extends TextureRect
class_name UIShovel

@onready var shovel: TextureRect = $Shovel

## 鼠标点击铲子
func _on_button_pressed() -> void:
	shovel.visible = false
	EventBus.push_event("main_game_click_shovel")

func ui_shovel_appear():
	shovel.visible = true

## 普通卡槽负责选择、重选与预选，所有内容统一使用卡牌引用。
extends Control
class_name CardSlotNorm

## 移动选卡时的临时挂载节点，防止卡片被原卡槽遮挡。
@onready var temporary_card: Control = $TemporaryCard
## 备选卡页面与返回容器的管理节点。
@onready var card_slot_candidate: CardSlotCandidate = $CardSlotCandidate
## 出战卡槽及阳光结算节点。
@onready var card_slot_battle: CardSlotBattle = $CardSlotBattle

## 使用 [param game_para] 初始化槽位、候选点击信号和不可取消的预选卡。
func init_card_slot_norm(game_para: ResourceLevelData) -> void:
	card_slot_battle.init_card_slot_battle(game_para.max_choosed_card_num, game_para.start_sun)
	# 候选容器按引用的完整选择键定位，模仿修饰决定点击处理方法。
	for container: CardCandidateContainer in card_slot_candidate.candidate_containers.values():
		if container.card.card_reference.is_imitater:
			container.card.signal_card_click.connect(_on_imitater_card_click)
		else:
			container.card.signal_card_click.connect(_on_card_click)
	if not game_para.prechosen_cards.is_empty():
		init_pre_choosed_card(game_para.prechosen_cards)

## 读取上次的统一选卡引用，只恢复仍可出战且存在于本次候选页的内容。
func _on_re_card_button_pressed() -> void:
	Global.save_service.load_selected_cards()
	# 上次选卡的引用只读，候选卡拥有自己的引用副本。
	for reference: ResourceCardReference in Global.global_game_state.selected_cards:
		if not AllCards.is_battle_card(reference):
			continue
		# 根据完整选择键同时区分普通植物和模仿植物。
		var container: CardCandidateContainer = card_slot_candidate.get_candidate(reference)
		if container == null or not container.visible or container.card.is_choosed_pre_card:
			continue
		if reference.is_imitater and card_slot_candidate.card_imitater.is_be_choosed_imitater:
			continue
		container.card._on_button_pressed()

## 倒序取消已选卡片；未连接点击信号的系统预选卡保持不变。
func _on_cancal_card_button_pressed() -> void:
	# 倒序取消避免移动后改变后续索引。
	for index: int in range(card_slot_battle.curr_cards.size() - 1, -1, -1):
		card_slot_battle.curr_cards[index]._on_button_pressed()

## 开始游戏并保存独立的选卡引用，由 SaveService 统一序列化。
func _on_texture_button_pressed() -> void:
	EventBus.push_event("card_slot_norm_start_game")
	Global.global_game_state.selected_cards.clear()
	# 保存引用副本，避免运行中的卡片修改影响持久化身份。
	for card: Card in card_slot_battle.curr_cards:
		Global.global_game_state.selected_cards.append(card.card_reference.copy_reference())
	Global.save_service.save_selected_cards()

## 按 [param references] 的顺序创建不可取消的预选卡；无效或未注册的出战引用不会进入卡槽。
func init_pre_choosed_card(references: Array[ResourceCardReference]) -> void:
	# 单个预选引用表示一个完整卡片，不再依赖两个补零数组的同下标组合。
	for reference: ResourceCardReference in references:
		if not AllCards.is_battle_card(reference):
			push_error("CardSlotNorm：预选卡必须是已注册的出战卡牌。")
			continue
		if card_slot_battle.curr_cards.size() >= card_slot_battle.cards_placeholder.size():
			break
		# 隐藏对应的候选卡，保持预选卡不可取消。
		var container: CardCandidateContainer = card_slot_candidate.get_candidate(reference)
		if container != null:
			container.card.visible = false
			container.card.is_choosed_pre_card = true
		# 实际出战卡是独立实例；开始战斗时再切换上下文。
		var card: Card = AllCards.create_card(reference, Card.CardContext.Selection)
		if card == null:
			continue
		card_slot_battle.curr_cards.append(card)
		pre_choosed_card(card, card_slot_battle.cards_placeholder[card_slot_battle.curr_cards.size() - 1])
		if reference.is_imitater:
			card_slot_candidate.imitater_be_choosed()
	card_disconnect_click_in_choose()

## 返回当前是否处于开局选卡或下一轮重选阶段。
func _is_choosing() -> bool:
	return Global.main_game.main_game_progress == MainGameManager.E_MainGameProgress.CHOOSE_CARD \
		or Global.main_game.main_game_progress == MainGameManager.E_MainGameProgress.RE_CHOOSE_CARD

## [param card] 的正常选择信号；只接纳具有出战能力的卡片。
func _on_card_click(card: Card) -> void:
	if not _is_choosing() or not AllCards.is_battle_card(card.card_reference):
		return
	SoundManager.play_other_SFX("tap")
	if card.is_choosed_pre_card:
		card.is_choosed_pre_card = false
		# 移除后从原位置开始将后续卡片向前移动。
		var card_index: int = card_slot_battle.curr_cards.find(card)
		card_slot_battle.curr_cards.erase(card)
		# 需要重新定位的出战卡索引。
		for index: int in range(card_index, card_slot_battle.curr_cards.size()):
			move_card_to(card_slot_battle.curr_cards[index], card_slot_battle.cards_placeholder[index])
		move_card_to(card, card.card_candidate_container)
	elif card_slot_battle.curr_cards.size() >= card_slot_battle.cards_placeholder.size():
		SoundManager.play_other_SFX("buzzer")
	else:
		card.is_choosed_pre_card = true
		card_slot_battle.curr_cards.append(card)
		move_card_to(card, card_slot_battle.cards_placeholder[card_slot_battle.curr_cards.size() - 1])

## [param card] 的模仿植物选择信号；独立入口本身不作为出战卡。
func _on_imitater_card_click(card: Card) -> void:
	if not _is_choosing() or not AllCards.is_battle_card(card.card_reference):
		return
	SoundManager.play_other_SFX("tap")
	if card.is_choosed_pre_card:
		card.is_choosed_pre_card = false
		# 原索引用于重新排列后续卡片。
		var card_index: int = card_slot_battle.curr_cards.find(card)
		card_slot_battle.curr_cards.erase(card)
		# 需要重新定位的出战卡索引。
		for index: int in range(card_index, card_slot_battle.curr_cards.size()):
			move_card_to(card_slot_battle.curr_cards[index], card_slot_battle.cards_placeholder[index])
		await move_card_to(card, card_slot_candidate.card_imitater)
		card.reparent(card.card_candidate_container, false)
		card_slot_candidate.imitater_be_choosed_cancel()
	elif card_slot_battle.curr_cards.size() >= card_slot_battle.cards_placeholder.size():
		SoundManager.play_other_SFX("buzzer")
		card_slot_candidate.imitater_card_slot_disappear()
	elif not card_slot_candidate.card_imitater.is_be_choosed_imitater:
		card.is_choosed_pre_card = true
		card_slot_battle.curr_cards.append(card)
		card.reparent(card_slot_candidate.card_imitater, false)
		move_card_to(card, card_slot_battle.cards_placeholder[card_slot_battle.curr_cards.size() - 1])
		card_slot_candidate.imitater_be_choosed()

## 将 [param card] 动画移动到 [param target_parent] 的全局位置，再重新挂载。
## 移动期间暂停按钮鼠标交互，耗时保持为 0.2 秒。
func move_card_to(card: Card, target_parent: Control) -> void:
	card.button.mouse_filter = Control.MOUSE_FILTER_IGNORE
	card.reparent(temporary_card)
	# 临时挂载后的移动动画。
	var tween: Tween = create_tween()
	tween.tween_property(card, "global_position", target_parent.global_position, 0.2)
	await tween.finished
	card.reparent(target_parent)
	card.button.mouse_filter = Control.MOUSE_FILTER_PASS

## 预选卡不连接选择处理；如存在已连接处理则解除，保持不可取消。
func card_disconnect_click_in_choose() -> void:
	# 系统预选卡不会恢复为候选卡。
	for card: Card in card_slot_battle.curr_cards:
		if card.signal_card_click.is_connected(_on_card_click):
			card.signal_card_click.disconnect(_on_card_click)
		if card.signal_card_click.is_connected(_on_imitater_card_click):
			card.signal_card_click.disconnect(_on_imitater_card_click)

## 将 [param card] 挂到 [param target_parent]；罐子模式仍保留原有零冷却规则。
func pre_choosed_card(card: Card, target_parent: Control) -> void:
	target_parent.add_child(card)
	card.position = Vector2.ZERO
	if Global.main_game.game_para.is_pot_mode:
		match card.card_reference.card_type:
			ResourceCardReference.CardType.Plant:
				if Global.global_read_data.zero_cd_plnat_card_type_on_pot_mode.has(card.card_reference.content_id):
					card.card_change_cool_time(0)
			ResourceCardReference.CardType.Zombie:
				card.card_change_cool_time(0)

## 根据 [param is_appeal] 显示或隐藏候选卡槽，等待原有 0.2 秒移动完成。
func move_card_slot_candidate(is_appeal: bool) -> void:
	# 候选卡槽位移动画。
	var tween: Tween = create_tween()
	tween.tween_property(card_slot_candidate, "position", Vector2(0, 89.0) if is_appeal else Vector2(0, 615.0), 0.2)
	await tween.finished

## 根据 [param is_appeal] 移动出战卡槽；[param appeal_time] 是动画耗时，单位秒。
func move_card_slot_battle(is_appeal: bool, appeal_time: float = 0.2) -> void:
	# 出战卡槽位移动画。
	var tween: Tween = create_tween()
	tween.tween_property(card_slot_battle, "position", Vector2(0, 0) if is_appeal else Vector2(0, -100.0), appeal_time)
	await tween.finished

extends PanelContainer
## 出战卡槽
class_name CardSlotBattle

@onready var curr_sun_value: Label = $SunLabelControl/CurrSunValue
@onready var card_placeholder_ori: TextureRect = $CardUiList/CardPlaceholder_ori
@onready var card_ui_list: HBoxContainer = $CardUiList
@onready var marker_2d_sun_target: Marker2D = %Marker2DSunTarget

## 出战卡槽占位节点
var cards_placeholder:Array = []
## 出战卡片
var curr_cards : Array[Card]
## 阳光值
var sun_value:
	set(value):
		sun_value = value
		curr_sun_value.text = str(value)

		for card in curr_cards:
			card.judge_sun_enough(value)

func _ready() -> void:
	Global.config_service.signal_change_disappear_spare_card_placeholder.connect(judge_disappear_add_card_bar)
	EventBus.subscribe("test_change_sun_value", func(value): sun_value = value)
	EventBus.subscribe("add_sun_value", func(value): sun_value+=value)
	EventBus.subscribe("update_card_purple_sun_cost", update_card_purple_sun_cost)


## 初始化出战卡槽，管理器调用
func init_card_slot_battle(max_choosed_card_num:int, sun:int):
	self.sun_value = sun
	for i in range(max_choosed_card_num):
		var cloned_card_placeholder = card_placeholder_ori.duplicate()
		card_ui_list.add_child(cloned_card_placeholder)

	card_placeholder_ori.free()		## 立即删除掉该节点，下面获取卡槽占位节点
	cards_placeholder = card_ui_list.get_children()
	## 更新阳光收集位置
	EventBus.push_event("update_marker_2d_sun_target", marker_2d_sun_target)

	return cards_placeholder

## 正式战斗时切换卡片上下文、检查费用并连接一次成功结算信号。
func main_game_refresh_card():
	update_card_purple_sun_cost()
	# 出战卡顺序决定快捷键位置。
	for i: int in range(curr_cards.size()):
		# 当前槽位卡片，统一确认出战能力后再按内容判断使用资格。
		var card: Card = curr_cards[i]
		if not AllCards.is_battle_card(card.card_reference):
			card.set_card_disable()
			continue
		card.card_context = Card.CardContext.Battle
		card.judge_sun_enough(sun_value)
		card.set_shortcut((i+1)%10)
		if not card.signal_card_use_end.is_connected(card_use_end):
			card.signal_card_use_end.connect(card_use_end)
	judge_disappear_add_card_bar()

## 下一轮重选前恢复选择上下文和冷却，解除本轮的使用结算。
func start_next_game_card_slot_battle_update():
	# 本轮保留的卡片顺序不变。
	for i: int in range(curr_cards.size()):
		# 需要恢复为选卡交互的卡片。
		var card: Card = curr_cards[i]
		card.card_context = Card.CardContext.Selection
		## 卡牌冷却结束,可以点击
		card.set_card_cool_end()
		card.card_ready()
		card.set_shortcut_disappear()
		if card.signal_card_use_end.is_connected(card_use_end):
			card.signal_card_use_end.disconnect(card_use_end)

## [param card] 成功使用后扣除当前阳光价格，并开始原有冷却。
func card_use_end(card:Card):
	## 减少阳光，卡片冷却
	sun_value = sun_value - card.sun_cost
	card.card_cool()

#region 控制台相关
## 是否显示多余卡槽
func judge_disappear_add_card_bar():
	## 在游戏进行阶段
	if Global.main_game.main_game_progress == MainGameManager.E_MainGameProgress.MAIN_GAME:
		if Global.config_service.disappear_spare_card_Placeholder:
			if curr_cards.size() < cards_placeholder.size():
				for i in range(curr_cards.size(), cards_placeholder.size()):
					cards_placeholder[i].visible = false
		else:
			for i in range(cards_placeholder.size()):
				cards_placeholder[i].visible = true
	else:
		for i in range(cards_placeholder.size()):
			cards_placeholder[i].visible = true

#endregion

## 植物数量变化一帧后刷新植物紫卡价格，普通僵尸及僵王不查询植物计数。
func update_card_purple_sun_cost():
	await get_tree().process_frame
	# 本次仍在槽中的卡片。
	for card: Card in curr_cards:
		if card.card_reference.card_type != ResourceCardReference.CardType.Plant:
			continue
		# 紫卡的植物内容编号，用于查询本关同种植物数量。
		var plant_type: int = card.card_reference.content_id
		if card.is_purple_card and Global.main_game.plant_cell_manager.curr_plant_num.has(plant_type):
			card.sun_cost = Global.character_registry.get_plant_info(plant_type, CharacterRegistry.PlantInfoAttribute.SunCost) + 50 * Global.main_game.plant_cell_manager.curr_plant_num[plant_type]
			card.judge_sun_enough(sun_value)

## 按目录顺序生成植物、普通僵尸、僵王及植物模仿卡页面，按可用角色列表筛选。
extends TextureRect
class_name CardSlotCandidate

## 普通备选页面的挂载节点。
@onready var all_card_page: Control = $AllCardPage
## 植物页面的占位布局模板。
@onready var grid_container_plant: GridContainer = $AllCardPage/GridContainerPlant
## 普通僵尸和僵王共用的占位布局模板。
@onready var grid_container_zombie: GridContainer = $AllCardPage/GridContainerZombie
## 类型、内容和模仿修饰共同确定的备选容器索引。
var candidate_containers: Dictionary[Vector3i, CardCandidateContainer] = {}
## 至少有一张已解锁卡的普通页面。
var all_show_page: Array[GridContainer] = []
## 普通页面的零起点页码。
var curr_page: int = 0
## 普通页面的页码标签。
@onready var label_page: Label = $LabelPage
## 模仿者选择弹层。
@onready var all_imitater_card: Control = %AllImitaterCard
## 模仿卡页面的挂载节点。
@onready var all_card_page_imitater: Control = $AllImitaterCard/Panel/AllCardPageImitater
## 模仿卡页面的占位布局模板。
@onready var grid_container_plant_imitater: GridContainer = $AllImitaterCard/Panel/AllCardPageImitater/GridContainerPlantImitater
## 独立模仿者入口，只负责打开弹层，不用于出战。
@onready var card_imitater: CardImitater = $ImitaterBG/CardImitater
## 至少有一张已解锁卡的模仿卡页面。
var all_show_page_imitater: Array[GridContainer] = []
## 模仿卡页面的零起点页码。
var curr_page_imitater: int = 0

## 根据目录稳定顺序分页，仅展示包含已解锁内容的页面。
func _ready() -> void:
	_create_candidate_pages(ResourceCardReference.CardType.Plant, grid_container_plant, all_card_page)
	_create_candidate_pages(ResourceCardReference.CardType.Zombie, grid_container_zombie, all_card_page)
	_create_candidate_pages(ResourceCardReference.CardType.Plant, grid_container_plant_imitater, all_card_page_imitater, true)
	if not all_show_page.is_empty():
		all_show_page[0].visible = true
	if not all_show_page_imitater.is_empty():
		all_show_page_imitater[0].visible = true
	label_page.text = "1/" + str(all_show_page.size()) if not all_show_page.is_empty() else "0/0"
	card_imitater.signal_card_click.connect(imitater_card_slot_appear)

## 使用 [param card_type] 的目录顺序复制 [param grid_template] 到 [param page_root]。
## [param imitate] 为 true 时为植物创建模仿修饰，不修改目录共享引用。
## 普通僵尸页末尾追加僵王目录，各引用保留自身类别，不受关卡自动出场类型影响。
func _create_candidate_pages(card_type: int, grid_template: GridContainer, page_root: Control, imitate: bool = false) -> void:
	# 页面容量沿用场景占位，内容编号不再承担布局索引。
	var page_capacity: int = grid_template.get_child_count()
	if page_capacity <= 0:
		push_error("CardSlotCandidate：备选页面缺少卡片占位。")
		return
	page_root.remove_child(grid_template)
	# 本批生成的页，顺序与目录顺序一致。
	var pages: Array[GridContainer] = []
	# 有效出战卡的连续布局索引，跳过独立模仿者入口。
	var card_index: int = 0
	# 本批分页的有序目录引用，僵王复用普通僵尸页面布局。
	var page_references: Array[ResourceCardReference] = AllCards.get_references(card_type)
	if card_type == ResourceCardReference.CardType.Zombie:
		page_references.append_array(AllCards.get_references(ResourceCardReference.CardType.ZombieBoss))
	# 当前源引用只读使用，混合页面也保留真实内容类别。
	for catalog_reference: ResourceCardReference in page_references:
		if not AllCards.is_battle_card(catalog_reference):
			continue
		# 模仿修饰只写入新引用。
		var reference: ResourceCardReference = catalog_reference.copy_reference()
		if imitate:
			reference.is_imitater = true
		# 当前卡片所属的零起点页；浮点除法后显式向下取整，保留分页规则。
		var page_index: int = floori(float(card_index) / page_capacity)
		if page_index >= pages.size():
			# 新页保留模板中的栅格占位，首次生成时先隐藏。
			var new_page: GridContainer = grid_template.duplicate() as GridContainer
			new_page.visible = false
			page_root.add_child(new_page)
			pages.append(new_page)
		# 卡片与占位分别保存引用，选择时仍可返回原位。
		var new_card: Card = AllCards.create_card(reference, Card.CardContext.Selection)
		if new_card == null:
			continue
		# 每张卡片对应的背景与返回位置。
		var container: CardCandidateContainer = SceneRegistry.CARD_CANDIDATE_CONTAINER.instantiate()
		container.init_card_in_seed_chooser(new_card)
		pages[page_index].get_child(card_index % page_capacity).add_child(container)
		container.visible = _is_unlocked(reference)
		candidate_containers[reference.get_selection_key()] = container
		card_index += 1
	# 只将含可见卡片的页面加入翻页范围。
	for page: GridContainer in pages:
		# 本页是否存在可展示的已解锁内容。
		var has_visible_card: bool = false
		# 场景中的单卡占位节点。
		for placeholder: Node in page.get_children():
			if placeholder.get_child_count() > 0 and (placeholder.get_child(0) as Control).visible:
				has_visible_card = true
				break
		if has_visible_card:
			if imitate:
				all_show_page_imitater.append(page)
			else:
				all_show_page.append(page)
	grid_template.queue_free()

## 返回 [param reference] 是否存在于对应类别的当前可用角色列表。
func _is_unlocked(reference: ResourceCardReference) -> bool:
	match reference.card_type:
		ResourceCardReference.CardType.Plant:
			return Global.global_game_state.curr_plant.has(reference.content_id)
		ResourceCardReference.CardType.Zombie:
			return Global.global_game_state.curr_zombie.has(reference.content_id)
		ResourceCardReference.CardType.ZombieBoss:
			return Global.global_game_state.curr_zombie_boss.has(reference.content_id)
	return false

## 查询 [param reference] 对应的普通或模仿卡容器，未生成内容返回 null。
func get_candidate(reference: ResourceCardReference) -> CardCandidateContainer:
	if reference == null:
		return null
	return candidate_containers.get(reference.get_selection_key()) as CardCandidateContainer

## 显示普通备选卡的上一页。
func _on_last_page_button_pressed() -> void:
	change_page(-1)

## 显示普通备选卡的下一页。
func _on_next_page_button_pressed() -> void:
	change_page(1)

## 按 [param change_num] 循环切换普通页面；空集合不执行切换。
func change_page(change_num: int = 1) -> void:
	if all_show_page.is_empty():
		return
	all_show_page[curr_page].visible = false
	curr_page = posmod(curr_page + change_num, all_show_page.size())
	all_show_page[curr_page].visible = true
	label_page.text = str(curr_page + 1) + "/" + str(all_show_page.size())

## [param _card] 是入口点击信号携带的卡片；仅打开模仿卡弹层。
func imitater_card_slot_appear(_card: Card) -> void:
	all_imitater_card.visible = true

## 关闭模仿卡弹层。
func imitater_card_slot_disappear() -> void:
	all_imitater_card.visible = false

## 真实模仿卡选中后关闭弹层并锁定独立入口。
func imitater_be_choosed() -> void:
	imitater_card_slot_disappear()
	card_imitater.imitater_card_be_choosed()

## 取消真实模仿卡后恢复独立入口。
func imitater_be_choosed_cancel() -> void:
	card_imitater.imitater_card_be_choosed_cancal()

## 显示模仿卡的上一页。
func _on_imitater_last_page_button_pressed() -> void:
	change_page_imitater(-1)

## 显示模仿卡的下一页。
func _on_imitater_next_page_button_pressed() -> void:
	change_page_imitater(1)

## 按 [param change_num] 循环切换模仿卡页面；没有解锁内容时不切换。
func change_page_imitater(change_num: int = 1) -> void:
	if all_show_page_imitater.is_empty():
		return
	all_show_page_imitater[curr_page_imitater].visible = false
	curr_page_imitater = posmod(curr_page_imitater + change_num, all_show_page_imitater.size())
	all_show_page_imitater[curr_page_imitater].visible = true

