import 'package:animal_chess/models/player_color.dart';
import 'package:animal_chess/models/position.dart';

class BoardConstants {
  static const int columns = 7;
  static const int rows = 9;

  // Dens positions
  static const Map<PlayerColor, Position> dens = {
    PlayerColor.green: Position(3, 0),
    PlayerColor.red: Position(3, 8),
  };

  // Traps positions
  static const Map<PlayerColor, List<Position>> traps = {
    PlayerColor.green: [Position(2, 0), Position(4, 0), Position(3, 1)],
    PlayerColor.red: [Position(2, 8), Position(4, 8), Position(3, 7)],
  };

  // Rivers positions
  static const List<Position> rivers = [
    // Left river (2x3 area)
    Position(1, 3), Position(1, 4), Position(1, 5),
    Position(2, 3), Position(2, 4), Position(2, 5),
    // Right river (2x3 area)
    Position(4, 3), Position(4, 4), Position(4, 5),
    Position(5, 3), Position(5, 4), Position(5, 5),
  ];
}

import 'package:animal_chess/models/animal_type.dart';
import 'package:animal_chess/models/game_board.dart';
import 'package:animal_chess/models/player_color.dart';
import 'package:animal_chess/models/position.dart';
import 'package:animal_chess/models/piece.dart';
import 'package:animal_chess/models/game_config.dart';
import 'package:animal_chess/game/game_rules.dart';
import 'package:animal_chess/constants/board_constants.dart';
import 'package:logging/logging.dart';

class GameActions {
  final Logger _logger = Logger('GameActions');
  final GameBoard board;
  final GameConfig gameConfig;
  PlayerColor currentPlayer = PlayerColor.red;
  Position? selectedPosition;
  bool gameEnded = false;
  PlayerColor? winner;
  List<Piece> capturedPieces = []; // List to track captured pieces
  final GameRules gameRules;

  GameActions({
    required this.board,
    required this.gameConfig,
    required this.gameRules,
  });

  /// Move a piece
  bool movePiece(Position from, Position to) {
    if (gameEnded) {
      _logger.fine("Game ended, cannot move piece.");
      return false;
    }

    if (!gameRules.isValidMove(from, to, currentPlayer)) {
      _logger.fine("Invalid move from $from to $to for $currentPlayer.");
      return false;
    }

    Piece? piece = board.getPiece(from);
    if (piece == null) {
      _logger.fine("No piece at $from.");
      return false;
    }

    Piece? targetPiece = board.getPiece(to);

    // Check win condition: entering opponent's den
    if (board.isOpponentDen(to, currentPlayer)) {
      // With rat-only variant, only rat can win by entering den
      if (gameConfig.ratOnlyDenEntry && piece.animalType != AnimalType.rat) {
        _logger.fine(
          "Rat-only den entry variant enabled, non-rat piece cannot win.",
        );
        return false; // Not a valid win under this variant
      } else {
        // Valid win
        board.movePiece(from, to);
        winner = currentPlayer;
        gameEnded = true;
        _logger.info("$currentPlayer wins by entering opponent's den!");
        return true;
      }
    }

    // Capture opponent piece
    if (targetPiece != null) {
      board.removePiece(to);
      capturedPieces.add(targetPiece);
      _logger.info(
        "$currentPlayer's ${piece.animalType} captured $targetPiece.",
      );
    }

    // Move the piece
    board.movePiece(from, to);
    _logger.fine("$currentPlayer moved ${piece.animalType} from $from to $to.");

    // Check if game has ended (capture all pieces)
    winner = board.getWinner();
    if (winner != null) {
      gameEnded = true;
      _logger.info("$winner wins by capturing all opponent pieces!");
    }

    switchPlayer();
    _logger.fine("Switched player to $currentPlayer.");
    return true;
  }

  /// Switch to the next player
  void switchPlayer() {
    currentPlayer = currentPlayer == PlayerColor.green
        ? PlayerColor.red
        : PlayerColor.green;
  }

  /// Get valid moves for a selected piece
  List<Position> getValidMoves(Position from, [PlayerColor? player]) {
    final effectivePlayer = player ?? currentPlayer;
    if (board.getPiece(from)?.playerColor != effectivePlayer) {
      _logger.fine("No piece or not current player's piece at $from.");
      return [];
    }

    List<Position> validMoves = [];
    for (int col = 0; col < BoardConstants.columns; col++) {
      for (int row = 0; row < BoardConstants.rows; row++) {
        Position to = Position(col, row);
        if (gameRules.isValidMove(from, to, effectivePlayer)) {
          validMoves.add(to);
        }
      }
    }
    _logger.fine("Found ${validMoves.length} valid moves for piece at $from.");
    return validMoves;
  }

  /// Reset the game
  void resetGame() {
    board.initializeDefaultBoard();
    currentPlayer = PlayerColor.red;
    selectedPosition = null;
    gameEnded = false;
    winner = null;
    capturedPieces.clear();
    _logger.info("Game reset.");
  }

  /// Create a copy of GameActions with a new board
  GameActions copyWithBoard(GameBoard newBoard) {
    return GameActions(
        board: newBoard,
        gameConfig: gameConfig,
        gameRules: gameRules,
      )
      ..currentPlayer = currentPlayer
      ..selectedPosition = selectedPosition
      ..gameEnded = gameEnded
      ..winner = winner
      ..capturedPieces = List.from(capturedPieces);
  }
}

import 'package:flutter/foundation.dart';
import 'package:animal_chess/models/game_board.dart';
import 'package:animal_chess/models/player_color.dart';
import 'package:animal_chess/models/position.dart';
import 'package:animal_chess/models/piece.dart';
import 'package:animal_chess/models/game_config.dart';
import 'package:animal_chess/game/game_rules.dart';
import 'package:animal_chess/game/game_actions.dart';
import 'package:animal_chess/ai/ai_strategy.dart';
import 'package:animal_chess/ai/ml_strategy.dart';
import 'package:animal_chess/ai/animal_chess_network.dart';
import 'package:animal_chess/ai/ai_move.dart';
import 'package:logging/logging.dart';

class GameController {
  bool isActive = true;
  final Logger _logger = Logger('GameController');
  final GameBoard board;
  PlayerColor currentPlayer = PlayerColor.red; // Red goes first
  Position? selectedPosition;
  bool gameEnded = false;
  PlayerColor? winner;
  List<Piece> capturedPieces = []; // List to track captured pieces

  final GameConfig gameConfig;
  final GameRules gameRules;
  final GameActions gameActions;

  // Callback for when the game state changes
  VoidCallback? onGameStateChanged;

  GameController({
    required this.board,
    required this.gameRules,
    required this.gameActions,
    required this.gameConfig,
  }) : currentPlayer = PlayerColor.red;

  bool movePiece(Position toPosition) {
    bool moved = false;
    if (selectedPosition != null) {
      moved = gameActions.movePiece(selectedPosition!, toPosition);
      if (moved) {
        selectedPosition = null;
        currentPlayer = gameActions.currentPlayer;
        gameEnded = gameActions.gameEnded;
        winner = gameActions.winner;
        // Notify that game state has changed
        onGameStateChanged?.call();
      }
    }
    return moved;
  }

  /// Execute AI move if it's an AI player's turn
  void executeAIMoveIfNecessary() {
    _executeAIMoveIfNecessaryInternal(0);
  }

  /// Internal implementation of AI move execution with safety counter
  void _executeAIMoveIfNecessaryInternal(int safetyCounter) {
    if (!isActive || gameEnded) return;
    _logger.fine(
      "Checking AI move: current player=$currentPlayer, "
      "aiGreen=${gameConfig.aiGreen}, aiRed=${gameConfig.aiRed}",
    );

    const maxMoves = 50; // Maximum number of AI moves in a chain

    // Check if we should execute an AI move
    if (((currentPlayer == PlayerColor.green && gameConfig.aiGreen) ||
            (currentPlayer == PlayerColor.red && gameConfig.aiRed)) &&
        safetyCounter < maxMoves) {
      _logger.info(
        "Executing AI move for $currentPlayer (chain: ${safetyCounter + 1})",
      );
      _executeSingleAIMove();

      // Notify that game state has changed after each AI move
      onGameStateChanged?.call();

      // Check if we should continue with another AI move
      if (((currentPlayer == PlayerColor.green && gameConfig.aiGreen) ||
              (currentPlayer == PlayerColor.red && gameConfig.aiRed)) &&
          !gameEnded &&
          safetyCounter + 1 < maxMoves) {
        // Wait for 1 second before continuing with the next move
        Future.delayed(const Duration(seconds: 1), () {
          // Continue with the next move after the delay only if still active and AI enabled
          if (isActive &&
              !gameEnded &&
              ((currentPlayer == PlayerColor.green && gameConfig.aiGreen) ||
                  (currentPlayer == PlayerColor.red && gameConfig.aiRed))) {
            _logger.fine("Continuing with next AI move after delay");
            _executeAIMoveIfNecessaryInternal(safetyCounter + 1);
          } else {
            _logger.fine("Skipping delayed AI move - conditions no longer met");
          }
        });
      } else {
        // No more moves to execute
        if (safetyCounter + 1 >= maxMoves) {
          _logger.warning("AI move chain limit reached ($maxMoves moves)");
        } else {
          _logger.fine(
            "AI move execution completed. Total moves: ${safetyCounter + 1}",
          );
        }
      }
    } else {
      // No AI move to execute
      if (safetyCounter > 0) {
        _logger.fine(
          "AI move execution completed. Total moves: $safetyCounter",
        );
      }
    }
  }

  /// Execute a single AI move
  void _executeSingleAIMove() {
    if (!isActive ||
        (currentPlayer == PlayerColor.green && !gameConfig.aiGreen) ||
        (currentPlayer == PlayerColor.red && !gameConfig.aiRed)) {
      return;
    }

    Move? bestMove;

    // Check if ML strategy is selected
    if (currentPlayer == PlayerColor.green && gameConfig.aiGreenStrategy == AIStrategyType.machineLearning) {
      // Use ML strategy
      final network = AnimalChessNetwork(); // Initialize the ML network
      final mlStrategy = MlStrategy(
        network: network,
        rules: gameActions.gameRules,
      );
      bestMove = mlStrategy.selectMove(board, currentPlayer);
    } else if (currentPlayer == PlayerColor.red && gameConfig.aiRedStrategy == AIStrategyType.machineLearning) {
      // Use ML strategy
      final network = AnimalChessNetwork(); // Initialize the ML network
      final mlStrategy = MlStrategy(
        network: network,
        rules: gameActions.gameRules,
      );
      bestMove = mlStrategy.selectMove(board, currentPlayer);
    } else {
      // Use traditional AIStrategy
      final ai = AIStrategy(gameConfig, gameActions);
      bestMove = ai.calculateBestMove(board, currentPlayer, gameActions);
    }

    if (bestMove != null) {
      // Set the selected position first
      selectedPosition = bestMove.from;
      // Execute the move
      gameActions.movePiece(bestMove.from, bestMove.to);
      // Update controller state
      selectedPosition = null;
      currentPlayer = gameActions.currentPlayer;
      gameEnded = gameActions.gameEnded;
      winner = gameActions.winner;
    }
  }

  List<Position> getValidMoves(Position fromPosition) {
    return gameActions.getValidMoves(fromPosition, currentPlayer);
  }

  void resetGame() {
    gameActions.resetGame();
    // Update GameController's state from GameActions after reset

    currentPlayer = gameActions.currentPlayer;
    selectedPosition = null;
    gameEnded = gameActions.gameEnded;
    winner = gameActions.winner;
    capturedPieces = gameActions.capturedPieces;

    // Notify that game state has changed
    onGameStateChanged?.call();
  }

  /// Select a piece to move
  bool selectPiece(Position position) {
    if (gameEnded) return false;

    Piece? piece = board.getPiece(position);

    // Can only select own pieces
    if (piece == null || piece.playerColor != currentPlayer) {
      selectedPosition = null;
      return false;
    }

    selectedPosition = position;
    return true;
  }

  /// Check if a move is valid
  bool isValidMove(Position from, Position to) {
    return gameRules.isValidMove(from, to, currentPlayer);
  }

  /// Force a player to win (for debugging/testing)
  void forceWin(PlayerColor player) {
    gameEnded = true;
    winner = player;
    currentPlayer = player;
  }
}

import 'package:animal_chess/models/game_board.dart';
import 'package:animal_chess/models/piece.dart';
import 'package:animal_chess/models/player_color.dart';
import 'package:animal_chess/models/position.dart';
import 'package:animal_chess/models/game_config.dart';
import 'package:animal_chess/game/rules/game_rule_variant.dart';
import 'package:animal_chess/game/rules/game_rule_factory.dart';
import 'package:logging/logging.dart';

class GameRules {
  final GameBoard board;
  final GameConfig gameConfig;
  final GameRuleVariant ruleVariant;
  final Logger _logger = Logger('GameRules');

  GameRules({required this.board, required this.gameConfig})
    : ruleVariant = GameRuleFactory.createRuleVariant(gameConfig);

  /// Check if a move is valid
  bool isValidMove(Position from, Position to, PlayerColor currentPlayer) {
    _logger.fine(
      "isValidMove: from=$from, to=$to, currentPlayer=$currentPlayer",
    );
    Piece? piece = board.getPiece(from);
    _logger.fine("Piece at from: $piece");
    if (piece == null || piece.playerColor != currentPlayer) {
      _logger.fine("Invalid: piece is null or not current player's");
      return false;
    }

    // Can't move to own den
    if (!ruleVariant.canMoveToDen(to, currentPlayer, board, gameConfig)) {
      _logger.fine("Invalid: moving to own den");
      return false;
    }

    Piece? targetPiece = board.getPiece(to);
    _logger.fine("Target piece at to: $targetPiece");

    // Can't capture own pieces
    if (targetPiece != null && targetPiece.playerColor == currentPlayer) {
      _logger.fine("Invalid: capturing own piece");
      return false;
    }

    // Check if it's a jump move
    if (ruleVariant.canJumpOverRiver(from, to, piece, board, gameConfig)) {
      _logger.fine("Is a jump move");
      // If it's a jump, the 'to' position must be empty or contain a capturable piece
      if (targetPiece == null) {
        _logger.fine("Valid jump: target empty");
        return true;
      } else {
        _logger.fine("Valid jump: target capturable");
        return ruleVariant.canCapture(
          piece,
          targetPiece,
          to,
          board,
          gameConfig,
        );
      }
    }

    // If not a jump move, check if it's an adjacent move
    List<Position> adjacent = from.adjacentPositions;
    _logger.fine("Adjacent positions: $adjacent");
    if (!adjacent.contains(to)) {
      _logger.fine("Invalid: not adjacent and not a jump");
      return false; // Not adjacent and not a jump, so invalid
    }

    // Special rules for river entry (for adjacent moves)
    if (board.isRiver(to)) {
      _logger.fine("Moving to river");
      if (!ruleVariant.canEnterRiver(piece, to, board, gameConfig)) {
        _logger.fine("Invalid: piece cannot enter river");
        return false;
      }
    }

    // Check capture rules for adjacent moves
    if (targetPiece != null) {
      _logger.fine("Target piece exists, checking capture rules");
      if (!ruleVariant.canCapture(piece, targetPiece, to, board, gameConfig)) {
        _logger.fine("Invalid: cannot capture target piece");
        return false;
      }
    }

    _logger.fine("Valid adjacent move");
    return true;
  }
}

import 'package:animal_chess/game/rules/game_rule_variant.dart';
import 'package:animal_chess/game/rules/standard_game_rule_variant.dart';
import 'package:animal_chess/game/rules/variants/dog_river_variant.dart';
import 'package:animal_chess/game/rules/variants/rat_capture_variant.dart';
import 'package:animal_chess/game/rules/variants/extended_jump_variant.dart';
import 'package:animal_chess/models/game_config.dart';

/// Factory class to create game rule variants based on game configuration
class GameRuleFactory {
  /// Create a game rule variant based on the game configuration
  static GameRuleVariant createRuleVariant(GameConfig gameConfig) {
    // Start with the standard rules
    GameRuleVariant variant = StandardGameRuleVariant();

    // Apply variants in a specific order
    // Note: The order matters as some variants may depend on others
    if (gameConfig.extendedLionTigerJumps) {
      variant = ExtendedJumpVariant(variant);
    }

    if (gameConfig.ratCannotCaptureElephant) {
      variant = RatCaptureVariant(variant);
    }

    if (gameConfig.dogRiverVariant) {
      variant = DogRiverVariant(variant);
    }

    return variant;
  }
}

import 'package:animal_chess/models/game_board.dart';
import 'package:animal_chess/models/piece.dart';
import 'package:animal_chess/models/player_color.dart';
import 'package:animal_chess/models/position.dart';
import 'package:animal_chess/models/game_config.dart';

/// Base interface for game rule variants
abstract class GameRuleVariant {
  /// Check if a piece can enter a river position
  bool canEnterRiver(
    Piece piece,
    Position to,
    GameBoard board,
    GameConfig gameConfig,
  );

  /// Check if a piece can capture another piece
  bool canCapture(
    Piece attacker,
    Piece target,
    Position to,
    GameBoard board,
    GameConfig gameConfig,
  );

  /// Check if a piece can jump over a river
  bool canJumpOverRiver(
    Position from,
    Position to,
    Piece piece,
    GameBoard board,
    GameConfig gameConfig,
  );

  /// Check if a move to a den is valid
  bool canMoveToDen(
    Position to,
    PlayerColor currentPlayer,
    GameBoard board,
    GameConfig gameConfig,
  );
}

import 'package:animal_chess/game/rules/game_rule_variant.dart';
import 'package:animal_chess/models/animal_type.dart';
import 'package:animal_chess/models/game_board.dart';
import 'package:animal_chess/models/piece.dart';
import 'package:animal_chess/models/player_color.dart';
import 'package:animal_chess/models/position.dart';
import 'package:animal_chess/models/game_config.dart';
import 'package:animal_chess/constants/game_constants.dart';

/// Standard implementation of game rules (core rules without any variants)
class StandardGameRuleVariant implements GameRuleVariant {
  @override
  bool canEnterRiver(
    Piece piece,
    Position to,
    GameBoard board,
    GameConfig gameConfig,
  ) {
    // In standard rules, only rats can enter rivers
    return piece.animalType == AnimalType.rat;
  }

  @override
  bool canCapture(
    Piece attacker,
    Piece target,
    Position to,
    GameBoard board,
    GameConfig gameConfig,
  ) {
    // Pieces in traps can be captured by any opponent piece
    if (board.isTrap(to)) {
      return target.playerColor != attacker.playerColor;
    }

    // Normal capture rules
    return attacker.canCapture(target);
  }

  @override
  bool canJumpOverRiver(
    Position from,
    Position to,
    Piece piece,
    GameBoard board,
    GameConfig gameConfig,
  ) {
    // Only lion and tiger can jump in standard rules
    if (piece.animalType != AnimalType.lion &&
        piece.animalType != AnimalType.tiger) {
      return false;
    }

    int distance;

    // Check horizontal jump (left or right)
    if (from.row == to.row) {
      distance = (from.column - to.column).abs();
      // Standard horizontal jump for Lion/Tiger (over 2 river cells)
      if (distance == GameConstants.lionTigerHorizontalJumpDistance) {
        Position river1 = Position(
          from.column + (to.column > from.column ? 1 : -1),
          from.row,
        );
        Position river2 = Position(
          from.column + (to.column > from.column ? 2 : -2),
          from.row,
        );
        if (board.isRiver(river1) && board.isRiver(river2)) {
          Piece? rat1 = board.getPiece(river1);
          Piece? rat2 = board.getPiece(river2);
          if ((rat1 != null && rat1.animalType == AnimalType.rat) ||
              (rat2 != null && rat2.animalType == AnimalType.rat)) {
            return false;
          }
          return true;
        }
      }
    }
    // Check vertical jump (up or down)
    else if (from.column == to.column) {
      distance = (from.row - to.row).abs();
      // Standard vertical jump for Lion/Tiger (over 3 river cells)
      if (distance == 4) {
        // Tiger needs to jump 4 rows (from row 2 to 6)
        Position river1 = Position(
          from.column,
          from.row + (to.row > from.row ? 1 : -1),
        );
        Position river2 = Position(
          from.column,
          from.row + (to.row > from.row ? 2 : -2),
        );
        Position river3 = Position(
          from.column,
          from.row + (to.row > from.row ? 3 : -3),
        );
        if (board.isRiver(river1) &&
            board.isRiver(river2) &&
            board.isRiver(river3)) {
          Piece? rat1 = board.getPiece(river1);
          Piece? rat2 = board.getPiece(river2);
          Piece? rat3 = board.getPiece(river3);
          if ((rat1 != null && rat1.animalType == AnimalType.rat) ||
              (rat2 != null && rat2.animalType == AnimalType.rat) ||
              (rat3 != null && rat3.animalType == AnimalType.rat)) {
            return false;
          }
          return true;
        }
      }
    }

    return false;
  }

  @override
  bool canMoveToDen(
    Position to,
    PlayerColor currentPlayer,
    GameBoard board,
    GameConfig gameConfig,
  ) {
    // Can't move to own den
    return !board.isOwnDen(to, currentPlayer);
  }
}

