import 'package:animal_chess/models/animal_type.dart';
import 'package:animal_chess/models/player_color.dart';
import 'package:animal_chess/models/position.dart';
import 'package:animal_chess/models/piece.dart';
import 'package:animal_chess/constants/board_constants.dart';
import 'package:animal_chess/constants/game_constants.dart';
import 'package:logging/logging.dart';

class GameBoard {
  final Logger _logger = Logger('GameBoard');

  // Board state
  final Map<Position, Piece?> _board = {};

  // Special positions
  final Map<PlayerColor, Position> dens = BoardConstants.dens;

  final Map<PlayerColor, List<Position>> traps = BoardConstants.traps;

  final List<Position> rivers = BoardConstants.rivers;

  GameBoard() {
    initializeDefaultBoard();
  }

  // Named constructor for an empty board
  GameBoard.empty();

  /// Initialize the board with pieces in their starting positions
  void initializeDefaultBoard() {
    // Clear the board
    clearBoard();

    // Place pieces based on GameConstants
    GameConstants.pieceStartPositions.forEach((playerColor, pieces) {
      pieces.forEach((animalType, position) {
        _board[position] = Piece(animalType, playerColor);
      });
    });
  }

  /// Get the piece at a specific position
  Piece? getPiece(Position position) {
    return _board[position];
  }

  /// Set a piece at a specific position
  void setPiece(Position position, Piece? piece) {
    if (position.isValid) {
      _board[position] = piece;
    }
  }

  /// Move a piece from one position to another
  bool movePiece(Position from, Position to) {
    if (!from.isValid || !to.isValid) return false;

    Piece? piece = _board[from];
    if (piece == null) return false;

    _board[to] = piece;
    _board[from] = null;
    return true;
  }

  /// Remove a piece from the board
  void removePiece(Position position) {
    _board[position] = null;
  }

  /// Clear all pieces from the board
  void clearBoard() {
    for (int col = 0; col < BoardConstants.columns; col++) {
      for (int row = 0; row < BoardConstants.rows; row++) {
        _board[Position(col, row)] = null;
      }
    }
  }

  void dumpBoardAndChessPieces() {
    _logger.fine("""Board State (R=Red, G=Green, 0=River):""");
    for (int row = 0; row < BoardConstants.rows; row++) {
      String rowString = "";
      for (int col = 0; col < BoardConstants.columns; col++) {
        Position currentPosition = Position(col, row);
        Piece? piece = getPiece(currentPosition);
        if (piece != null) {
          String pieceChar;
          switch (piece.animalType) {
            case AnimalType.elephant:
              pieceChar = "E";
              break;
            case AnimalType.lion:
              pieceChar = "L";
              break;
            case AnimalType.tiger:
              pieceChar = "T";
              break;
            case AnimalType.leopard:
              pieceChar =
                  "P"; // Using P for Leopard to avoid conflict with Lion
              break;
            case AnimalType.wolf:
              pieceChar = "W";
              break;
            case AnimalType.dog:
              pieceChar = "D";
              break;
            case AnimalType.cat:
              pieceChar = "C";
              break;
            case AnimalType.rat:
              pieceChar = "R";
              break;
          }
          if (piece.playerColor == PlayerColor.red) {
            rowString += "${pieceChar.toUpperCase()} ";
          } else {
            rowString += "${pieceChar.toLowerCase()} ";
          }
        } else if (isRiver(currentPosition)) {
          rowString += "0 ";
        } else if (isTrap(currentPosition)) {
          rowString += "X "; // 'X' for trap
        } else if (isDen(currentPosition)) {
          rowString += "H "; // 'H' for den (home)
        } else {
          rowString += "- ";
        }
      }
      _logger.fine(rowString);
    }
  }

  /// Check if a position is a den
  bool isDen(Position position) {
    return dens.values.contains(position);
  }

  /// Check if a position is a trap
  bool isTrap(Position position) {
    return traps[PlayerColor.green]!.contains(position) ||
        traps[PlayerColor.red]!.contains(position);
  }

  /// Check if a position is in the river
  bool isRiver(Position position) {
    return rivers.contains(position);
  }

  /// Get the owner of a den or trap (null if not a den or trap)
  PlayerColor? getZoneOwner(Position position) {
    if (dens[PlayerColor.green] == position) return PlayerColor.green;
    if (dens[PlayerColor.red] == position) return PlayerColor.red;

    if (traps[PlayerColor.green]!.contains(position)) return PlayerColor.green;
    if (traps[PlayerColor.red]!.contains(position)) return PlayerColor.red;

    return null;
  }

  /// Check if a position is the player's own den
  bool isOwnDen(Position position, PlayerColor player) {
    return dens[player] == position;
  }

  /// Check if a position is the opponent's den
  bool isOpponentDen(Position position, PlayerColor player) {
    PlayerColor opponent = player == PlayerColor.green
        ? PlayerColor.red
        : PlayerColor.green;
    return dens[opponent] == position;
  }

  /// Get all pieces of a specific player
  Map<Position, Piece> getPlayerPieces(PlayerColor player) {
    Map<Position, Piece> playerPieces = {};
    _board.forEach((position, piece) {
      if (piece != null && piece.playerColor == player) {
        playerPieces[position] = piece;
      }
    });
    return playerPieces;
  }

  /// Check if the game has a winner
  PlayerColor? getWinner() {
    // Check if any piece is in the opponent's den
    Piece? greenPieceInRedDen = _board[dens[PlayerColor.red]!];
    if (greenPieceInRedDen != null &&
        greenPieceInRedDen.playerColor == PlayerColor.green) {
      return PlayerColor.green;
    }

    Piece? redPieceInGreenDen = _board[dens[PlayerColor.green]!];
    if (redPieceInGreenDen != null &&
        redPieceInGreenDen.playerColor == PlayerColor.red) {
      return PlayerColor.red;
    }

    // Check if a player has no pieces left
    bool greenHasPieces = getPlayerPieces(PlayerColor.green).isNotEmpty;
    bool redHasPieces = getPlayerPieces(PlayerColor.red).isNotEmpty;

    if (!greenHasPieces) return PlayerColor.red;
    if (!redHasPieces) return PlayerColor.green;

    return null;
  }

  /// Create a copy of the board (for game state management)
  GameBoard copy() {
    GameBoard newBoard = GameBoard();
    newBoard._board.clear();
    _board.forEach((position, piece) {
      newBoard._board[position] = piece != null
          ? Piece(piece.animalType, piece.playerColor)
          : null;
    });
    return newBoard;
  }
}

import 'package:animal_chess/models/piece_display_format.dart';
import 'package:animal_chess/ai/animal_chess_network.dart';

enum AIStrategyType { defensive, offensive, balanced, exploratory, machineLearning }

class GameConfig {
  bool ratOnlyDenEntry;
  bool extendedLionTigerJumps;
  bool dogRiverVariant;
  bool ratCannotCaptureElephant;
  PieceDisplayFormat pieceDisplayFormat;

  // AI player configuration
  bool aiGreen;
  bool aiRed;
  AIStrategyType aiGreenStrategy;
  AIStrategyType aiRedStrategy;
  AnimalChessNetwork? animalChessNetwork;

  GameConfig({
    this.ratOnlyDenEntry = false,
    this.extendedLionTigerJumps = false,
    this.dogRiverVariant = false,
    this.ratCannotCaptureElephant = false,
    this.pieceDisplayFormat = PieceDisplayFormat.traditionalChinese,
    this.aiGreen = false,
    this.aiRed = false,
    this.aiGreenStrategy = AIStrategyType.offensive,
    this.aiRedStrategy = AIStrategyType.offensive,
    this.animalChessNetwork,
  });

  GameConfig copyWith({
    bool? ratOnlyDenEntry,
    bool? extendedLionTigerJumps,
    bool? dogRiverVariant,
    bool? ratCannotCaptureElephant,
    PieceDisplayFormat? pieceDisplayFormat,
    bool? aiGreen,
    bool? aiRed,
    AIStrategyType? aiGreenStrategy,
    AIStrategyType? aiRedStrategy,
    AnimalChessNetwork? animalChessNetwork,
  }) {
    return GameConfig(
      ratOnlyDenEntry: ratOnlyDenEntry ?? this.ratOnlyDenEntry,
      extendedLionTigerJumps:
          extendedLionTigerJumps ?? this.extendedLionTigerJumps,
      dogRiverVariant: dogRiverVariant ?? this.dogRiverVariant,
      ratCannotCaptureElephant:
          ratCannotCaptureElephant ?? this.ratCannotCaptureElephant,
      pieceDisplayFormat: pieceDisplayFormat ?? this.pieceDisplayFormat,
      aiGreen: aiGreen ?? this.aiGreen,
      aiRed: aiRed ?? this.aiRed,
      aiGreenStrategy: aiGreenStrategy ?? this.aiGreenStrategy,
      aiRedStrategy: aiRedStrategy ?? this.aiRedStrategy,
      animalChessNetwork: animalChessNetwork ?? this.animalChessNetwork,
    );
  }

  @override
  bool operator ==(Object other) {
    if (identical(this, other)) return true;
    return other is GameConfig &&
        other.ratOnlyDenEntry == ratOnlyDenEntry &&
        other.extendedLionTigerJumps == extendedLionTigerJumps &&
        other.dogRiverVariant == dogRiverVariant &&
        other.ratCannotCaptureElephant == ratCannotCaptureElephant &&
        other.pieceDisplayFormat == pieceDisplayFormat &&
        other.aiGreen == aiGreen &&
        other.aiRed == aiRed &&
        other.aiGreenStrategy == aiGreenStrategy &&
        other.aiRedStrategy == aiRedStrategy &&
        other.animalChessNetwork == animalChessNetwork;
  }

  @override
  int get hashCode => Object.hash(
    ratOnlyDenEntry,
    extendedLionTigerJumps,
    dogRiverVariant,
    ratCannotCaptureElephant,
    pieceDisplayFormat,
    aiGreen,
    aiRed,
    aiGreenStrategy,
    aiRedStrategy,
    animalChessNetwork,
  );
}

import 'package:animal_chess/models/animal_type.dart';
import 'package:animal_chess/models/player_color.dart';

class Piece {
  final AnimalType animalType;
  final PlayerColor playerColor;

  Piece(this.animalType, this.playerColor);

  // Getter to access playerColor as player for compatibility
  PlayerColor get player => playerColor;

  @override
  bool operator ==(Object other) {
    if (identical(this, other)) return true;
    if (other.runtimeType != runtimeType) return false;
    return other is Piece &&
        other.animalType == animalType &&
        other.playerColor == playerColor;
  }

  @override
  int get hashCode => Object.hash(animalType, playerColor);

  @override
  String toString() => '${playerColor.name} ${animalType.name}';

  /// Check if this piece can capture the opponent piece
  bool canCapture(Piece opponent) {
    // Pieces in traps can be captured by any opponent piece
    // This logic should be handled in the game controller, not here

    // Same player pieces cannot capture each other
    if (playerColor == opponent.playerColor) return false;

    // Rat can capture Elephant and vice versa (special rule)
    if (animalType == AnimalType.rat &&
        opponent.animalType == AnimalType.elephant) {
      return true;
    }

    if (animalType == AnimalType.elephant &&
        opponent.animalType == AnimalType.rat) {
      return true;
    }

    // Normal capture: can capture equal or lower rank pieces
    return animalType.rank <= opponent.animalType.rank;
  }
}

import 'package:flutter/material.dart';
import 'package:animal_chess/models/game_board.dart';
import 'package:animal_chess/models/player_color.dart';
import 'package:animal_chess/models/position.dart';
import 'package:animal_chess/models/piece.dart';
import 'package:animal_chess/models/animal_type.dart';
import 'package:animal_chess/models/piece_display_format.dart';
import 'package:animal_chess/widgets/piece_widget.dart';
import 'package:animal_chess/game/game_controller.dart';
import 'package:animal_chess/l10n/app_localizations.dart';
import 'package:animal_chess/constants/board_constants.dart';
import 'package:animal_chess/constants/ui_constants.dart';

class GameBoardWidget extends StatelessWidget {
  final GameController gameController;
  final Function(Position) onPositionTap;
  final List<Position> validMoves;
  final PieceDisplayFormat displayFormat;

  const GameBoardWidget({
    super.key,
    required this.gameController,
    required this.onPositionTap,
    required this.validMoves,
    this.displayFormat = PieceDisplayFormat.traditionalChinese,
  });

  @override
  Widget build(BuildContext context) {
    return AspectRatio(
      aspectRatio:
          BoardConstants.columns / BoardConstants.rows, // 7 columns × 9 rows
      child: LayoutBuilder(
        builder: (context, constraints) {
          final localizations = AppLocalizations.of(context);
          // Calculate the size of each cell
          final cellSize = constraints.maxWidth / BoardConstants.columns;

          return Container(
            decoration: BoxDecoration(
              border: Border.all(
                color: UIConstants.boardBorderColor,
                width: UIConstants.boardBorderWidth,
              ),
              color: UIConstants.boardBackgroundColor,
            ),
            child: GridView.builder(
              gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
                crossAxisCount: BoardConstants.columns, // 7 columns
              ),
              itemCount: BoardConstants.columns * BoardConstants.rows,
              itemBuilder: (context, index) {
                int row = index ~/ BoardConstants.columns;
                int col = index % BoardConstants.columns;
                Position position = Position(col, row);

                return _buildBoardCell(position, cellSize, localizations);
              },
            ),
          );
        },
      ),
    );
  }

  /// Build a single cell of the board
  Widget _buildBoardCell(
    Position position,
    double cellSize,
    AppLocalizations localizations,
  ) {
    GameBoard board = gameController.board;
    Piece? piece = board.getPiece(position);
    bool isSelected = gameController.selectedPosition == position;
    bool isValidMove = validMoves.contains(position);

    // Determine cell background color
    Color cellColor = _getCellBackgroundColor(position);

    // Add highlight for valid moves
    if (isValidMove) {
      cellColor = cellColor.withOpacity(0.7);
    }

    return GestureDetector(
      key: Key('cell_${position.column}_${position.row}'),
      onTap: () => onPositionTap(position),
      behavior: HitTestBehavior.opaque,
      child: Container(
        decoration: BoxDecoration(
          color: cellColor,
          border: Border.all(
            color: UIConstants.cellBorderColor.withOpacity(
              UIConstants.cellBorderWidth,
            ),
          ),
        ),
        child: Stack(
          alignment: Alignment.center,
          children: [
            // Special zone indicators
            if (board.isDen(position))
              _buildDenIndicator(position)
            else if (board.isTrap(position))
              _buildTrapIndicator()
            else if (board.isRiver(position))
              _buildRiverIndicator(),

            // Piece widget
            if (piece != null)
              PieceWidget(
                piece: piece,
                isSelected: isSelected,
                onTap: () => onPositionTap(position),
                size: cellSize, // Pass the cell size to the PieceWidget
                displayFormat: displayFormat, // Pass the display format
                animalName: _getLocalizedAnimalName(
                  localizations,
                  piece.animalType,
                ),
              )
            // Empty cell
            else
              Container(color: Colors.transparent),

            // Valid move indicator
            if (isValidMove && piece == null)
              Container(
                width: cellSize * UIConstants.validMoveIndicatorSizeFactor,
                height: cellSize * UIConstants.validMoveIndicatorSizeFactor,
                decoration: const BoxDecoration(
                  color: UIConstants.validMoveIndicatorColor,
                  shape: BoxShape.circle,
                ),
              ),
          ],
        ),
      ),
    );
  }

  String _getLocalizedAnimalName(
    AppLocalizations localizations,
    AnimalType animalType,
  ) {
    switch (animalType) {
      case AnimalType.elephant:
        return localizations.elephantName;
      case AnimalType.lion:
        return localizations.lionName;
      case AnimalType.tiger:
        return localizations.tigerName;
      case AnimalType.leopard:
        return localizations.leopardName;
      case AnimalType.wolf:
        return localizations.wolfName;
      case AnimalType.dog:
        return localizations.dogName;
      case AnimalType.cat:
        return localizations.catName;
      case AnimalType.rat:
        return localizations.ratName;
    }
  }

  /// Get background color for a cell based on its type
  Color _getCellBackgroundColor(Position position) {
    GameBoard board = gameController.board;

    // Dens
    if (board.isDen(position)) {
      return board.getZoneOwner(position) == PlayerColor.green
          ? UIConstants.greenDenColor
          : UIConstants.redDenColor;
    }

    // Traps
    if (board.isTrap(position)) {
      return board.getZoneOwner(position) == PlayerColor.green
          ? UIConstants.greenTrapColor
          : UIConstants.redTrapColor;
    }

    // Rivers
    if (board.isRiver(position)) {
      return UIConstants.riverColor;
    }

    // Regular cells
    return UIConstants.boardBackgroundColor;
  }

  /// Build indicator for den cells
  Widget _buildDenIndicator(Position position) {
    return Container(
      decoration: BoxDecoration(
        color: Colors.transparent,
        border: Border.all(
          color: UIConstants.denBorderColor,
          width: UIConstants.boardBorderWidth,
        ),
        borderRadius: BorderRadius.circular(UIConstants.denBorderRadius),
      ),
      child: const Center(
        child: Icon(
          Icons.home,
          color: UIConstants.denIconColor,
          size: UIConstants.denIconSize,
        ),
      ),
    );
  }

  /// Build indicator for trap cells
  Widget _buildTrapIndicator() {
    return Container(
      decoration: BoxDecoration(
        color: Colors.transparent,
        border: Border.all(
          color: UIConstants.trapBorderColor,
          width: UIConstants.boardBorderWidth,
        ),
        borderRadius: BorderRadius.circular(UIConstants.trapBorderRadius),
      ),
      child: const Center(
        child: Icon(
          Icons.warning,
          color: UIConstants.trapIconColor,
          size: UIConstants.trapIconSize,
        ),
      ),
    );
  }

  /// Build indicator for river cells
  Widget _buildRiverIndicator() {
    return const Center(
      child: Icon(
        Icons.water_drop,
        color: UIConstants.riverIconColor,
        size: UIConstants.riverIconSize,
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:animal_chess/models/player_color.dart';
import 'package:animal_chess/models/piece.dart';
import 'package:animal_chess/models/animal_type.dart';
import 'package:animal_chess/models/piece_display_format.dart';
import 'package:animal_chess/constants/ui_constants.dart';

class PieceWidget extends StatelessWidget {
  final Piece piece;
  final bool isSelected;
  final VoidCallback? onTap;
  final double size; // New parameter for piece size
  final bool isRankDisplay; // New parameter for rank display
  final String? animalName; // New parameter for localized animal name
  final PieceDisplayFormat displayFormat; // New parameter for display format

  const PieceWidget({
    super.key,
    required this.piece,
    this.isSelected = false,
    this.onTap,
    this.size = 40.0, // Default size
    this.isRankDisplay = false, // Default to false
    this.animalName, // Allow passing a localized name
    this.displayFormat =
        PieceDisplayFormat.traditionalChinese, // Default to traditional Chinese
  });

  /// Returns the animal symbol based on the selected display format
  String _getAnimalSymbol(AnimalType animalType) {
    switch (displayFormat) {
      case PieceDisplayFormat.emoji:
        return _getEmojiSymbol(animalType);
      case PieceDisplayFormat.simplifiedChinese:
        return _getSimplifiedChineseSymbol(animalType);
      case PieceDisplayFormat.traditionalChinese:
        return _getTraditionalChineseSymbol(animalType);
    }
  }

  /// Returns the emoji symbol for the animal
  String _getEmojiSymbol(AnimalType animalType) {
    switch (animalType) {
      case AnimalType.elephant:
        return '🐘';
      case AnimalType.lion:
        return '🦁';
      case AnimalType.tiger:
        return '🐯';
      case AnimalType.leopard:
        return '🐆';
      case AnimalType.wolf:
        return '🐺';
      case AnimalType.dog:
        return '🐕';
      case AnimalType.cat:
        return '🐈';
      case AnimalType.rat:
        return '🐀';
    }
  }

  /// Returns the simplified Chinese symbol for the animal
  String _getSimplifiedChineseSymbol(AnimalType animalType) {
    switch (animalType) {
      case AnimalType.elephant:
        return '象';
      case AnimalType.lion:
        return '狮';
      case AnimalType.tiger:
        return '虎';
      case AnimalType.leopard:
        return '豹';
      case AnimalType.wolf:
        return '狼';
      case AnimalType.dog:
        return '狗';
      case AnimalType.cat:
        return '猫';
      case AnimalType.rat:
        return '鼠';
    }
  }

  /// Returns the traditional Chinese symbol for the animal
  String _getTraditionalChineseSymbol(AnimalType animalType) {
    switch (animalType) {
      case AnimalType.elephant:
        return '象';
      case AnimalType.lion:
        return '獅';
      case AnimalType.tiger:
        return '虎';
      case AnimalType.leopard:
        return '豹';
      case AnimalType.wolf:
        return '狼';
      case AnimalType.dog:
        return '狗';
      case AnimalType.cat:
        return '貓';
      case AnimalType.rat:
        return '鼠';
    }
  }

  @override
  Widget build(BuildContext context) {
    // Calculate the piece size as 90% of the block size
    final pieceSize = size * UIConstants.pieceSizeFactor;

    // Define colors for each player
    Color backgroundColor = piece.playerColor == PlayerColor.green
        ? UIConstants.greenPieceColor
        : UIConstants.redPieceColor;

    // Define text color for better contrast
    Color textColor = UIConstants.pieceTextColor;

    // If this is for rank display, use dark grey with white text
    if (isRankDisplay) {
      backgroundColor = UIConstants.rankDisplayBackgroundColor; // Dark grey
      textColor = UIConstants.pieceTextColor; // White text
    }

    // Add selection indicator (only for game board, not rank display)
    if (isSelected && !isRankDisplay) {
      backgroundColor = piece.playerColor == PlayerColor.green
          ? UIConstants.greenPieceColor
          : UIConstants.redPieceColor;
    }

    return GestureDetector(
      onTap: onTap,
      child: Padding(
        padding: EdgeInsets.all(UIConstants.pieceTapPadding),
        child: Container(
          width: pieceSize,
          height: pieceSize,
          decoration: BoxDecoration(
            color: backgroundColor,
            shape: BoxShape.circle,
            border: Border.all(
              color: isSelected && !isRankDisplay
                  ? UIConstants.pieceBorderColorSelected
                  : UIConstants.pieceBorderColorNormal,
              width: isSelected && !isRankDisplay
                  ? UIConstants.pieceBorderWidthSelected
                  : UIConstants.pieceBorderWidthNormal,
            ),
            boxShadow: [
              BoxShadow(
                color: Color.alphaBlend(
                  UIConstants.pieceShadowColor.withOpacity(0.2),
                  Colors.transparent,
                ),
                blurRadius: UIConstants.pieceShadowBlurRadius,
                offset: UIConstants.pieceShadowOffset,
              ),
            ],
          ),
          child: Center(
            child: Transform.translate(
              offset: const Offset(0, -2), // Move up by 5 pixels
              child: Text(
                _getAnimalSymbol(piece.animalType),
                style: TextStyle(
                  color: textColor,
                  fontSize:
                      pieceSize *
                      UIConstants
                          .pieceFontSizeFactor, // Adjust font size proportionally
                  fontWeight: FontWeight.bold,
                  height: 1.0, // Ensures proper vertical centering
                ),
              ),
            ),
          ),
        ),
      ),
    );
  }
}

