import { type Forbidden, forbiddenAt } from './renju';

/**
 * 15×15 gomoku: black moves first, five or more in a row wins. Under the
 * optional renju rule black must make exactly five and may not play forbidden
 * points (see renju.ts); white is unrestricted.
 */

export const BOARD_SIZE = 15;
export const EMPTY = 0;
export const BLACK = 1;
export const WHITE = 2;

export type Stone = typeof BLACK | typeof WHITE;
export type Cell = typeof EMPTY | Stone;
export type Point = { x: number; y: number };
export type Board = Uint8Array;
export type Rule = 'freestyle' | 'renju';

export const DIRECTIONS: ReadonlyArray<readonly [number, number]> = [
  [1, 0],
  [0, 1],
  [1, 1],
  [1, -1],
];

export function createBoard(size = BOARD_SIZE): Board {
  return new Uint8Array(size * size);
}

export function cloneBoard(board: Board): Board {
  return new Uint8Array(board);
}

export function sizeOf(board: Board) {
  return Math.round(Math.sqrt(board.length));
}

export function inBounds(size: number, x: number, y: number) {
  return x >= 0 && y >= 0 && x < size && y < size;
}

export function get(board: Board, x: number, y: number): Cell {
  const size = sizeOf(board);
  return inBounds(size, x, y) ? (board[y * size + x] as Cell) : EMPTY;
}

export function set(board: Board, x: number, y: number, value: Cell) {
  board[y * sizeOf(board) + x] = value;
}

export function opponent(stone: Stone): Stone {
  return stone === BLACK ? WHITE : BLACK;
}

export function isEmpty(board: Board, x: number, y: number) {
  const size = sizeOf(board);
  return inBounds(size, x, y) && board[y * size + x] === EMPTY;
}

export function isFull(board: Board) {
  return board.every((cell) => cell !== EMPTY);
}

export function stoneCount(board: Board) {
  let count = 0;
  for (const cell of board) if (cell !== EMPTY) count += 1;
  return count;
}

/**
 * The winning line through (x, y) for `stone`, or null. Returns every stone in
 * the run (five or more), ordered from one end to the other.
 */
export function winningLine(board: Board, x: number, y: number, stone: Stone, rule: Rule = 'freestyle'): Point[] | null {
  // Renju: only an exact five wins for black (an overline is forbidden).
  const exact = rule === 'renju' && stone === BLACK;
  const size = sizeOf(board);
  for (const [dx, dy] of DIRECTIONS) {
    const line: Point[] = [{ x, y }];
    for (let step = 1; ; step += 1) {
      const nx = x + dx * step;
      const ny = y + dy * step;
      if (!inBounds(size, nx, ny) || board[ny * size + nx] !== stone) break;
      line.push({ x: nx, y: ny });
    }
    for (let step = 1; ; step += 1) {
      const nx = x - dx * step;
      const ny = y - dy * step;
      if (!inBounds(size, nx, ny) || board[ny * size + nx] !== stone) break;
      line.unshift({ x: nx, y: ny });
    }
    if (exact ? line.length === 5 : line.length >= 5) return line;
  }
  return null;
}

export type MoveResult =
  | { kind: 'invalid' }
  | { kind: 'forbidden'; reason: Forbidden }
  | { kind: 'placed' }
  | { kind: 'win'; line: Point[] }
  | { kind: 'draw' };

/** Game state with history; the single source of truth for every mode. */
export class GomokuGame {
  readonly size: number;
  readonly rule: Rule;
  board: Board;
  turn: Stone = BLACK;
  history: Array<Point & { stone: Stone }> = [];
  winner: Stone | null = null;
  winLine: Point[] | null = null;
  over = false;

  constructor(size = BOARD_SIZE, rule: Rule = 'freestyle') {
    this.size = size;
    this.rule = rule;
    this.board = createBoard(size);
  }

  get lastMove() {
    return this.history.at(-1) ?? null;
  }

  movesBy(stone: Stone) {
    return this.history.filter((move) => move.stone === stone).length;
  }

  play(x: number, y: number): MoveResult {
    if (this.over || !isEmpty(this.board, x, y)) return { kind: 'invalid' };
    const stone = this.turn;
    const reason = this.forbidden(x, y);
    if (reason) return { kind: 'forbidden', reason };
    set(this.board, x, y, stone);
    this.history.push({ x, y, stone });
    const line = winningLine(this.board, x, y, stone, this.rule);
    if (line) {
      this.over = true;
      this.winner = stone;
      this.winLine = line;
      return { kind: 'win', line };
    }
    if (isFull(this.board)) {
      this.over = true;
      return { kind: 'draw' };
    }
    this.turn = opponent(stone);
    return { kind: 'placed' };
  }

  /** Why the side to move may not play at (x, y) under this game's rule, or null. */
  forbidden(x: number, y: number): Forbidden | null {
    if (this.rule !== 'renju' || this.turn !== BLACK) return null;
    return forbiddenAt(this.board, x, y);
  }

  /** Remove the last `count` moves. Returns the removed moves, newest first. */
  undo(count = 1) {
    const removed: Array<Point & { stone: Stone }> = [];
    for (let index = 0; index < count && this.history.length > 0; index += 1) {
      const move = this.history.pop();
      if (!move) break;
      set(this.board, move.x, move.y, EMPTY);
      removed.push(move);
      this.turn = move.stone;
    }
    this.over = false;
    this.winner = null;
    this.winLine = null;
    return removed;
  }

  /** The side to move gives up. */
  resign() {
    if (this.over) return;
    this.over = true;
    this.winner = opponent(this.turn);
  }
}

import { BLACK, type Board, DIRECTIONS, EMPTY, inBounds, type Point, type Rule, sizeOf } from './rules';

/**
 * Renju forbidden points (RIF rules, 15×15). Only black is restricted:
 *   - overline: six or more in a row;
 *   - double-four: one move makes two or more fours;
 *   - double-three: one move makes two or more real threes.
 * A move that makes an exact five is never forbidden, even if it also makes
 * any of the above. A three is only real if some empty point turns it into a
 * straight four and that point is not itself forbidden, so the check recurses
 * (every level places one more stone, which keeps it bounded).
 *
 * Differentially tested against Rapfi's `checkForbiddenPoint` (YXSHOWFORBID)
 * on ~40k forbidden points; tests/fixtures/renju-rapfi.json keeps a sample.
 * One known difference, where this follows the RIF wording: when the point that
 * turns a three into a straight four also makes a five elsewhere, Rapfi does
 * not count that three (it classifies the point as a five), while here it
 * counts. It only arises when black already has an unanswered four.
 */

export type Forbidden = 'overline' | 'double-four' | 'double-three';

export const RULE_NAMES: Record<Rule, string> = { freestyle: '无禁手', renju: '连珠' };
export const FORBIDDEN_NAMES: Record<Forbidden, string> = { overline: '长连', 'double-four': '四四', 'double-three': '三三' };

/** Black stones in a row through (x, y), counting (x, y) itself as black. */
function runLength(board: Board, size: number, x: number, y: number, dx: number, dy: number) {
  let length = 1;
  for (let step = 1; ; step += 1) {
    const nx = x + dx * step;
    const ny = y + dy * step;
    if (!inBounds(size, nx, ny) || board[ny * size + nx] !== BLACK) break;
    length += 1;
  }
  for (let step = 1; ; step += 1) {
    const nx = x - dx * step;
    const ny = y - dy * step;
    if (!inBounds(size, nx, ny) || board[ny * size + nx] !== BLACK) break;
    length += 1;
  }
  return length;
}

/**
 * Offsets along (dx, dy) of the empty points that would give black an exact
 * five containing the black stone at (x, y).
 */
function fiveSpots(board: Board, size: number, x: number, y: number, dx: number, dy: number) {
  const spots: number[] = [];
  for (let offset = -4; offset <= 4; offset += 1) {
    if (offset === 0) continue;
    const qx = x + dx * offset;
    const qy = y + dy * offset;
    if (!inBounds(size, qx, qy) || board[qy * size + qx] !== EMPTY) continue;
    // Every cell strictly between q and (x, y) must be black, or the five would not contain it.
    let joined = true;
    for (let step = 1; step < Math.abs(offset); step += 1) {
      const k = Math.sign(offset) * step;
      if (board[(y + dy * k) * size + (x + dx * k)] !== BLACK) {
        joined = false;
        break;
      }
    }
    if (joined && runLength(board, size, qx, qy, dx, dy) === 5) spots.push(offset);
  }
  return spots;
}

/** Fours in one line through a black stone: an open four counts once, a split double-four twice. */
function foursInLine(spots: number[]) {
  if (spots.length === 2 && Math.abs(spots[0] - spots[1]) === 5) return 1;
  return spots.length;
}

function isStraightFour(spots: number[]) {
  return spots.length === 2 && Math.abs(spots[0] - spots[1]) === 5;
}

/** Why black may not play at (x, y), or null if it may. The cell must be empty. */
export function forbiddenAt(board: Board, x: number, y: number): Forbidden | null {
  const size = sizeOf(board);
  const index = y * size + x;
  if (board[index] !== EMPTY) return null;
  // Forbidden shapes need black stones nearby; skip the recursion for lone points.
  if (!hasBlackNeighbours(board, size, x, y)) return null;

  board[index] = BLACK;
  try {
    let overline = false;
    for (const [dx, dy] of DIRECTIONS) {
      const length = runLength(board, size, x, y, dx, dy);
      if (length === 5) return null;
      if (length > 5) overline = true;
    }
    if (overline) return 'overline';

    let fours = 0;
    const fourLines: boolean[] = [];
    for (const [dx, dy] of DIRECTIONS) {
      const count = foursInLine(fiveSpots(board, size, x, y, dx, dy));
      fours += count;
      fourLines.push(count > 0);
    }
    if (fours >= 2) return 'double-four';

    let threes = 0;
    DIRECTIONS.forEach(([dx, dy], dir) => {
      if (threes >= 2 || fourLines[dir]) return;
      if (isRealThree(board, size, x, y, dx, dy)) threes += 1;
    });
    return threes >= 2 ? 'double-three' : null;
  } finally {
    board[index] = EMPTY;
  }
}

/** Whether the black stone at (x, y) forms a three along (dx, dy) that can become a legal straight four. */
function isRealThree(board: Board, size: number, x: number, y: number, dx: number, dy: number) {
  for (let offset = -4; offset <= 4; offset += 1) {
    if (offset === 0) continue;
    const qx = x + dx * offset;
    const qy = y + dy * offset;
    if (!inBounds(size, qx, qy)) continue;
    const q = qy * size + qx;
    if (board[q] !== EMPTY) continue;
    board[q] = BLACK;
    const straight = isStraightFour(fiveSpots(board, size, x, y, dx, dy));
    board[q] = EMPTY;
    if (straight && forbiddenAt(board, qx, qy) === null) return true;
  }
  return false;
}

function hasBlackNeighbours(board: Board, size: number, x: number, y: number) {
  let seen = 0;
  for (const [dx, dy] of DIRECTIONS) {
    for (let step = -4; step <= 4; step += 1) {
      if (step === 0) continue;
      const nx = x + dx * step;
      const ny = y + dy * step;
      if (inBounds(size, nx, ny) && board[ny * size + nx] === BLACK) seen += 1;
    }
  }
  // A double-three needs four other black stones; a four-four or overline at least three.
  return seen >= 3;
}

/** Every forbidden point for black on this board. */
export function forbiddenPoints(board: Board): Array<Point & { reason: Forbidden }> {
  const size = sizeOf(board);
  const points: Array<Point & { reason: Forbidden }> = [];
  for (let y = 0; y < size; y += 1) {
    for (let x = 0; x < size; x += 1) {
      const reason = forbiddenAt(board, x, y);
      if (reason) points.push({ x, y, reason });
    }
  }
  return points;
}

import { BLACK, type Board, EMPTY, type Point, type Rule, sizeOf } from './rules';

/**
 * RIF opening for renju: 三手交换 · 五手两打.
 *   1. The tentative black places the first three stones (black, white, black):
 *      move 1 on the centre, move 2 within the centre 3×3, move 3 within the 5×5.
 *   2. The tentative white may swap colours.
 *   3. White plays move 4 anywhere.
 *   4. Black offers two 5th moves that are not symmetric to each other; white
 *      keeps one (the other is dropped) and then plays move 6. Play is normal
 *      from there on.
 * Only the kept 5th move is ever played, so the move list stays an ordinary
 * alternating game (the leaderboard replay needs nothing new).
 */

export type Opening = 'free' | 'rif';
export const OPENING_NAMES: Record<Opening, string> = { free: '自由开局', rif: '三手交换 · 五手两打' };

/** The three rule choices offered in the menus, in the order a toggle cycles through them. */
export type Variant = { rule: Rule; opening: Opening };
export const VARIANTS: Variant[] = [
  { rule: 'freestyle', opening: 'free' },
  { rule: 'renju', opening: 'free' },
  { rule: 'renju', opening: 'rif' },
];

/** The RIF opening only exists with renju; anything else collapses to a free opening. */
/** Every menu starts on free-style; renju and the RIF opening are opted into each time. */
export const DEFAULT_VARIANT: Variant = VARIANTS[0];

export function normalizeVariant(rule: Rule, opening: Opening | undefined): Variant {
  return { rule, opening: rule === 'renju' && opening === 'rif' ? 'rif' : 'free' };
}

export function nextVariant(current: Variant): Variant {
  const index = VARIANTS.findIndex((v) => v.rule === current.rule && v.opening === current.opening);
  return VARIANTS[(index + 1) % VARIANTS.length];
}

/** Short name, e.g. for a toggle: 无禁手 / 连珠 / 连珠 · 三手交换五手两打. */
export function variantName(variant: Variant) {
  if (variant.rule === 'freestyle') return '无禁手';
  return variant.opening === 'rif' ? '连珠 · 三手交换五手两打' : '连珠';
}

export type OpeningPhase =
  /** The tentative black is placing move 1–3. */
  | 'place'
  /** The tentative white decides whether to swap colours. */
  | 'swap'
  /** White plays move 4, or anyone plays after the opening: normal turns. */
  | 'play'
  /** Black is picking two candidate 5th moves. */
  | 'offer'
  /** White keeps one of the two offers. */
  | 'choose';

export type OpeningState = { swapDecided: boolean; offers: Point[] };

export const freshOpening = (): OpeningState => ({ swapDecided: false, offers: [] });

/** Where the game stands, from the number of moves played and the opening decisions so far. */
export function openingPhase(opening: Opening, moves: number, state: OpeningState): OpeningPhase {
  if (opening !== 'rif') return 'play';
  if (moves < 3) return 'place';
  if (moves === 3 && !state.swapDecided) return 'swap';
  if (moves === 4) return state.offers.length === 2 ? 'choose' : 'offer';
  return 'play';
}

/** Chebyshev radius around the centre that move `index` (0-based) must stay within, or null. */
export function openingRadius(index: number): number | null {
  return index === 0 ? 0 : index === 1 ? 1 : index === 2 ? 2 : null;
}

export function inOpeningZone(board: Board, index: number, point: Point) {
  const radius = openingRadius(index);
  if (radius === null) return true;
  const center = Math.floor(sizeOf(board) / 2);
  return Math.abs(point.x - center) <= radius && Math.abs(point.y - center) <= radius;
}

/** The eight symmetries of the square board around its centre. */
function transforms(size: number): Array<(p: Point) => Point> {
  const m = size - 1;
  return [
    (p) => ({ x: p.x, y: p.y }),
    (p) => ({ x: m - p.x, y: p.y }),
    (p) => ({ x: p.x, y: m - p.y }),
    (p) => ({ x: m - p.x, y: m - p.y }),
    (p) => ({ x: p.y, y: p.x }),
    (p) => ({ x: m - p.y, y: p.x }),
    (p) => ({ x: p.y, y: m - p.x }),
    (p) => ({ x: m - p.y, y: m - p.x }),
  ];
}

/**
 * Whether black playing `a` or `b` gives the same position up to rotation or
 * reflection. RIF forbids offering two such 5th moves.
 */
export function equivalentOffers(board: Board, a: Point, b: Point) {
  if (a.x === b.x && a.y === b.y) return true;
  const size = sizeOf(board);
  const withA = new Uint8Array(board);
  withA[a.y * size + a.x] = BLACK;
  const withB = new Uint8Array(board);
  withB[b.y * size + b.x] = BLACK;
  return transforms(size).some((t) => {
    for (let index = 0; index < withA.length; index += 1) {
      const cell = withA[index];
      if (cell === EMPTY) continue;
      const q = t({ x: index % size, y: Math.floor(index / size) });
      if (withB[q.y * size + q.x] !== cell) return false;
    }
    return true;
  });
}

/** A random point for opening move `index` (0–2), for an AI placing the first three stones. */
export function randomOpeningMove(board: Board, index: number, random: () => number = Math.random): Point {
  const size = sizeOf(board);
  const center = Math.floor(size / 2);
  const radius = openingRadius(index) ?? 2;
  const free: Point[] = [];
  for (let y = center - radius; y <= center + radius; y += 1) {
    for (let x = center - radius; x <= center + radius; x += 1) {
      if (board[y * size + x] === EMPTY) free.push({ x, y });
    }
  }
  return free[Math.floor(random() * free.length)] ?? { x: center, y: center };
}

import { Container, type FederatedPointerEvent, Graphics, Rectangle, Sprite, type Ticker } from 'pixi.js';
import gsap from 'gsap';

import { tex } from '../app/textures';
import { BOARD_INSET } from '../svg/art';
import { BLACK, BOARD_SIZE, type Point, type Stone } from '../gomoku/rules';

const STAR_POINTS = [
  [3, 3], [11, 3], [7, 7], [3, 11], [11, 11],
];

type StoneNode = { stone: Sprite; shadow: Sprite };

/**
 * The wooden board. Grid lines are drawn in Pixi so they stay crisp at any size;
 * stones are SVG textures. Emits `onCell` when the local player picks a point.
 */
export class BoardView extends Container {
  readonly size = BOARD_SIZE;
  private boardSprite = new Sprite(tex('board'));
  private grid = new Graphics();
  private shadows = new Container();
  private stones = new Container();
  private overlay = new Container();
  private winGraphics = new Graphics();
  private ghost = new Sprite(tex('stone-black'));
  private lastMarker = new Graphics();
  /** Red crosses on points black may not play (renju). */
  private forbiddenMarks = new Graphics();
  private forbidden = new Set<number>();
  /** RIF opening: the area the next opening stone must go in. */
  private zoneMarks = new Graphics();
  private zoneRadius: number | null = null;
  /** RIF opening: candidate 5th moves, drawn as see-through black stones. */
  private offerLayer = new Container();
  private offers: Point[] = [];
  private nodes = new Map<number, StoneNode>();
  private pixelSize = 600;
  private cell = 40;
  private gridStart = 0;
  private time = 0;
  private pendingTouch: Point | null = null;
  private winGlows: Sprite[] = [];
  private winTween: gsap.core.Tween | null = null;

  /** Whether the local player may place a stone right now. */
  acceptingInput = false;
  /** Whether hovering shows a stone preview (off while picking among offered points). */
  ghostEnabled = true;
  /** Colour of the ghost preview. */
  turnStone: Stone = BLACK;
  onCell: (point: Point) => void = () => undefined;
  onTouchPreviewChange: () => void = () => undefined;

  constructor() {
    super();
    this.ghost.anchor.set(0.5);
    this.ghost.alpha = 0;
    this.lastMarker.visible = false;
    this.addChild(this.boardSprite, this.grid, this.zoneMarks, this.forbiddenMarks, this.shadows, this.stones, this.offerLayer, this.lastMarker, this.ghost, this.winGraphics, this.overlay);

    this.eventMode = 'static';
    this.on('pointermove', (event) => this.handleHover(event));
    this.on('pointerleave', (event) => {
      // Touch pointers leave on finger lift, between preview and confirmation.
      if (event.pointerType !== 'touch') this.hideGhost();
    });
    this.on('pointerupoutside', () => this.hideGhost());
    this.on('pointercancel', () => this.hideGhost());
    this.on('pointertap', (event) => this.handleTap(event));
  }

  get boardPixelSize() {
    return this.pixelSize;
  }

  get hasTouchPreview() {
    return this.pendingTouch !== null;
  }

  layout(pixelSize: number) {
    this.pixelSize = pixelSize;
    this.boardSprite.width = this.boardSprite.height = pixelSize;
    const inset = (BOARD_INSET / 1000) * pixelSize;
    const play = pixelSize - inset * 2;
    this.cell = play / this.size;
    this.gridStart = inset + this.cell / 2;
    this.hitArea = new Rectangle(0, 0, pixelSize, pixelSize);
    this.drawGrid();
    for (const [index, node] of this.nodes) this.positionNode(node, index % this.size, Math.floor(index / this.size));
    this.ghost.width = this.ghost.height = this.cell * 0.9;
    if (this.pendingTouch) this.showGhost(this.pendingTouch, 0.6);
    this.placeLastMarker();
    this.drawForbidden();
    this.drawZone();
    this.drawOffers();
  }

  private drawGrid() {
    const g = this.grid.clear();
    const start = this.gridStart;
    const end = this.gridStart + this.cell * (this.size - 1);
    const lineWidth = Math.max(1, this.cell * 0.035);
    for (let index = 0; index < this.size; index += 1) {
      const p = this.gridStart + index * this.cell;
      g.moveTo(start, p).lineTo(end, p);
      g.moveTo(p, start).lineTo(p, end);
    }
    g.stroke({ color: 0x5a2c0c, width: lineWidth, alpha: 0.75 });
    g.rect(start, start, end - start, end - start).stroke({ color: 0x5a2c0c, width: lineWidth * 2.2, alpha: 0.85 });
    for (const [x, y] of STAR_POINTS) g.circle(this.gridStart + x * this.cell, this.gridStart + y * this.cell, this.cell * 0.12).fill({ color: 0x5a2c0c, alpha: 0.9 });
  }

  toLocal2(point: Point) {
    return { x: this.gridStart + point.x * this.cell, y: this.gridStart + point.y * this.cell };
  }

  private pointFromEvent(event: FederatedPointerEvent): Point | null {
    const local = this.toLocal(event.global);
    const x = Math.round((local.x - this.gridStart) / this.cell);
    const y = Math.round((local.y - this.gridStart) / this.cell);
    if (x < 0 || y < 0 || x >= this.size || y >= this.size) return null;
    return { x, y };
  }

  private occupied(point: Point) {
    return this.nodes.has(point.y * this.size + point.x);
  }

  private isForbidden(point: Point) {
    return this.forbidden.has(point.y * this.size + point.x);
  }

  /** Mark the points the local player may not play; an empty list clears the marks. */
  setForbidden(points: Point[]) {
    this.forbidden = new Set(points.map((point) => point.y * this.size + point.x));
    this.drawForbidden();
  }

  /** Highlight the centre square of this Chebyshev radius; null clears it. */
  setZone(radius: number | null) {
    this.zoneRadius = radius;
    this.drawZone();
  }

  private drawZone() {
    const g = this.zoneMarks.clear();
    if (this.zoneRadius === null) return;
    const center = Math.floor(this.size / 2);
    const from = this.toLocal2({ x: center - this.zoneRadius, y: center - this.zoneRadius });
    const side = (this.zoneRadius * 2 + 1) * this.cell;
    const half = this.cell / 2;
    g.roundRect(from.x - half, from.y - half, side, side, this.cell * 0.3)
      .fill({ color: 0xffd23f, alpha: 0.18 })
      .stroke({ color: 0xffb400, width: Math.max(2, this.cell * 0.06), alpha: 0.8 });
  }

  /** Show candidate 5th moves; an empty list clears them. */
  setOffers(points: Point[]) {
    this.offers = points.map((point) => ({ x: point.x, y: point.y }));
    this.drawOffers();
  }

  private drawOffers() {
    for (const child of this.offerLayer.removeChildren()) child.destroy();
    for (const point of this.offers) {
      const { x, y } = this.toLocal2(point);
      const stone = new Sprite(tex('stone-black'));
      stone.anchor.set(0.5);
      stone.width = stone.height = this.cell * 0.92;
      stone.alpha = 0.5;
      stone.position.set(x, y);
      const ring = new Graphics().circle(x, y, this.cell * 0.5).stroke({ color: 0xffd23f, width: Math.max(2, this.cell * 0.08) });
      this.offerLayer.addChild(stone, ring);
    }
  }

  private drawForbidden() {
    const g = this.forbiddenMarks.clear();
    const arm = this.cell * 0.2;
    for (const index of this.forbidden) {
      const { x, y } = this.toLocal2({ x: index % this.size, y: Math.floor(index / this.size) });
      g.moveTo(x - arm, y - arm).lineTo(x + arm, y + arm).moveTo(x + arm, y - arm).lineTo(x - arm, y + arm);
    }
    g.stroke({ color: 0xe0303f, width: Math.max(2, this.cell * 0.08), cap: 'round', alpha: 0.85 });
  }

  private handleHover(event: FederatedPointerEvent) {
    if (event.pointerType === 'touch') return;
    const point = this.pointFromEvent(event);
    if (!this.acceptingInput || !this.ghostEnabled || !point || this.occupied(point) || this.isForbidden(point)) {
      this.hideGhost();
      return;
    }
    this.showGhost(point, 0.45);
  }

  private handleTap(event: FederatedPointerEvent) {
    const point = this.pointFromEvent(event);
    if (!this.acceptingInput || !point || this.occupied(point)) return;
    // Touch: the first tap previews, a second tap on the same point confirms.
    // A forbidden point goes straight through so the game can say why it is refused.
    if (event.pointerType === 'touch' && this.ghostEnabled && !this.isForbidden(point)) {
      if (!this.pendingTouch || this.pendingTouch.x !== point.x || this.pendingTouch.y !== point.y) {
        this.pendingTouch = point;
        this.showGhost(point, 0.6);
        this.onTouchPreviewChange();
        return;
      }
    }
    this.hideGhost();
    this.onCell(point);
  }

  private showGhost(point: Point, alpha: number) {
    this.ghost.texture = tex(this.turnStone === BLACK ? 'stone-black' : 'stone-white');
    const { x, y } = this.toLocal2(point);
    this.ghost.position.set(x, y);
    this.ghost.alpha = alpha;
  }

  hideGhost() {
    const hadTouchPreview = this.hasTouchPreview;
    this.pendingTouch = null;
    this.ghost.alpha = 0;
    if (hadTouchPreview) this.onTouchPreviewChange();
  }

  private positionNode(node: StoneNode, x: number, y: number) {
    const p = this.toLocal2({ x, y });
    node.stone.position.set(p.x, p.y);
    node.stone.width = node.stone.height = this.cell * 0.92;
    node.shadow.position.set(p.x + this.cell * 0.06, p.y + this.cell * 0.1);
    node.shadow.width = node.shadow.height = this.cell * 1.02;
  }

  placeStone(x: number, y: number, stone: Stone, animate = true) {
    const index = y * this.size + x;
    this.removeStone(x, y);
    const node: StoneNode = {
      stone: new Sprite(tex(stone === BLACK ? 'stone-black' : 'stone-white')),
      shadow: new Sprite(tex('stone-shadow')),
    };
    node.stone.anchor.set(0.5);
    node.shadow.anchor.set(0.5);
    this.positionNode(node, x, y);
    this.shadows.addChild(node.shadow);
    this.stones.addChild(node.stone);
    this.nodes.set(index, node);
    this.lastPoint = { x, y };
    this.placeLastMarker();
    if (animate) {
      const targetScale = node.stone.scale.x;
      const shadowScale = node.shadow.scale.x;
      gsap.fromTo(node.stone.scale, { x: targetScale * 1.35, y: targetScale * 1.35 }, { x: targetScale, y: targetScale, duration: 0.28, ease: 'back.out(2.6)' });
      gsap.fromTo(node.stone, { alpha: 0, y: node.stone.y - this.cell * 0.4 }, { alpha: 1, y: node.stone.y, duration: 0.2, ease: 'power2.in' });
      gsap.fromTo(node.shadow.scale, { x: shadowScale * 0.4, y: shadowScale * 0.4 }, { x: shadowScale, y: shadowScale, duration: 0.24 });
      this.ripple(x, y);
    }
  }

  private lastPoint: Point | null = null;

  setLastMove(point: Point | null) {
    this.lastPoint = point;
    this.placeLastMarker();
  }

  private placeLastMarker() {
    const g = this.lastMarker.clear();
    if (!this.lastPoint) {
      g.visible = false;
      return;
    }
    const node = this.nodes.get(this.lastPoint.y * this.size + this.lastPoint.x);
    if (!node) {
      g.visible = false;
      return;
    }
    g.visible = true;
    g.circle(0, 0, this.cell * 0.14).fill(0xff4d5e).stroke({ color: 0xffffff, width: 2, alpha: 0.9 });
    g.position.copyFrom(node.stone.position);
  }

  removeStone(x: number, y: number) {
    const index = y * this.size + x;
    const node = this.nodes.get(index);
    if (!node) return;
    this.nodes.delete(index);
    gsap.killTweensOf(node.stone);
    gsap.killTweensOf(node.stone.scale);
    node.stone.destroy();
    node.shadow.destroy();
  }

  clear() {
    this.hideGhost();
    this.setForbidden([]);
    this.setZone(null);
    this.setOffers([]);
    for (const index of [...this.nodes.keys()]) this.removeStone(index % this.size, Math.floor(index / this.size));
    this.clearWin();
    this.setLastMove(null);
  }

  private ripple(x: number, y: number) {
    const p = this.toLocal2({ x, y });
    const ring = new Graphics().circle(0, 0, this.cell * 0.5).stroke({ color: 0xffffff, width: 3, alpha: 0.8 });
    ring.position.set(p.x, p.y);
    this.overlay.addChild(ring);
    gsap.to(ring.scale, { x: 1.9, y: 1.9, duration: 0.45, ease: 'power2.out' });
    gsap.to(ring, { alpha: 0, duration: 0.45, onComplete: () => ring.destroy() });
  }

  /** Glow over the winning stones and a golden stroke drawn across them. */
  showWin(line: Point[]) {
    this.clearWin();
    this.lastMarker.visible = false;
    const first = this.toLocal2(line[0]);
    const last = this.toLocal2(line[line.length - 1]);
    const progress = { t: 0 };
    this.winTween = gsap.to(progress, {
      t: 1,
      duration: 0.5,
      ease: 'power2.out',
      delay: 0.15,
      onUpdate: () => {
        const x = first.x + (last.x - first.x) * progress.t;
        const y = first.y + (last.y - first.y) * progress.t;
        this.winGraphics.clear().moveTo(first.x, first.y).lineTo(x, y).stroke({ color: 0xffd23f, width: this.cell * 0.18, cap: 'round', alpha: 0.9 });
      },
    });
    line.forEach((point, index) => {
      const glow = new Sprite(tex('glow'));
      glow.anchor.set(0.5);
      glow.tint = 0xffd23f;
      glow.blendMode = 'add';
      const p = this.toLocal2(point);
      glow.position.set(p.x, p.y);
      glow.width = glow.height = this.cell * 2;
      glow.alpha = 0;
      this.overlay.addChild(glow);
      this.winGlows.push(glow);
      gsap.to(glow, { alpha: 0.9, duration: 0.25, delay: 0.08 * index });
      const node = this.nodes.get(point.y * this.size + point.x);
      if (node) {
        const s = node.stone.scale.x;
        gsap.to(node.stone.scale, { x: s * 1.15, y: s * 1.15, duration: 0.2, delay: 0.08 * index, yoyo: true, repeat: 1 });
      }
    });
  }

  clearWin() {
    this.winTween?.kill();
    this.winTween = null;
    this.winGraphics.clear();
    for (const glow of this.winGlows) glow.destroy();
    this.winGlows = [];
  }

  override destroy(options?: Parameters<Container['destroy']>[0]) {
    this.winTween?.kill();
    super.destroy(options);
  }

  update(ticker: Ticker) {
    this.time += ticker.deltaMS / 1000;
    this.winGlows.forEach((glow, index) => {
      glow.alpha = 0.55 + 0.35 * Math.sin(this.time * 6 - index * 0.6);
    });
    if (this.pendingTouch) this.ghost.alpha = 0.45 + 0.25 * Math.sin(this.time * 8);
  }
}

import { Container, Graphics, NineSliceSprite, type Text } from 'pixi.js';

import { tex } from '../app/textures';
import { INK } from '../svg/palette';
import { label } from './Label';
import { TabBar } from './TabBar';

const HEADER_H = 118;
const TEXT = 0xe7dcff;
const DIM = 0xb9abe0;
const GOLD = 0xffd84a;
const RED = 0xff5a5a;

type Page = 'compare' | 'forbidden' | 'opening' | 'play';

/**
 * The rules page on the home screen: how the three rule choices differ, what
 * renju forbids, how the RIF opening runs, and the AI / 托管 / leaderboard
 * rules. Each page is drawn to a fixed design width and scaled to fit.
 */
export class RulesView extends Container {
  private bg = new NineSliceSprite({ texture: tex('tile-dark'), leftWidth: 40, rightWidth: 40, topHeight: 40, bottomHeight: 40 });
  private title: Text;
  private pages: TabBar;
  private page = new Container();
  private current: Page = 'compare';
  private w = 560;
  private h = 520;

  constructor() {
    super();
    this.title = label('规则说明', 'heading', { fontSize: 28, fill: GOLD });
    this.title.anchor.set(0, 0.5);
    this.pages = new TabBar(
      [
        { id: 'compare', text: '三种规则', icon: 'book' },
        { id: 'forbidden', text: '禁手', icon: 'close' },
        { id: 'opening', text: '开局', icon: 'swords' },
        { id: 'play', text: '托管与排行', icon: 'robot' },
      ],
      'compare',
      (id) => {
        this.current = id as Page;
        this.render();
      },
    );
    this.addChild(this.bg, this.title, this.pages, this.page);
  }

  layout(width: number, height: number) {
    this.w = Math.max(300, width);
    this.h = Math.max(360, height);
    this.bg.width = this.w;
    this.bg.height = this.h;
    this.bg.position.set(-this.w / 2, -this.h / 2);
    this.title.position.set(-this.w / 2 + 26, -this.h / 2 + 36);
    const tabScale = Math.min(1, (this.w - 32) / this.pages.barWidth);
    this.pages.scale.set(tabScale);
    this.pages.position.set(-(this.pages.barWidth * tabScale) / 2, -this.h / 2 + 60);
    this.render();
  }

  private render() {
    for (const child of this.page.removeChildren()) child.destroy({ children: true });
    const room = { w: this.w - 36, h: this.h - HEADER_H - 20 };
    // Phones get a narrower design (stacked cards instead of the table) rather than tiny text.
    const design = room.w < 440 ? 360 : 520;
    const content = new Container();
    const height = this.current === 'compare' ? this.compare(content, design)
      : this.current === 'forbidden' ? this.forbidden(content, design)
        : this.current === 'opening' ? this.opening(content, design)
          : this.play(content, design);
    // Fit the page into the panel below the tabs, never enlarging it.
    const scale = Math.min(1, room.w / design, room.h / height);
    content.scale.set(scale);
    content.position.set(-(design * scale) / 2, -this.h / 2 + HEADER_H + (room.h - height * scale) / 2);
    this.page.addChild(content);
  }

  // ---- pages ----------------------------------------------------------------------------

  private compare(root: Container, width: number) {
    if (width < 440) return this.compareCards(root, width);
    const columns = [120, 128, 128, 144];
    const rows: string[][] = [
      ['', '无禁手', '连珠', '连珠 · 三手交换\n五手两打'],
      ['黑棋限制', '无', '不能下三三、\n四四、长连', '同连珠'],
      ['怎样算赢', '五子或以上', '黑棋恰好五子；\n白棋五子以上', '同连珠'],
      ['开局', '黑棋随意先下', '黑棋随意先下', '先摆三手可交换，\n第五手给两个点'],
      ['先手优势', '很大\n（理论上黑必胜）', '较小', '最平衡'],
      ['适合', '休闲、入门', '想认真下的玩家', '比赛、高手对局'],
    ];
    let y = 0;
    rows.forEach((row, r) => {
      const lines = Math.max(...row.map((cell) => cell.split('\n').length));
      const rowH = 22 + lines * 22;
