export function brainInfo(id: BrainId) {
  return BRAINS.find((brain) => brain.id === id) ?? BRAINS[0];
}

type Random = () => number;

/** Whether `stone` may play at `point` under `rule` (renju forbids some points to black). */
function legal(board: Board, point: Point, stone: Stone, rule: Rule) {
  return rule !== 'renju' || stone !== BLACK || forbiddenAt(board, point.x, point.y) === null;
}

/** The first `count` legal moves of a ranked list, checking only as far as needed. */
function legalMoves(board: Board, ranked: RankedMove[], stone: Stone, rule: Rule, count = ranked.length) {
  const moves: RankedMove[] = [];
  for (const move of ranked) {
    if (moves.length >= count) break;
    if (legal(board, move, stone, rule)) moves.push(move);
  }
  return moves;
}

/** Win now if possible, otherwise block the opponent's immediate five. */
function forcedMove(board: Board, stone: Stone, rule: Rule): Point | null {
  const candidates = candidateMoves(board, 1);
  for (const point of candidates) {
    if (evaluatePoint(board, point.x, point.y, stone).score >= SCORE.FIVE && legal(board, point, stone, rule)) return point;
  }
  // No need to block a five the opponent is not allowed to play, and no way to
  // block one on a point we are not allowed to play ourselves.
  const other = opponent(stone);
  for (const point of candidates) {
    if (evaluatePoint(board, point.x, point.y, other).score >= SCORE.FIVE && legal(board, point, other, rule) && legal(board, point, stone, rule)) return point;
  }
  return null;
}

/** Sprout: takes a win and blocks a five, otherwise picks loosely from good moves. */
function sproutMove(board: Board, stone: Stone, random: Random, rule: Rule): Point {
  const forced = forcedMove(board, stone, rule);
  if (forced) return forced;
  const ranked = legalMoves(board, rankMoves(board, stone, 0.55), stone, rule, 6);
  // Sometimes it simply does not notice an open four being built.
  const pool = ranked.slice(0, Math.min(6, ranked.length));
  const pick = pool[Math.floor(Math.pow(random(), 1.6) * pool.length)] ?? ranked[0];
  return pick;
}

/** Fox: one-ply greedy on attack + defence with light noise among near-equal moves. */
function foxMove(board: Board, stone: Stone, random: Random, rule: Rule): Point {
  const forced = forcedMove(board, stone, rule);
  if (forced) return forced;
  const ranked = legalMoves(board, rankMoves(board, stone, 0.95), stone, rule, 3);
  const best = ranked[0];
  const close = ranked.filter((move) => move.score >= best.score * 0.92).slice(0, 3);
  return close[Math.floor(random() * close.length)] ?? best;
}

/** Whole-position heuristic from `stone`'s point of view. */
function evaluateBoard(board: Board, stone: Stone) {
  const other = opponent(stone);
  let mine = 0;
  let theirs = 0;
  for (const point of candidateMoves(board, 1)) {
    mine = Math.max(mine, evaluatePoint(board, point.x, point.y, stone).score);
    theirs = Math.max(theirs, evaluatePoint(board, point.x, point.y, other).score);
  }
  return mine - theirs * 1.1;
}

/** Owl: alpha-beta over the top candidates, iterative deepening within a time budget. */
function owlMove(board: Board, stone: Stone, rule: Rule, budgetMs = 900): Point {
  const forced = forcedMove(board, stone, rule);
  if (forced) return forced;

  const work = cloneBoard(board);
  const started = Date.now();
  let timedOut = false;
  const width = 9;

  function search(depth: number, toMove: Stone, alpha: number, beta: number): number {
    if (Date.now() - started > budgetMs) {
      timedOut = true;
      return evaluateBoard(work, stone);
    }
    if (depth === 0) return evaluateBoard(work, stone);
    const moves = legalMoves(work, rankMoves(work, toMove, 1), toMove, rule, width);
    if (moves.length === 0) return 0;
    const maximizing = toMove === stone;
    let best = maximizing ? -Infinity : Infinity;
    for (const move of moves) {
      set(work, move.x, move.y, toMove);
      let value: number;
      if (winningLine(work, move.x, move.y, toMove, rule)) {
        value = (maximizing ? 1 : -1) * (SCORE.FIVE * 10 + depth);
      } else {
        value = search(depth - 1, opponent(toMove), alpha, beta);
      }
      set(work, move.x, move.y, EMPTY);
      if (maximizing) {
        best = Math.max(best, value);
        alpha = Math.max(alpha, value);
      } else {
        best = Math.min(best, value);
        beta = Math.min(beta, value);
      }
      if (beta <= alpha || timedOut) break;
    }
    return best;
  }

  const roots = legalMoves(work, rankMoves(work, stone, 1), stone, rule, 12);
  let bestMove: Point = roots[0];
  for (let depth = 2; depth <= 5; depth += 1) {
    let depthBest: Point | null = null;
    let depthScore = -Infinity;
    for (const move of roots) {
      set(work, move.x, move.y, stone);
      const value = winningLine(work, move.x, move.y, stone, rule)
        ? SCORE.FIVE * 100
        : search(depth - 1, opponent(stone), -Infinity, Infinity);
      set(work, move.x, move.y, EMPTY);
      if (timedOut) break;
      // Tie-break toward the stronger static move so play stays natural.
      const tieBreak = move.score / 1e9;
      if (value + tieBreak > depthScore) {
        depthScore = value + tieBreak;
        depthBest = move;
      }
    }
    if (timedOut) break;
    if (depthBest) bestMove = depthBest;
    if (depthScore >= SCORE.FIVE * 10) break;
  }
  return bestMove;
}

export function chooseMove(id: BrainId, board: Board, stone: Stone, random: Random = Math.random, rule: Rule = 'freestyle'): Point {
  // 'master' reaches here only as a stand-in when its engine is unavailable.
  const move: Point | undefined = id === 'sprout' ? sproutMove(board, stone, random, rule) : id === 'fox' ? foxMove(board, stone, random, rule) : owlMove(board, stone, rule);
  if (move) return { x: move.x, y: move.y };
  // Every nearby point is forbidden (renju): take any legal point on the board.
  const size = sizeOf(board);
  for (let index = 0; index < board.length; index += 1) {
    const point = { x: index % size, y: Math.floor(index / size) };
    if (board[index] === EMPTY && legal(board, point, stone, rule)) return point;
  }
  return { x: 0, y: 0 };
}

// ---- RIF opening decisions (heuristic brains; the master asks its engine instead) ------

/** The tentative white, with white to move after three stones: true to swap and take black. */
export function heuristicSwap(board: Board, random: Random = Math.random): boolean {
  const score = evaluateBoard(board, BLACK);
  return score > 0 || (score === 0 && random() < 0.5);
}

/** Two 5th moves for black that are not symmetric to each other, `first` (or the best) first. */
export function heuristicOffers(board: Board, rule: Rule, first?: Point): Point[] {
  const ranked = legalMoves(board, rankMoves(board, BLACK, 0.9), BLACK, rule);
  const a = first ?? ranked[0];
  if (!a) return [];
  const b = ranked.find((move) => !(move.x === a.x && move.y === a.y) && !equivalentOffers(board, a, move));
  return b ? [{ x: a.x, y: a.y }, { x: b.x, y: b.y }] : [{ x: a.x, y: a.y }];
}

/** White keeps the offered 5th move that leaves the position best for white. */
export function heuristicChoose(board: Board, offers: Point[]): Point {
  let best = offers[0];
  let bestScore = -Infinity;
  for (const offer of offers) {
    const work = cloneBoard(board);
    set(work, offer.x, offer.y, BLACK);
    const score = evaluateBoard(work, WHITE);
    if (score > bestScore) {
      bestScore = score;
      best = offer;
    }
  }
  return best;
}

import { getProfile, updateProfile } from './storage';
import { stopSpeaking } from './voice';

/**
 * Synthesised sound effects, no audio files. Everything is built from soft
 * sine "bell" partials, filtered noise and gentle envelopes, then sent through
 * a warm low-pass, a short generated reverb and a compressor so nothing
 * sounds raw or harsh. A limiter at the very end keeps stacked cues from
 * clipping.
 */

type Bus = { audio: AudioContext; dry: AudioNode; wet: AudioNode };

let bus: Bus | null = null;

function makeImpulse(audio: AudioContext, seconds: number, decay: number) {
  const length = Math.ceil(audio.sampleRate * seconds);
  const buffer = audio.createBuffer(2, length, audio.sampleRate);
  for (let channel = 0; channel < 2; channel += 1) {
    const data = buffer.getChannelData(channel);
    for (let i = 0; i < length; i += 1) data[i] = (Math.random() * 2 - 1) * (1 - i / length) ** decay;
  }
  return buffer;
}

function getBus(): Bus | null {
  if (getProfile().muted) return null;
  if (!bus) {
    const Ctor = window.AudioContext ?? (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
    if (!Ctor) return null;
    const audio = new Ctor();
    // warm low-pass → gain → gentle compressor → brick-wall limiter. The make-up
    // gain sits before the dynamics so stacked cues (boom + bells + voice) never clip.
    const warm = audio.createBiquadFilter();
    warm.type = 'lowpass';
    warm.frequency.value = 7000;
    warm.Q.value = 0.5;
    const master = audio.createGain();
    master.gain.value = 1.5;
    const compressor = audio.createDynamicsCompressor();
    compressor.threshold.value = -18;
    compressor.ratio.value = 3;
    compressor.attack.value = 0.005;
    compressor.release.value = 0.2;
    const limiter = audio.createDynamicsCompressor();
    limiter.threshold.value = -2;
    limiter.knee.value = 0;
    limiter.ratio.value = 20;
    limiter.attack.value = 0.001;
    limiter.release.value = 0.1;
    warm.connect(master).connect(compressor).connect(limiter).connect(audio.destination);
    const reverb = audio.createConvolver();
    reverb.buffer = makeImpulse(audio, 1.4, 3);
    const wetGain = audio.createGain();
    wetGain.gain.value = 0.22;
    reverb.connect(wetGain).connect(warm);
    bus = { audio, dry: warm, wet: reverb };
  }
  if (bus.audio.state === 'suspended') void bus.audio.resume();
  return bus;
}

/** Route a voice to the dry path and (a little of it) to the reverb. */
function send(b: Bus, node: AudioNode, reverb = 0.6) {
  node.connect(b.dry);
  if (reverb > 0) {
    const g = b.audio.createGain();
    g.gain.value = reverb;
    node.connect(g).connect(b.wet);
  }
}

/** Soft bell: a sine fundamental with a quiet octave and fifth, quick attack, long decay. */
function bell(frequency: number, options: { gain?: number; delay?: number; decay?: number; reverb?: number; pan?: number } = {}) {
  const b = getBus();
  if (!b) return;
  const { audio } = b;
  const start = audio.currentTime + (options.delay ?? 0);
  const decay = options.decay ?? 0.6;
  const out = audio.createGain();
  out.gain.setValueAtTime(0.0001, start);
  out.gain.linearRampToValueAtTime(options.gain ?? 0.12, start + 0.008);
  out.gain.exponentialRampToValueAtTime(0.0001, start + decay);
  let tail: AudioNode = out;
  if (options.pan && audio.createStereoPanner) {
    const panner = audio.createStereoPanner();
    panner.pan.value = options.pan;
    out.connect(panner);
    tail = panner;
  }
  for (const [ratio, level] of [[1, 1], [2, 0.18], [3, 0.06]] as const) {
    const osc = audio.createOscillator();
    osc.type = 'sine';
    osc.frequency.value = frequency * ratio;
    const g = audio.createGain();
    g.gain.value = level;
    osc.connect(g).connect(out);
    osc.start(start);
    osc.stop(start + decay + 0.05);
  }
  send(b, tail, options.reverb ?? 0.6);
}

/** Pitched sine with a smooth glide; for thumps and gentle risers. */
function glide(from: number, to: number, duration: number, options: { gain?: number; delay?: number; attack?: number; reverb?: number } = {}) {
  const b = getBus();
  if (!b) return;
  const { audio } = b;
  const start = audio.currentTime + (options.delay ?? 0);
  const osc = audio.createOscillator();
  osc.type = 'sine';
  osc.frequency.setValueAtTime(from, start);
  osc.frequency.exponentialRampToValueAtTime(to, start + duration);
  const g = audio.createGain();
  g.gain.setValueAtTime(0.0001, start);
  g.gain.linearRampToValueAtTime(options.gain ?? 0.15, start + (options.attack ?? 0.01));
  g.gain.exponentialRampToValueAtTime(0.0001, start + duration);
  osc.connect(g);
  osc.start(start);
  osc.stop(start + duration + 0.05);
  send(b, g, options.reverb ?? 0.2);
}

/** Band-passed noise; `to` sweeps the band for whooshes. */
function hiss(duration: number, options: { gain?: number; from?: number; to?: number; q?: number; delay?: number; attack?: number; reverb?: number } = {}) {
  const b = getBus();
  if (!b) return;
  const { audio } = b;
  const start = audio.currentTime + (options.delay ?? 0);
  const buffer = audio.createBuffer(1, Math.ceil(audio.sampleRate * duration), audio.sampleRate);
  const data = buffer.getChannelData(0);
  for (let i = 0; i < data.length; i += 1) data[i] = Math.random() * 2 - 1;
  const source = audio.createBufferSource();
  source.buffer = buffer;
  const filter = audio.createBiquadFilter();
  filter.type = 'bandpass';
  filter.Q.value = options.q ?? 1.2;
  filter.frequency.setValueAtTime(options.from ?? 1200, start);
  if (options.to) filter.frequency.exponentialRampToValueAtTime(options.to, start + duration);
  const g = audio.createGain();
  g.gain.setValueAtTime(0.0001, start);
  g.gain.linearRampToValueAtTime(options.gain ?? 0.1, start + (options.attack ?? 0.005));
  g.gain.exponentialRampToValueAtTime(0.0001, start + duration);
  source.connect(filter).connect(g);
  source.start(start);
  send(b, g, options.reverb ?? 0.3);
}

/**
 * A filtered harmonic tone (saw/square/triangle through a low-pass that opens
 * with the attack): brassy for fanfares, plucky for ticks.
 */
function tone(frequency: number, duration: number, options: { type?: OscillatorType; gain?: number; delay?: number; attack?: number; cutoff?: number; detune?: number; reverb?: number; pan?: number; glideTo?: number } = {}) {
  const b = getBus();
  if (!b) return;
  const { audio } = b;
  const start = audio.currentTime + (options.delay ?? 0);
  const attack = options.attack ?? 0.02;
  const filter = audio.createBiquadFilter();
  filter.type = 'lowpass';
  filter.Q.value = 1.4;
  const cutoff = options.cutoff ?? 2400;
  filter.frequency.setValueAtTime(cutoff * 0.25, start);
  filter.frequency.exponentialRampToValueAtTime(cutoff, start + attack + 0.04);
  filter.frequency.exponentialRampToValueAtTime(cutoff * 0.4, start + duration);
  const g = audio.createGain();
  g.gain.setValueAtTime(0.0001, start);
  g.gain.linearRampToValueAtTime(options.gain ?? 0.08, start + attack);
  g.gain.setValueAtTime(options.gain ?? 0.08, start + Math.max(attack, duration * 0.6));
  g.gain.exponentialRampToValueAtTime(0.0001, start + duration);
  // Two slightly detuned voices for a fuller, ensemble sound.
  for (const cents of [-(options.detune ?? 7), options.detune ?? 7]) {
    const osc = audio.createOscillator();
    osc.type = options.type ?? 'sawtooth';
    osc.frequency.setValueAtTime(frequency, start);
    if (options.glideTo) osc.frequency.exponentialRampToValueAtTime(options.glideTo, start + duration);
    osc.detune.value = cents;
    osc.connect(filter);
    osc.start(start);
    osc.stop(start + duration + 0.05);
  }
  filter.connect(g);
  let tail: AudioNode = g;
  if (options.pan && audio.createStereoPanner) {
    const panner = audio.createStereoPanner();
    panner.pan.value = options.pan;
    g.connect(panner);
    tail = panner;
  }
  send(b, tail, options.reverb ?? 0.35);
}

/** Low-passed noise burst whose cutoff falls: the body of an explosion. */
function rumble(duration: number, options: { gain?: number; from?: number; to?: number; delay?: number } = {}) {
  const b = getBus();
  if (!b) return;
  const { audio } = b;
  const start = audio.currentTime + (options.delay ?? 0);
  const buffer = audio.createBuffer(1, Math.ceil(audio.sampleRate * duration), audio.sampleRate);
  const data = buffer.getChannelData(0);
  // Brown-ish noise: integrated white noise has the weight a boom needs.
  let last = 0;
  for (let i = 0; i < data.length; i += 1) {
    last = (last + 0.04 * (Math.random() * 2 - 1)) / 1.04;
    data[i] = last * 3.5;
  }
  const source = audio.createBufferSource();
  source.buffer = buffer;
  const filter = audio.createBiquadFilter();
  filter.type = 'lowpass';
  filter.frequency.setValueAtTime(options.from ?? 1800, start);
  filter.frequency.exponentialRampToValueAtTime(options.to ?? 90, start + duration);
  const g = audio.createGain();
  g.gain.setValueAtTime(0.0001, start);
  g.gain.linearRampToValueAtTime(options.gain ?? 0.5, start + 0.006);
  g.gain.exponentialRampToValueAtTime(0.0001, start + duration);
  source.connect(filter).connect(g);
  source.start(start);
  send(b, g, 0.35);
}

/** Decode a compressed clip (e.g. a bundled voice line); null if audio is unavailable. */
export async function decodeClip(data: ArrayBuffer): Promise<AudioBuffer | null> {
  const audio = getBus()?.audio;
  if (!audio) return null;
  return await audio.decodeAudioData(data);
}

const leadIns = new WeakMap<AudioBuffer, number>();

/**
 * Seconds of near-silence at the start of a clip (TTS output carries ~0.18 s),
 * less a short margin; skipped so a line lands on its animation beat.
 */
function leadIn(buffer: AudioBuffer) {
  let offset = leadIns.get(buffer);
  if (offset === undefined) {
    const data = buffer.getChannelData(0);
    let index = 0;
    while (index < data.length && Math.abs(data[index]) < 0.01) index += 1;
    offset = index < data.length ? Math.max(0, index / buffer.sampleRate - 0.02) : 0;
    leadIns.set(buffer, offset);
  }
  return offset;
}

/** Play a decoded clip through the effects chain (dry, a touch of reverb). Returns a stopper. */
export function playClip(buffer: AudioBuffer, gain = 1): (() => void) | null {
  const b = getBus();
  if (!b) return null;
  const source = b.audio.createBufferSource();
  source.buffer = buffer;
  const g = b.audio.createGain();
  g.gain.value = gain;
  source.connect(g);
  send(b, g, 0.12);
  source.start(0, leadIn(buffer));
  return () => {
    try {
      source.stop();
    } catch {
      /* already finished */
    }
  };
}

