    hiss(0.035, { gain: 0.34, from: 2600, q: 2.5, reverb: 0.2 });
  },
  /** Gentle "nope". */
  invalid: () => {
    glide(300, 240, 0.12, { gain: 0.14 });
    glide(240, 200, 0.14, { gain: 0.1, delay: 0.1 });
  },
  win: () => {
    [C5, E5, G5, C6].forEach((f, i) => bell(f, { gain: 0.12, delay: i * 0.11, decay: 0.9, pan: (i - 1.5) * 0.2 }));
    [C6, E6, G6].forEach((f) => bell(f, { gain: 0.06, delay: 0.5, decay: 1.6 }));
  },
  lose: () => {
    [A4, F4, D4].forEach((f, i) => bell(f, { gain: 0.1, delay: i * 0.2, decay: 1.1 }));
  },
  /** Chest landing: soft thud and a puff. */
  land: () => {
    glide(140, 60, 0.28, { gain: 0.3, reverb: 0.2 });
    hiss(0.2, { gain: 0.08, from: 500, to: 200, q: 0.8 });
  },
  /** Crouch-and-leap: a springy upward boing and a short whoosh. */
  jump: () => {
    glide(180, 620, 0.22, { gain: 0.12, attack: 0.02, reverb: 0.15 });
    hiss(0.25, { gain: 0.05, from: 700, to: 2600, q: 1.2, attack: 0.08 });
  },
  /** The mid-air turn: an airy swish. */
  spin: () => hiss(0.3, { gain: 0.07, from: 1200, to: 4200, q: 2.2, attack: 0.1, reverb: 0.25 }),
  /** Tier-up: a bright major arpeggio that sits higher with every tier (0..3). */
  upgrade: (tier = 1) => {
    const up = 2 ** ((tier - 1) * 2 / 12);
    hiss(0.4, { gain: 0.06, from: 600, to: 4200, q: 1.5, attack: 0.15, reverb: 0.5 });
    [C5, E5, G5, C6].forEach((f, i) => bell(f * up, { gain: 0.1, delay: 0.04 + i * 0.06, decay: 0.9, pan: (i - 1.5) * 0.25 }));
    [C5, E5, G5].forEach((f) => tone(f * up, 0.5, { type: 'triangle', gain: 0.035, delay: 0.24, attack: 0.02, cutoff: 3200 }));
  },
  /** Charge before opening: a riser whose pitch keeps climbing, with a trembling whoosh. */
  charge: (duration = 1) => {
    hiss(duration, { gain: 0.1, from: 300, to: 3200, q: 2.5, attack: duration * 0.8, reverb: 0.3 });
    glide(160, 900, duration, { gain: 0.08, attack: duration * 0.7 });
    tone(110, duration, { type: 'sawtooth', gain: 0.05, attack: duration * 0.8, cutoff: 900, glideTo: 330, reverb: 0.2 });
  },
  /** The burst: sub-bass drop, a noise blast and a shower of bells; `strength` 0..1 scales it. */
  open: (strength = 1) => {
    glide(120, 38, 0.7, { gain: 0.34 + 0.12 * strength, reverb: 0.4 });
    rumble(0.9 + 0.5 * strength, { gain: 0.32 + 0.25 * strength, from: 2400, to: 70 });
    hiss(0.5, { gain: 0.08, from: 3000, to: 800, q: 0.7, reverb: 0.6, delay: 0.02 });
    [C6, D6, E6, G6, A5 * 2].forEach((f, i) => bell(f, { gain: 0.07, delay: 0.12 + i * 0.06, decay: 1.2, pan: (Math.random() - 0.5) * 0.6 }));
  },
  /** Victory horn for the reveal: a brassy call, then a held major chord. Bigger chests get the long version. */
  fanfare: (tier = 0) => {
    const notes: Array<[number, number, number]> = tier >= 2
      ? [[G4, 0, 0.14], [C5, 0.14, 0.14], [E5, 0.28, 0.14], [G5, 0.42, 0.9]]
      : [[C5, 0, 0.14], [G5, 0.14, 0.7]];
    for (const [f, delay, length] of notes) tone(f, length, { type: 'sawtooth', gain: 0.07, delay, attack: 0.03, cutoff: 2600 });
    const hold = notes[notes.length - 1][1];
    for (const f of [C5, E5, G5]) tone(f, 1.1, { type: 'sawtooth', gain: 0.035, delay: hold, attack: 0.06, cutoff: 1800, detune: 10 });
    bell(C6 * 2, { gain: 0.05, delay: hold, decay: 1.4 });
  },
  /** A reward card pops out. */
  pop: () => {
    glide(420, 980, 0.09, { gain: 0.16, reverb: 0.15 });
    bell(E6, { gain: 0.06, delay: 0.03, decay: 0.3 });
  },
  /** One count-up tick; soft and short because it repeats quickly. */
  tick: (step = 0) => tone(1600 + (step % 6) * 90, 0.045, { type: 'square', gain: 0.02, attack: 0.002, cutoff: 5000, detune: 0, reverb: 0.05 }),
  /** Tiny coin chime; played many times in a row, so it is quiet and varies a little. */
  coin: () => bell([G6, A5 * 2, E6, D6][Math.floor(Math.random() * 4)], { gain: 0.12, decay: 0.3, reverb: 0.3, pan: (Math.random() - 0.5) * 0.5 }),
};

export function setMuted(muted: boolean) {
  updateProfile({ muted });
  if (muted) {
    void bus?.audio.suspend();
    stopSpeaking();
  }
}

import type { BrainId } from '../gomoku/ai';
import { LocalProgress, PROGRESS_PREFIX } from '../profile/localProgress';
import { COUNTERS, type ProgressReceipt } from '../profile/progress';

/** Persistent player profile, stored in localStorage. */
export type Profile = {
  coins: number;
  gems: number;
  crowns: number;
  streak: number;
  bestStreak: number;
  wins: number;
  losses: number;
  draws: number;
  muted: boolean;
  lastBrain: BrainId;
  playFirst: boolean;
  /** Privacy: whether the master's public record (托管 and challenge games) may show this player's name. */
  showInMasterRecord: boolean;
  nickname: string;
};

const defaults = (): Profile => ({
  coins: 0,
  gems: 0,
  crowns: 0,
  streak: 0,
  bestStreak: 0,
  wins: 0,
  losses: 0,
  draws: 0,
  muted: false,
  lastBrain: 'fox',
  playFirst: true,
  showInMasterRecord: false,
  nickname: `棋手${Math.floor(100 + Math.random() * 900)}`,
});

const initial = defaults();
const browserStorage = (() => { try { return localStorage; } catch { return null; } })();
// Two tabs opening the old save for the first time must share one import ID.
export const localProgress = typeof navigator !== 'undefined' && navigator.locks
  ? await navigator.locks.request('pixi-gomoku:profile-migration', () => new LocalProgress(browserStorage))
  : new LocalProgress(browserStorage);
const listeners = new Set<(profile: Profile) => void>();
const localListeners = new Set<() => void>();
const notify = () => { for (const listener of listeners) listener(getProfile()); };

export function getProfile(): Readonly<Profile> {
  return { ...initial, ...localProgress.preferences(), ...localProgress.totals() } as Profile;
}

export function updateProfile(patch: Partial<Profile> | ((current: Profile) => Partial<Profile>)) {
  const profile = getProfile();
  const next = typeof patch === 'function' ? patch(profile) : patch;
  const changed = localProgress.record(profile, next);
  const preferences = Object.fromEntries(Object.entries(next).filter(([key]) => ![...COUNTERS, 'streak', 'bestStreak'].includes(key)));
  if (Object.keys(preferences).length) localProgress.savePreferences(preferences);
  notify();
  if (changed) for (const listener of localListeners) listener();
}

export function setProfileAccount(userId: string | null) { localProgress.setAccount(userId); notify(); }
export function acceptProfile(userId: string, receipt: ProgressReceipt) { localProgress.accept(userId, receipt); notify(); }
export function onLocalProgress(listener: () => void) { localListeners.add(listener); return () => localListeners.delete(listener); }

if (typeof window !== 'undefined') window.addEventListener('storage', (event: StorageEvent) => {
  if (event.key?.startsWith(PROGRESS_PREFIX)) {
    notify();
    if (event.key.startsWith(PROGRESS_PREFIX + 'event:')) for (const listener of localListeners) listener();
  }
});

export function onProfileChange(listener: (profile: Profile) => void) {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

import { Container, NineSliceSprite, Sprite, Text } from 'pixi.js';
import gsap from 'gsap';

import { getProfile, onProfileChange } from '../app/storage';
import { tex } from '../app/textures';
import { label } from './Label';

export type Currency = 'coins' | 'gems' | 'crowns';

const PILL_W = 108;
const GAP = 8;
const format = (value: number) => value.toLocaleString('en-US');
const ICON: Record<Currency, string> = { coins: 'coin', gems: 'gem', crowns: 'crown' };

/** Top-right currency counters, as in the reference result screen. */
export class Hud extends Container {
  private values = new Map<Currency, { text: Text; value: { v: number }; icon: Sprite; baseScale: number }>();
  private unsubscribe: () => void;

  constructor() {
    super();
    const profile = getProfile();
    let x = 0;
    for (const currency of ['coins', 'gems', 'crowns'] as Currency[]) {
      const item = new Container();
      const bg = new NineSliceSprite({ texture: tex('pill'), leftWidth: 24, rightWidth: 24, topHeight: 20, bottomHeight: 20 });
      bg.width = PILL_W;
      bg.height = 40;
      // Icon sits inside the pill and the count is bold white, as in the reference.
      const icon = new Sprite(tex(ICON[currency]));
      icon.anchor.set(0.5);
      icon.width = icon.height = 28;
      icon.position.set(22, 20);
      const text = label(format(profile[currency]), 'number', { fontSize: 19, stroke: { color: 0x0e0620, width: 4, join: 'round' } });
      text.anchor.set(0, 0.5);
      text.position.set(42, 20);
      item.addChild(bg, icon, text);
      item.x = x;
      x += PILL_W + GAP;
      this.addChild(item);
      this.values.set(currency, { text, value: { v: profile[currency] }, icon, baseScale: icon.scale.x });
    }
    this.unsubscribe = onProfileChange((next) => {
      for (const currency of ['coins', 'gems', 'crowns'] as Currency[]) this.animateTo(currency, next[currency]);
    });
  }

  get totalHeight() {
    return 40;
  }

  get totalWidth() {
    return PILL_W * 3 + GAP * 2;
  }

  /** Global position of a currency icon, for rewards flying into the HUD. */
  iconPosition(currency: Currency) {
    const entry = this.values.get(currency);
    return entry ? entry.icon.getGlobalPosition() : this.getGlobalPosition();
  }

  /** Bump a counter by `amount` for a landing reward, ahead of the profile update. */
  bump(currency: Currency, amount: number) {
    const entry = this.values.get(currency);
    if (!entry) return;
    gsap.killTweensOf(entry.value);
    entry.value.v = Math.round(entry.value.v + amount);
    entry.text.text = format(entry.value.v);
    gsap.killTweensOf(entry.icon.scale);
    const base = entry.baseScale;
    gsap.fromTo(entry.icon.scale, { x: base * 1.35, y: base * 1.35 }, { x: base, y: base, duration: 0.25, ease: 'back.out(3)' });
  }

  private animateTo(currency: Currency, target: number) {
    const entry = this.values.get(currency);
    if (!entry || entry.value.v === target) return;
    gsap.to(entry.value, {
      v: target,
      duration: 0.8,
      ease: 'power2.out',
      onUpdate: () => void (entry.text.text = format(Math.round(entry.value.v))),
    });
    const base = entry.baseScale;
    gsap.killTweensOf(entry.icon.scale);
    gsap.fromTo(entry.icon.scale, { x: base * 1.4, y: base * 1.4 }, { x: base, y: base, duration: 0.4, ease: 'back.out(3)' });
  }

  override destroy(options?: Parameters<Container['destroy']>[0]) {
    this.unsubscribe();
    // The count-up tween writes into a Text that is about to be destroyed.
    for (const entry of this.values.values()) {
      gsap.killTweensOf(entry.value);
      gsap.killTweensOf(entry.icon.scale);
    }
    super.destroy(options);
  }
}

import { Container, NineSliceSprite, Sprite, Text, type Ticker } from 'pixi.js';
import gsap from 'gsap';

import { tex } from '../app/textures';
import type { AvatarId } from '../svg/art';
import type { Stone } from '../gomoku/rules';
import { label } from './Label';

/** Chunky dark tile with avatar, name and stone; a gold frame pulses on the side to move. */
export class PlayerCard extends Container {
  private glow: NineSliceSprite;
  private avatar: Sprite;
  private status: Text;
  private active = false;
  private time = 0;
  private thinking = false;
  readonly cardWidth = 250;

  constructor(options: { name: string; subtitle: string; avatar: AvatarId; stone: Stone; alignRight?: boolean }) {
    super();
    const w = this.cardWidth;
    const h = 92;
    const bg = new NineSliceSprite({ texture: tex('tile-dark'), leftWidth: 40, rightWidth: 40, topHeight: 40, bottomHeight: 40 });
    bg.width = w;
    bg.height = h;
    this.glow = new NineSliceSprite({ texture: tex('tile-frame'), leftWidth: 40, rightWidth: 40, topHeight: 40, bottomHeight: 40 });
    this.glow.width = w + 12;
    this.glow.height = h + 12;
    this.glow.position.set(-6, -6);
    this.glow.alpha = 0;

    this.avatar = new Sprite(tex(`avatar-${options.avatar}`));
    this.avatar.anchor.set(0.5);
    this.avatar.width = this.avatar.height = 70;
    const stone = new Sprite(tex(options.stone === 1 ? 'stone-black' : 'stone-white'));
    stone.anchor.set(0.5);
    stone.width = stone.height = 26;

    const name = label(options.name, 'button', { fontSize: 22, stroke: { color: 0x2a1638, width: 5, join: 'round' } });
    this.status = label(options.subtitle, 'small', { fontSize: 13, fill: 0xd9ccff, fontWeight: '600' });
    name.anchor.set(options.alignRight ? 1 : 0, 0.5);
    this.status.anchor.set(options.alignRight ? 1 : 0, 0.5);

    if (options.alignRight) {
      this.avatar.position.set(w - 44, h / 2 - 2);
      stone.position.set(w - 18, h - 16);
      name.position.set(w - 86, h / 2 - 12);
      this.status.position.set(w - 86, h / 2 + 14);
    } else {
      this.avatar.position.set(44, h / 2 - 2);
      stone.position.set(66, h - 16);
      name.position.set(86, h / 2 - 12);
      this.status.position.set(86, h / 2 + 14);
    }
    this.addChild(bg, this.glow, this.avatar, stone, name, this.status);
  }

  setStatus(text: string) {
    this.status.text = text;
  }

  setActive(active: boolean, thinking = false) {
    this.thinking = thinking;
    if (active === this.active) return;
    this.active = active;
    gsap.to(this.glow, { alpha: active ? 1 : 0, duration: 0.25 });
    gsap.to(this.avatar.scale, { x: this.avatar.scale.x * (active ? 1.08 : 1 / 1.08), y: this.avatar.scale.y * (active ? 1.08 : 1 / 1.08), duration: 0.25, ease: 'back.out(2)' });
  }

  update(ticker: Ticker) {
    this.time += ticker.deltaMS / 1000;
    if (this.active) this.glow.alpha = 0.7 + 0.3 * Math.sin(this.time * 5);
    if (this.thinking) {
      const dots = '.'.repeat(1 + (Math.floor(this.time * 3) % 3));
      this.status.text = `思考中${dots}`;
    }
  }
}

import { describe, expect, test } from 'vitest';
import { BLACK, GomokuGame, WHITE } from '../src/gomoku/rules';

function playAll(game: GomokuGame, moves: Array<[number, number]>) {
  return moves.map(([x, y]) => game.play(x, y));
}

describe('rules', () => {
  test('black moves first and turns alternate', () => {
    const game = new GomokuGame();
    expect(game.turn).toBe(BLACK);
    game.play(7, 7);
    expect(game.turn).toBe(WHITE);
    expect(game.play(7, 7).kind).toBe('invalid');
  });

  test.each([
    ['horizontal', [0, 1]],
    ['vertical', [1, 0]],
    ['diagonal', [1, 1]],
  ] as const)('detects a %s five and returns the line', (_, [dx, dy]) => {
    const game = new GomokuGame();
    const moves: Array<[number, number]> = [];
    for (let i = 0; i < 5; i += 1) {
      moves.push([2 + i * dy, 2 + i * dx]);
      if (i < 4) moves.push([12, 2 + i]);
    }
    const results = playAll(game, moves);
    const last = results.at(-1);
    expect(last?.kind).toBe('win');
    if (last?.kind === 'win') expect(last.line).toHaveLength(5);
    expect(game.winner).toBe(BLACK);
  });

  test('anti-diagonal and overlines win', () => {
    const game = new GomokuGame();
    // Black 6 in a row on the anti-diagonal, filled from the middle outward.
    playAll(game, [[5, 5], [0, 0], [6, 4], [0, 1], [4, 6], [0, 2], [7, 3], [0, 3], [2, 8], [14, 14]]);
    expect(game.over).toBe(false);
    expect(game.play(3, 7).kind).toBe('win');
    expect(game.winLine).toHaveLength(6);
  });

  test('undo restores the board and the side to move', () => {
    const game = new GomokuGame();
    playAll(game, [[7, 7], [7, 8], [8, 8]]);
    game.undo(2);
    expect(game.history).toHaveLength(1);
    expect(game.turn).toBe(WHITE);
    expect(game.play(7, 8).kind).toBe('placed');
  });

  test('resign hands the win to the other side', () => {
    const game = new GomokuGame();
    game.play(7, 7);
    game.resign();
    expect(game.over).toBe(true);
    expect(game.winner).toBe(BLACK);
  });
});

import { readFileSync } from 'node:fs';
import { describe, expect, test } from 'vitest';
import { forbiddenAt, forbiddenPoints } from '../src/gomoku/renju';
import { chooseMove } from '../src/gomoku/ai/brains';
import { BLACK, type Board, createBoard, EMPTY, GomokuGame, WHITE } from '../src/gomoku/rules';

/** Rows top to bottom; X black, O white, anything else empty. Short boards are padded. */
function parse(rows: string[]): Board {
  const board = createBoard();
  rows.forEach((row, y) => [...row].forEach((cell, x) => {
    board[y * 15 + x] = cell === 'X' ? BLACK : cell === 'O' ? WHITE : EMPTY;
  }));
  return board;
}

describe('renju forbidden points', () => {
  test('double-three', () => {
    const board = parse(['', '', '', '', '', '', '', '.....XX', '', '.......X', '.......X']);
    expect(forbiddenAt(board, 7, 7)).toBe('double-three');
  });

  test('a three blocked on one side is not a three', () => {
    const board = parse(['', '', '', '', '', '', '', '....OXX', '', '.......X', '.......X']);
    expect(forbiddenAt(board, 7, 7)).toBeNull();
  });

  test('four-three is allowed', () => {
    const board = parse(['', '', '', '', '', '', '', '....XXX', '', '.......X', '.......X']);
    expect(forbiddenAt(board, 7, 7)).toBeNull();
  });

  test('double-four across two lines', () => {
    const board = parse(['', '', '', '', '', '', '', '....XXX', '', '.......X', '.......X', '.......X']);
    expect(forbiddenAt(board, 7, 7)).toBe('double-four');
  });

  test('double-four inside a single line', () => {
    // X.X?X.X: the middle stone makes two separate fours on the same row.
    const board = parse(['', '', '', '', '', '', '', '...X.X.X.X']);
    expect(forbiddenAt(board, 6, 7)).toBe('double-four');
  });

  test('overline', () => {
    const board = parse(['', '', '', '', '', '', '', '..XXX.XX']);
    expect(forbiddenAt(board, 5, 7)).toBe('overline');
  });

  test('an exact five wins even when it also makes forbidden shapes', () => {
    // Five on the row, plus a double-four through the same point.
    const board = parse(['', '', '', '', '', '', '', '...XXXX', '', '.......X', '.......X', '.......X']);
    expect(forbiddenAt(board, 7, 7)).toBeNull();
  });

  test('a three whose completion point is forbidden is not a three', () => {
    // Found by fuzzing: a naive double-three check flags (9, 9); Rapfi and RIF say it is legal.
    const board = parse([
      'O...........OOO', '', '', '', '', '', '',
      '.......X.X.....',
      '.....X.XX......',
      '.O....X.X......',
      '',
      '.....O....X....',
      '.......O.......',
      '',
      '.........O.....',
    ]);
    expect(forbiddenAt(board, 9, 9)).toBeNull();
  });

  test('leaves the board untouched', () => {
    const board = parse(['', '', '', '', '', '', '', '.....XX', '', '.......X', '.......X']);
    const before = board.slice();
    forbiddenPoints(board);
    expect(board).toEqual(before);
  });

  test('matches Rapfi on fuzzed positions', () => {
    const { positions } = JSON.parse(readFileSync(new URL('./fixtures/renju-rapfi.json', import.meta.url), 'utf8')) as {
      positions: Array<{ rows: string[]; forbidden: Array<[number, number]> }>;
    };
    expect(positions.length).toBeGreaterThan(100);
    for (const { rows, forbidden } of positions) {
      const ours = forbiddenPoints(parse(rows)).map((point) => [point.x, point.y]);
      expect(ours.sort((a, b) => a[1] - b[1] || a[0] - b[0])).toEqual(forbidden);
    }
  });
});

describe('renju games', () => {
  test('the game refuses a forbidden move and keeps black to move', () => {
    const game = new GomokuGame(15, 'renju');
    // Black: (5,7) (6,7) (7,9) (7,10); white far away. (7,7) is then a double-three.
    for (const [x, y] of [[5, 7], [0, 0], [6, 7], [0, 2], [7, 9], [0, 4], [7, 10], [0, 6]] as const) game.play(x, y);
    expect(game.play(7, 7)).toEqual({ kind: 'forbidden', reason: 'double-three' });
    expect(game.turn).toBe(BLACK);
    expect(game.history).toHaveLength(8);
    expect(game.play(8, 7).kind).toBe('placed');
  });

  test('free-style games are unaffected', () => {
    const game = new GomokuGame();
    for (const [x, y] of [[5, 7], [0, 0], [6, 7], [0, 2], [7, 9], [0, 4], [7, 10], [0, 6]] as const) game.play(x, y);
    expect(game.play(7, 7).kind).toBe('placed');
  });

  test('white still wins with an overline', () => {
    const game = new GomokuGame(15, 'renju');
    const moves: Array<[number, number]> = [[14, 14], [2, 3], [14, 12], [3, 3], [14, 10], [4, 3], [12, 14], [6, 3], [12, 12], [7, 3], [10, 12]];
    for (const [x, y] of moves) game.play(x, y);
    expect(game.play(5, 3).kind).toBe('win');
    expect(game.winner).toBe(WHITE);
  });

  test.each(['sprout', 'fox', 'owl'] as const)('%s as black does not block a five on its own forbidden point', (brain) => {
    // White threatens five at (7, 7) (the other end is blocked); for black (7, 7) is a double-three.
    const board = createBoard();
    for (const [x, y] of [[5, 7], [6, 7], [7, 9], [7, 10], [2, 2]]) board[y * 15 + x] = BLACK;
    for (const [x, y] of [[3, 3], [4, 4], [5, 5], [6, 6], [14, 14]]) board[y * 15 + x] = WHITE;
    expect(forbiddenAt(board, 7, 7)).toBe('double-three');
    const move = chooseMove(brain, board, BLACK, () => 0.5, 'renju');
    expect(forbiddenAt(board, move.x, move.y)).toBeNull();
  });

  test.each(['sprout', 'fox', 'owl'] as const)('%s never plays a forbidden point as black', (brain) => {
    let seed = 7;
    const random = () => ((seed = (seed * 16807) % 2147483647) / 2147483647);
    for (let round = 0; round < (brain === 'owl' ? 2 : 6); round += 1) {
      const game = new GomokuGame(15, 'renju');
      while (!game.over && game.history.length < 120) {
        const stone = game.turn;
        const move = chooseMove(stone === BLACK ? brain : 'fox', game.board, stone, random, 'renju');
        expect(game.forbidden(move.x, move.y)).toBeNull();
        expect(game.play(move.x, move.y).kind).not.toBe('invalid');
      }
    }
  }, 120_000);
});

import { describe, expect, test } from 'vitest';
import { equivalentOffers, freshOpening, inOpeningZone, openingPhase, randomOpeningMove } from '../src/gomoku/opening';
import { heuristicChoose, heuristicOffers, heuristicSwap } from '../src/gomoku/ai/brains';
import { forbiddenAt } from '../src/gomoku/renju';
import { BLACK, createBoard, WHITE } from '../src/gomoku/rules';

describe('RIF opening', () => {
  test('phases follow the move count and decisions', () => {
    const state = freshOpening();
    expect(openingPhase('free', 0, state)).toBe('play');
    expect(openingPhase('rif', 0, state)).toBe('place');
    expect(openingPhase('rif', 2, state)).toBe('place');
    expect(openingPhase('rif', 3, state)).toBe('swap');
    expect(openingPhase('rif', 3, { ...state, swapDecided: true })).toBe('play');
    expect(openingPhase('rif', 4, { swapDecided: true, offers: [{ x: 1, y: 1 }] })).toBe('offer');
    expect(openingPhase('rif', 4, { swapDecided: true, offers: [{ x: 1, y: 1 }, { x: 2, y: 2 }] })).toBe('choose');
    expect(openingPhase('rif', 5, { swapDecided: true, offers: [] })).toBe('play');
  });

  test('the first three moves stay near the centre', () => {
    const board = createBoard();
    expect(inOpeningZone(board, 0, { x: 7, y: 7 })).toBe(true);
    expect(inOpeningZone(board, 0, { x: 7, y: 8 })).toBe(false);
    expect(inOpeningZone(board, 1, { x: 8, y: 8 })).toBe(true);
    expect(inOpeningZone(board, 1, { x: 9, y: 7 })).toBe(false);
    expect(inOpeningZone(board, 2, { x: 9, y: 5 })).toBe(true);
    expect(inOpeningZone(board, 2, { x: 10, y: 7 })).toBe(false);
    expect(inOpeningZone(board, 3, { x: 0, y: 0 })).toBe(true);
  });

  test('random opening moves are legal', () => {
    const board = createBoard();
    for (let index = 0; index < 3; index += 1) {
      const move = randomOpeningMove(board, index);
      expect(inOpeningZone(board, index, move)).toBe(true);
      expect(board[move.y * 15 + move.x]).toBe(0);
      board[move.y * 15 + move.x] = index % 2 ? WHITE : BLACK;
    }
  });

  test('offers that mirror each other are equivalent', () => {
    // Black (7,7) (7,5), white (7,6): symmetric about the vertical line x = 7.
    const board = createBoard();
    board[7 * 15 + 7] = BLACK;
    board[5 * 15 + 7] = BLACK;
    board[6 * 15 + 7] = WHITE;
    board[9 * 15 + 7] = WHITE;
    expect(equivalentOffers(board, { x: 5, y: 6 }, { x: 9, y: 6 })).toBe(true);
    expect(equivalentOffers(board, { x: 5, y: 6 }, { x: 5, y: 6 })).toBe(true);
    expect(equivalentOffers(board, { x: 5, y: 6 }, { x: 6, y: 5 })).toBe(false);
  });

  test('an asymmetric position has no equivalent offers', () => {
    const board = createBoard();
    board[7 * 15 + 7] = BLACK;
    board[7 * 15 + 8] = WHITE;
    board[5 * 15 + 9] = BLACK;
    board[10 * 15 + 3] = WHITE;
    expect(equivalentOffers(board, { x: 4, y: 4 }, { x: 10, y: 10 })).toBe(false);
  });
});

describe('AI opening decisions', () => {
  // A typical position after move 4: black (7,7) (8,6), white (7,6) (6,8).
  const position = () => {
    const board = createBoard();
    for (const [x, y] of [[7, 7], [8, 6]]) board[y * 15 + x] = BLACK;
    for (const [x, y] of [[7, 6], [6, 8]]) board[y * 15 + x] = WHITE;
    return board;
  };

  test('offers two legal 5th moves that are not symmetric', () => {
    const board = position();
    const offers = heuristicOffers(board, 'renju');
    expect(offers).toHaveLength(2);
    for (const p of offers) {
      expect(board[p.y * 15 + p.x]).toBe(0);
      expect(forbiddenAt(board, p.x, p.y)).toBeNull();
    }
    expect(equivalentOffers(board, offers[0], offers[1])).toBe(false);
  });

  test('keeps the engine\'s pick as the first offer', () => {
    const offers = heuristicOffers(position(), 'renju', { x: 9, y: 5 });
    expect(offers[0]).toEqual({ x: 9, y: 5 });
    expect(offers).toHaveLength(2);
  });

  test('chooses one of the offers', () => {
    const board = position();
    const offers = heuristicOffers(board, 'renju');
    expect(offers).toContainEqual(heuristicChoose(board, offers));
  });

  test('decides a swap on the three-stone position', () => {
    const board = createBoard();
    for (const [x, y] of [[7, 7], [8, 6]]) board[y * 15 + x] = BLACK;
    board[6 * 15 + 7] = WHITE;
    expect(typeof heuristicSwap(board, () => 0.3)).toBe('boolean');
  });
});

import { afterEach, describe, expect, test, vi } from 'vitest';
import { type FederatedPointerEvent, Texture } from 'pixi.js';

import { BoardView } from '../src/ui/BoardView';
import { BLACK } from '../src/gomoku/rules';

// Exercise real Pixi containers and board coordinates without loading SVGs or a GPU.
vi.mock('../src/app/textures', () => ({ tex: () => Texture.EMPTY }));

const boards: BoardView[] = [];
function setup() {
  const board = new BoardView();
  board.layout(360);
  board.acceptingInput = true;
  board.onCell = vi.fn();
  boards.push(board);
  return board;
}

function tap(board: BoardView, x: number, y: number, pointerType = 'touch') {
  board.emit('pointertap', {
    pointerType,
    global: board.toGlobal(board.toLocal2({ x, y })),
  } as FederatedPointerEvent);
}

function liftFinger(board: BoardView) {
  // Non-hovering touch pointers leave after pointerup; the next tap has a new contact.
  board.emit('pointerleave', { pointerType: 'touch' } as FederatedPointerEvent);
}

afterEach(() => {
  for (const board of boards.splice(0)) board.destroy({ children: true });
});

describe('board touch input', () => {
  test('confirms the same intersection after the first finger has lifted', () => {
    const board = setup();
    tap(board, 7, 7);
    liftFinger(board);
    expect(board.onCell).not.toHaveBeenCalled();
    expect(board.hasTouchPreview).toBe(true);
    tap(board, 7, 7);
    liftFinger(board);
    expect(board.onCell).toHaveBeenCalledExactlyOnceWith({ x: 7, y: 7 });
    expect(board.hasTouchPreview).toBe(false);
  });

  test('moving to a different intersection requires confirmation of the new point', () => {
    const board = setup();
    tap(board, 7, 7);
    liftFinger(board);
    tap(board, 8, 7);
    liftFinger(board);
    expect(board.onCell).not.toHaveBeenCalled();
    tap(board, 8, 7);
    expect(board.onCell).toHaveBeenCalledExactlyOnceWith({ x: 8, y: 7 });
  });

  test.each(['mouse', 'pen'])('%s still places with one tap', (pointerType) => {
    const board = setup();
    tap(board, 7, 7, pointerType);
    expect(board.onCell).toHaveBeenCalledExactlyOnceWith({ x: 7, y: 7 });
  });

  test.each(['pointerupoutside', 'pointercancel'] as const)('%s cancels a pending touch', (event) => {
    const board = setup();
    tap(board, 7, 7);
    board.emit(event, { pointerType: 'touch' } as FederatedPointerEvent);
    expect(board.hasTouchPreview).toBe(false);
    tap(board, 7, 7);
    expect(board.onCell).not.toHaveBeenCalled();
  });

  test.each(['hideGhost', 'clear'] as const)('%s requires a fresh confirmation', (reset) => {
    const board = setup();
    const previews: boolean[] = [];
    board.onTouchPreviewChange = () => previews.push(board.hasTouchPreview);
    tap(board, 7, 7);
    board[reset]();
    tap(board, 7, 7);
    expect(board.onCell).not.toHaveBeenCalled();
    expect(previews).toEqual([true, false, true]);
  });

  test('rejects occupied, out-of-board and disabled input', () => {
    const board = setup();
    board.placeStone(7, 7, BLACK, false);
    for (const pointerType of ['touch', 'mouse']) {
      tap(board, 7, 7, pointerType);
      tap(board, 7, 7, pointerType);
      tap(board, -1, 7, pointerType);
      tap(board, 15, 7, pointerType);
    }
    board.acceptingInput = false;
    tap(board, 8, 7);
    tap(board, 8, 7);
    expect(board.onCell).not.toHaveBeenCalled();
    expect(board.hasTouchPreview).toBe(false);
  });

  test('confirms the same grid point after resizing a scaled board', () => {
    const board = setup();
    board.position.set(20, 100);
    board.scale.set(0.8);
    tap(board, 3, 11);
    liftFinger(board);
    board.layout(600);
    tap(board, 3, 11);
    expect(board.onCell).toHaveBeenCalledExactlyOnceWith({ x: 3, y: 11 });
  });
});

# BoardArt.gd
# 军旗翻翻棋 3D · 棋盘贴图（在 SubViewport 里用 2D 绘制，然后贴到三维棋盘的顶面）
#
# 参照实物军棋棋盘：金黄色的木质板面，深褐色墨线，逐个画出
#   * 公路（细线）、铁路（双线 + 枕木）；
#   * 兵站（圆角方框 + 「兵站」）；
#   * 行营（圆 + 「行营」）；
#   * 大本营（圆角方框 + 「大 / 本营」）；
#   * 前线（圆角方框 + 「山界 / 前线」）与中线的「山 界」横带。
#
# 一切几何都直接来自 JunqiMap 的拓扑，所以画出来的线就是真正能走的线。
#
# 遵循 Godot 4.7 GDScript 2.0 静态类型规范

class_name BoardArt
extends Control

## 每个世界单位对应的贴图像素数
var ppu: float = 200.0
## 中文字体（由 main.gd 注入）
var font: Font = null

const COL_WOOD := Color(0.902, 0.741, 0.290)
const COL_WOOD_DARK := Color(0.741, 0.553, 0.145)
const COL_CAMP := Color(0.867, 0.694, 0.239)
const COL_INK := Color(0.267, 0.106, 0.055)
const COL_INK_SOFT := Color(0.267, 0.106, 0.055, 0.34)
const COL_RAIL := Color(0.180, 0.129, 0.106)

## 兵站方框尺寸（世界单位：宽 × 深）
const BOX := Vector2(0.88, 0.40)
## 行营圆半径（世界单位）
const CAMP_R: float = 0.31

var _box_style: StyleBoxFlat = null
var _hq_style: StyleBoxFlat = null


func _ready() -> void:
	if font == null:
		font = ThemeDB.fallback_font
	_box_style = _make_box_style(4.0, 10)
	_hq_style = _make_box_style(6.0, 10)
	queue_redraw()


func _make_box_style(width: float, radius: int) -> StyleBoxFlat:
	var sb := StyleBoxFlat.new()
	sb.draw_center = false
	sb.border_color = COL_INK
	sb.set_border_width_all(int(width))
	sb.set_corner_radius_all(radius)
	return sb


# ==================== 绘制 ====================

func _draw() -> void:
	draw_rect(Rect2(Vector2.ZERO, size), COL_WOOD, true)
	_draw_grain()
	_draw_roads()
	_draw_rails()
	_draw_mountain_band()
	_draw_cells()
	_draw_border()


## 世界坐标（XZ）→ 贴图像素
func _px(v: Vector2) -> Vector2:
	return (v - JunqiMap.art_origin()) * ppu


func _cell_px(pos: Vector2i) -> Vector2:
	return _px(Vector2(JunqiMap.col_x(pos.y), JunqiMap.row_z(pos.x)))


func _draw_grain() -> void:
	var rng := RandomNumberGenerator.new()
	rng.seed = 20240926
	for i in 220:
		var x0: float = rng.randf() * size.x
		var amp: float = rng.randf_range(2.0, 11.0)
		var freq: float = rng.randf_range(0.5, 2.4)
		var phase: float = rng.randf() * TAU
		var col := COL_WOOD_DARK
		col.a = rng.randf_range(0.03, 0.11)
		var segs: int = 8
		var pts := PackedVector2Array()
		for k in segs + 1:
			var t: float = float(k) / float(segs)
			pts.append(Vector2(x0 + sin(t * PI * freq + phase) * amp, t * size.y))
		draw_polyline(pts, col, rng.randf_range(1.5, 4.0))


func _draw_roads() -> void:
	for row in JunqiMap.ROWS:
		for col in JunqiMap.COLS:
			var pos: Vector2i = Vector2i(row, col)
			var a: Vector2 = _cell_px(pos)
			for n: Vector2i in JunqiMap.get_road_neighbors(pos):
				if n.x < pos.x or (n.x == pos.x and n.y < pos.y):
					continue
				draw_line(a, _cell_px(n), COL_INK_SOFT, 2.5)


func _draw_rails() -> void:
	var edges: Array[Vector2i] = JunqiMap.rail_edges()
	var i: int = 0
	while i + 1 < edges.size():
		var a: Vector2 = _cell_px(edges[i])
		var b: Vector2 = _cell_px(edges[i + 1])
		var dir: Vector2 = (b - a).normalized()
		var nrm := Vector2(-dir.y, dir.x)
		var off: float = 0.075 * ppu
		var half_tie: float = 0.13 * ppu
		draw_line(a + nrm * off, b + nrm * off, COL_RAIL, 3.5)
		draw_line(a - nrm * off, b - nrm * off, COL_RAIL, 3.5)
		var ties: int = maxi(2, int(a.distance_to(b) / (0.16 * ppu)))
		for k in ties + 1:
			var p: Vector2 = a.lerp(b, float(k) / float(ties))
			draw_line(p - nrm * half_tie, p + nrm * half_tie, COL_RAIL, 3.0)
		i += 2


## 中线「山 界」横带：两条横贯棋盘的长线 + 居中大字
func _draw_mountain_band() -> void:
	var z: float = (JunqiMap.row_z(5) + JunqiMap.row_z(6)) * 0.5
	var x0: float = JunqiMap.col_x(0) - 0.44
	var x1: float = JunqiMap.col_x(JunqiMap.COLS - 1) + 0.44
	var y: float = _px(Vector2(0.0, z)).y
	var p0: Vector2 = _px(Vector2(x0, z))
	var p1: Vector2 = _px(Vector2(x1, z))
	draw_line(p0, p1, COL_INK, 5.0)
	draw_line(Vector2(p0.x, p0.y + 7.0), Vector2(p1.x, p1.y + 7.0), COL_INK_SOFT, 3.0)
	var center: Vector2 = _px(Vector2((x0 + x1) * 0.5, z))
	draw_rect(Rect2(center - Vector2(0.30, 0.13) * ppu, Vector2(0.60, 0.26) * ppu), COL_WOOD, true)
	_text_center("山 界", center, int(0.17 * ppu), COL_INK)


func _draw_cells() -> void:
	for row in JunqiMap.ROWS:
		for col in JunqiMap.COLS:
			var pos: Vector2i = Vector2i(row, col)
			var c: Vector2 = _cell_px(pos)
			if JunqiMap.is_camp(pos):
				var r: float = CAMP_R * ppu
				draw_circle(c, r, COL_CAMP, true)
				draw_arc(c, r, 0.0, TAU, 48, COL_INK, 4.5, true)
				draw_arc(c, r * 0.86, 0.0, TAU, 48, COL_INK_SOFT, 2.0, true)
				_text_center("行营", c, int(0.18 * ppu), COL_INK)
			elif JunqiMap.is_hq(pos):
				_draw_cell_box(c, _hq_style)
				_text_center("大", c - Vector2(0.0, 0.085 * ppu), int(0.15 * ppu), COL_INK)
				_text_center("本营", c + Vector2(0.0, 0.10 * ppu), int(0.16 * ppu), COL_INK)
			elif JunqiMap.is_frontline_row(pos.x):
				_draw_cell_box(c, _box_style)
				_text_center("山界", c - Vector2(0.0, 0.095 * ppu), int(0.125 * ppu), COL_INK)
				_text_center("前线", c + Vector2(0.0, 0.105 * ppu), int(0.165 * ppu), COL_INK)
			else:
				_draw_cell_box(c, _box_style)
				_text_center("兵站", c, int(0.185 * ppu), COL_INK)


func _draw_cell_box(c: Vector2, style: StyleBoxFlat) -> void:
	var half: Vector2 = BOX * ppu * 0.5
	draw_style_box(style, Rect2(c - half, half * 2.0))


func _draw_border() -> void:
	var r1 := Rect2(Vector2(0.10, 0.10) * ppu, size - Vector2(0.20, 0.20) * ppu)
	draw_rect(r1, COL_INK, false, 7.0)
	var r2 := r1.grow(-0.045 * ppu)
	draw_rect(r2, COL_INK_SOFT, false, 3.0)


func _text_center(text: String, center: Vector2, font_size: int, color: Color) -> void:
	if font == null:
		return
	var asc: float = font.get_ascent(font_size)
	var desc: float = font.get_descent(font_size)
	var baseline: float = center.y - (asc + desc) * 0.5 + asc
	var w: float = size.x
	draw_string(font, Vector2(center.x - w * 0.5, baseline), text,
		HORIZONTAL_ALIGNMENT_CENTER, w, font_size, color)

# JunqiAI.gd
# 军旗翻翻棋 · 电脑对手（大师级）
#
# 设计要点
# --------
# 1. 翻翻棋里“暗棋”既不能被吃、也不能移动，所以**已翻开的棋子构成的子博弈是完全信息博弈**：
#    对局面的走子搜索可以做到精确，不用偷看暗棋身份。本 AI 用 alpha-beta 负极大搜索
#    在“已翻开的棋子”上做 2~4 层前瞻，配合迭代加深与节点/时间上限。
# 2. 暗棋身份只在“翻棋”决策里使用，而且用的是**公开信息**推断出的概率分布
#    （每种棋子总数固定，已经翻出/阵亡的对双方都是可见的）。翻棋的分数是
#    “翻开后局面的期望评估”，因此 AI 会优先翻出对局势最有帮助的暗棋。
# 3. 评估函数包含：子力（工兵随对方剩余地雷数增值）、行营安全、机动性、被吃/被保威胁、
#    明棋贴着暗棋的隐蔽风险、军旗与地雷的攻防进度。
#
# 遵循 Godot 4.7 GDScript 2.0 静态类型规范

class_name JunqiAI
extends RefCounted

const N: int = JunqiMap.ROWS * JunqiMap.COLS

## 搜索上限（迭代加深会在达到上限前返回上一层完整结果）
const MAX_DEPTH: int = 4
const NODE_LIMIT: int = 9000
const TIME_LIMIT_USEC: int = 350000

## 可调搜索预算（对局用默认值；自测时调小以加快批量对局）
var max_depth: int = MAX_DEPTH
var node_limit: int = NODE_LIMIT
var time_limit_usec: int = TIME_LIMIT_USEC
## > 0 时，翻棋只评估随机抽样的这么多枚暗棋（仅用于大批量自测提速）
var flip_scan_limit: int = 0

## 评估权重
const W_CAMP: float = 6.0
const W_MOBILITY: float = 0.5
const W_THREAT: float = 0.45
const W_DEFEND_FACTOR: float = 0.35
const W_HIDDEN_EDGE: float = 0.05
const W_MINE_TIMING: float = 9.0
const W_ENGINEER_MINE: float = 5.0
const INFO_BASE: float = 13.0
const WIN_SCORE: float = 900000.0

var rng: RandomNumberGenerator = RandomNumberGenerator.new()

## 邻接表（按 idx 存，避免每次查询都分配 Dictionary / Array）
var _road_nb: Array = []
var _rail_nb: Array = []
var _camp: PackedByteArray = PackedByteArray()
var _dirs: Array[Vector2i] = [
	Vector2i(0, 1), Vector2i(0, -1), Vector2i(1, 0), Vector2i(-1, 0),
]

## 搜索状态
var _kind: PackedInt32Array = PackedInt32Array()
var _side: PackedInt32Array = PackedInt32Array()
var _rev: PackedInt32Array = PackedInt32Array()

var _nodes: int = 0
var _deadline: int = 0
var _aborted: bool = false

## 公开信息推断：key = side * 100 + kind，value = 曾经翻开过的数量（翻出即永久可见）
var _last_game_id: int = 0
var _seen: Dictionary = {}
var _dist: Dictionary = {}


func _init() -> void:
	rng.randomize()
	_road_nb.resize(N)
	_rail_nb.resize(N)
	_camp.resize(N)
	for row in JunqiMap.ROWS:
		for col in JunqiMap.COLS:
			var pos: Vector2i = Vector2i(row, col)
			var i: int = _idx(pos)
			_camp[i] = 1 if JunqiMap.is_camp(pos) else 0
			var rn := PackedInt32Array()
			for n: Vector2i in JunqiMap.get_road_neighbors(pos):
				rn.append(_idx(n))
			_road_nb[i] = rn
			var ln := PackedInt32Array()
			for n: Vector2i in JunqiMap.get_rail_neighbors(pos):
				ln.append(_idx(n))
			_rail_nb[i] = ln


# ==================== 对外入口 ====================

## 返回 { "action": "move", "from": Vector2i, "to": Vector2i }
##      { "action": "flip", "pos": Vector2i }
##      {} 表示无棋可下
func decide(game: JunqiGame, side: int) -> Dictionary:
	_load(game)
	var hidden: Array[Vector2i] = game.hidden_positions()
	var progress: float = clampf(float(game.revealed_count(-1)) / 50.0, 0.0, 1.0)

	# ---- 走子：alpha-beta 搜索 ----
	var moves: Array = _gen(side)
	var move_int: int = -1
	var move_score: float = -INF
	if not moves.is_empty():
		var r: Array = _root_search(side, moves)
		move_int = int(r[0])
		move_score = float(r[1])

	# ---- 翻棋：按公开分布做期望评估 ----
	var flip_pos: Vector2i = Vector2i(-1, -1)
	var flip_score: float = -INF
	if not hidden.is_empty():
		_build_dist(game)
		var base_eval: float = _eval(side)
		var candidates: Array[Vector2i] = hidden
		if flip_scan_limit > 0 and hidden.size() > flip_scan_limit:
			candidates = hidden.duplicate()
			for i in range(candidates.size() - 1, 0, -1):
				var j: int = rng.randi_range(0, i)
				var t: Vector2i = candidates[i]
				candidates[i] = candidates[j]
				candidates[j] = t
			candidates.resize(flip_scan_limit)
		for pos: Vector2i in candidates:
			var sc: float = _eval_flip(pos, side, base_eval, progress)
			sc += rng.randf() * 2.0
			if sc > flip_score:
				flip_score = sc
				flip_pos = pos

	if flip_pos.x >= 0 and (move_int < 0 or flip_score > move_score):
		return {"action": "flip", "pos": flip_pos}
	if move_int >= 0:
		return {"action": "move", "from": _pos(move_int / N), "to": _pos(move_int % N)}
	return {}


# ==================== 状态装载 / 公开信息 ====================

func _load(game: JunqiGame) -> void:
	_kind.resize(N)
	_side.resize(N)
	_rev.resize(N)
	for i in N:
		_kind[i] = -1
		_side[i] = -1
		_rev[i] = 0
	for pos: Vector2i in game.cells:
		var p: JunqiGame.Piece = game.cells[pos]
		var i: int = _idx(pos)
		_kind[i] = p.kind
		_side[i] = p.side
		_rev[i] = 1 if p.revealed else 0
	_refresh_seen(game)


## 记录“曾经翻开过”的棋子数量：翻出即永久可见，因此 max 历史值 = 已翻出 + 已阵亡
func _refresh_seen(game: JunqiGame) -> void:
	var gid: int = game.get_instance_id()
	if gid != _last_game_id:
		_last_game_id = gid
		_seen.clear()
	var cur: Dictionary = {}
	for pos: Vector2i in game.cells:
		var p: JunqiGame.Piece = game.cells[pos]
		if p.revealed:
			var key: int = p.side * 100 + p.kind
			cur[key] = int(cur.get(key, 0)) + 1
	for key: int in cur:
		if int(cur[key]) > int(_seen.get(key, 0)):
			_seen[key] = int(cur[key])


## 剩余暗棋的分布（按公开信息推断，不含任何“偷看”）
func _build_dist(game: JunqiGame) -> void:
	_dist.clear()
	for side: int in [JunqiData.Side.RED, JunqiData.Side.BLUE]:
		for kind: int in JunqiData.SIDE_CONFIG.keys():
			var seen: int = int(_seen.get(side * 100 + int(kind), 0))
			var rem: int = int(JunqiData.SIDE_CONFIG[kind]) - seen
			if rem > 0:
				_dist[side * 100 + int(kind)] = rem


# ==================== 翻棋期望评估 ====================

## 翻棋期望评估：只做“加入一枚明棋”的增量评估，不平价全盘，快很多。
func _eval_flip(pos: Vector2i, side: int, base_eval: float, progress: float) -> float:
	var total: int = 0
	for key: int in _dist:
		total += int(_dist[key])
	if total <= 0:
		return -INF
	var idx: int = _idx(pos)
	var mines: Array[int] = [_mine_count(0), _mine_count(1)]
	var mob: int = 0
	for j: int in _road_nb[idx]:
		if _kind[j] < 0:
			mob += 1
	var camp_bonus: float = W_CAMP if _camp[idx] == 1 else 0.0
	var delta: float = 0.0
	for key: int in _dist:
		var w: float = float(_dist[key]) / float(total)
		var sd: int = key / 100
		var kd: int = key % 100
		var v: float = float(JunqiData.value_of(kd))
		if kd == JunqiData.PieceType.ENGINEER:
			v += W_ENGINEER_MINE * float(mines[1 - sd])
		elif kd == JunqiData.PieceType.FLAG:
			v = 40.0 if mines[sd] > 0 else 260.0
		elif kd == JunqiData.PieceType.BOMB:
			v += 8.0
		v += camp_bonus + float(mob) * W_MOBILITY
		delta += w * (v if sd == side else -v)
	# 情报价值随牌面逐渐打开而衰减
	return base_eval + delta + INFO_BASE * (1.0 - progress)


# ==================== 走法生成 ====================

func _gen(s: int) -> Array:
	var out: Array = []
	for i in N:
		var ka: int = _kind[i]
		if ka < 0 or _rev[i] == 0 or _side[i] != s:
			continue
		if ka == JunqiData.PieceType.FLAG or ka == JunqiData.PieceType.MINE:
			continue
		for j: int in _road_nb[i]:
			if _can(i, j, s):
				out.append(i * N + j)
		if (_rail_nb[i] as PackedInt32Array).size() > 0:
			if ka == JunqiData.PieceType.ENGINEER:
				_gen_engineer(i, s, out)
			elif not JunqiGame.RAIL_FLY_ENGINEER_ONLY:
				_gen_straight(i, s, out)
	return out


func _gen_straight(i: int, s: int, out: Array) -> void:
	var rnb: PackedInt32Array = _road_nb[i]
	for d: Vector2i in _dirs:
		var cur: int = i
		while true:
			var np: Vector2i = _pos(cur) + d
			if not JunqiMap.is_valid_pos(np):
				break
			var nxt: int = _idx(np)
			if not (_rail_nb[cur] as PackedInt32Array).has(nxt):
				break
			var kd: int = _kind[nxt]
			if kd >= 0:
				if _can(i, nxt, s) and not rnb.has(nxt):
					out.append(i * N + nxt)
				break
			if not rnb.has(nxt):
				out.append(i * N + nxt)
			cur = nxt


func _gen_engineer(i: int, s: int, out: Array) -> void:
	var rnb: PackedInt32Array = _road_nb[i]
	var seen := PackedByteArray()
	seen.resize(N)
	var queue: Array[int] = [i]
	seen[i] = 1
	while not queue.is_empty():
		var cur: int = queue.pop_front()
		for nxt: int in _rail_nb[cur]:
			if seen[nxt] == 1:
				continue
			var kd: int = _kind[nxt]
			if kd >= 0 and _rev[nxt] == 1 and _side[nxt] == s:
				continue
			seen[nxt] = 1
			if _can(i, nxt, s) and not rnb.has(nxt):
				out.append(i * N + nxt)
			if kd < 0:
				queue.append(nxt)


## 攻击合法性（与 JunqiGame.can_move_to 完全一致）
func _can(from: int, to: int, s: int) -> bool:
	var kd: int = _kind[to]
	if kd < 0:
		return true
	if _rev[to] == 0:
		return false
	if _side[to] == s:
		return false
	if _camp[to] == 1:
		return false
	if kd == JunqiData.PieceType.MINE:
		var ka: int = _kind[from]
		return ka == JunqiData.PieceType.ENGINEER or ka == JunqiData.PieceType.BOMB
	if kd == JunqiData.PieceType.FLAG:
		return _mine_count(_side[to]) == 0
	return true


# ==================== 搜索 ====================

func _root_search(s: int, moves: Array) -> Array:
	_nodes = 0
	_aborted = false
	_deadline = Time.get_ticks_usec() + time_limit_usec

	var ordered: Array = _order(moves, s)
	var best_m: int = int(ordered[0])
	var best_sc: float = -INF
	var depth: int = 1
	while depth <= max_depth:
		var alpha: float = -INF
		var local_best: int = -1
		var local_sc: float = -INF
		for m: int in ordered:
			var res: Array = _apply(m)
			var sc: float
			if bool(res[1]):
				sc = WIN_SCORE
			else:
				sc = -_search(1 - s, depth - 1, -INF, -alpha)
			_undo(res[0])
			if sc > local_sc:
				local_sc = sc
				local_best = m
			if sc > alpha:
				alpha = sc
			if _aborted:
				break
		# 即使本层被时间/节点上限打断，也要采用已经算出的最好着法
		# （否则极端情况下会退化成“随便走第一步”）
		if local_best < 0:
			break
		best_m = local_best
		best_sc = local_sc
		if _aborted:
			break
		ordered.erase(best_m)
		ordered.push_front(best_m)
		depth += 1
	return [best_m, best_sc]


func _search(s: int, depth: int, alpha: float, beta: float) -> float:
	_nodes += 1
	if _nodes >= node_limit:
		return _eval(s)
	if (_nodes & 31) == 0 and Time.get_ticks_usec() > _deadline:
		_aborted = true
		return _eval(s)
	if depth <= 0:
		return _eval(s)
	var moves: Array = _gen(s)
	if moves.is_empty():
		return _eval(s)
	moves = _order(moves, s)
	var best: float = -INF
	for m: int in moves:
		var res: Array = _apply(m)
		var sc: float
		if bool(res[1]):
			sc = WIN_SCORE
		else:
			sc = -_search(1 - s, depth - 1, -beta, -alpha)
		_undo(res[0])
		if sc > best:
			best = sc
		if sc > alpha:
			alpha = sc
		if alpha >= beta or _aborted:
			break
	return best


## 走法排序：吃子优先（MVV-LVA），其余保持稳定。
## 不用 sort_custom/lambda：在成千上万次调用的热路径上更稳、更快。
func _order(moves: Array, _s: int) -> Array:
	var n: int = moves.size()
	if n < 2:
		return moves
	var sc := PackedFloat32Array()
	sc.resize(n)
	for i in n:
		var m: int = moves[i]
		var to: int = m % N
		var s: float = 0.0
		var kd: int = _kind[to]
		if kd >= 0:
			s = 1000.0 + float(JunqiData.value_of(kd)) \
				- float(JunqiData.value_of(_kind[m / N])) * 0.1
			if kd == JunqiData.PieceType.FLAG:
				s += 5000.0
		sc[i] = s
	var out: Array = moves.duplicate()
	for i in range(1, n):
		var key_m: int = out[i]
		var key_s: float = sc[i]
		var j: int = i - 1
		while j >= 0 and sc[j] < key_s:
			out[j + 1] = out[j]
			sc[j + 1] = sc[j]
			j -= 1
		out[j + 1] = key_m
		sc[j + 1] = key_s
	return out


# ==================== 走子 / 撤销 ====================

func _apply(m: int) -> Array:
	var from: int = m / N
	var to: int = m % N
	var rec: Array = [
		from, to, _kind[from], _side[from], _rev[from],
		_kind[to], _side[to], _rev[to],
	]
	var ak: int = _kind[from]
	var asd: int = _side[from]
	var dk: int = _kind[to]
	if dk < 0:
		_kind[from] = -1
		_side[from] = -1
		_rev[from] = 0
		_kind[to] = ak
		_side[to] = asd
		_rev[to] = 1
		return [rec, false]
	var combat: int = JunqiGame.resolve_kinds(ak, dk)
	match combat:
		JunqiGame.Combat.ATTACKER_WIN, JunqiGame.Combat.FLAG_DOWN:
			_kind[from] = -1
			_side[from] = -1
			_rev[from] = 0
			_kind[to] = ak
			_side[to] = asd
			_rev[to] = 1
		JunqiGame.Combat.BOTH_DIE:
			_kind[from] = -1
			_side[from] = -1
			_rev[from] = 0
			_kind[to] = -1
			_side[to] = -1
			_rev[to] = 0
		_:
			_kind[from] = -1
			_side[from] = -1
			_rev[from] = 0
	return [rec, combat == JunqiGame.Combat.FLAG_DOWN]


func _undo(rec: Array) -> void:
	_kind[rec[0]] = rec[2]
	_side[rec[0]] = rec[3]
	_rev[rec[0]] = rec[4]
	_kind[rec[1]] = rec[5]
	_side[rec[1]] = rec[6]
	_rev[rec[1]] = rec[7]


# ==================== 评估 ====================

func _eval(s: int) -> float:
	var mines: Array[int] = [_mine_count(0), _mine_count(1)]
	var sc: float = 0.0
	for i in N:
		var k: int = _kind[i]
		if k < 0 or _rev[i] == 0:
			continue
		var owner: int = _side[i]
		var v: float = float(JunqiData.value_of(k))
		if k == JunqiData.PieceType.ENGINEER:
			v += W_ENGINEER_MINE * float(mines[1 - owner])
		elif k == JunqiData.PieceType.FLAG:
			v = 40.0 if mines[owner] > 0 else 260.0
		elif k == JunqiData.PieceType.BOMB:
			v += 8.0
		if _camp[i] == 1:
			v += W_CAMP
		var mob: int = 0
		for j: int in _road_nb[i]:
			if _kind[j] < 0:
				mob += 1
		v += float(mob) * W_MOBILITY
		if owner == s:
			sc += v
		else:
			sc -= v
	sc += _threat_balance(s)
	sc += _hidden_risk(s)
	# 地雷攻防进度：每少一颗被挖，军旗就多一分危险
	sc += W_MINE_TIMING * float(mines[s] - mines[1 - s])
	return sc


func _threat_balance(s: int) -> float:
	var sc: float = 0.0
	for i in N:
		var k: int = _kind[i]
		if k < 0 or _rev[i] == 0:
			continue
		var owner: int = _side[i]
		var gain: float = _best_attacker_gain(i, 1 - owner)
		if gain <= 0.0:
			continue
		if _has_defender(i, owner):
			gain *= W_DEFEND_FACTOR
		if owner == s:
			sc -= gain * W_THREAT
		else:
			sc += gain * W_THREAT
	return sc


## 明棋贴着暗棋的潜在风险（暗棋随时可能被翻出成强敌）
func _hidden_risk(s: int) -> float:
	var sc: float = 0.0
	for i in N:
		var k: int = _kind[i]
		if k < 0 or _rev[i] == 0:
			continue
		var risky: bool = false
		for j: int in _road_nb[i]:
			if _kind[j] >= 0 and _rev[j] == 0:
				risky = true
				break
		if not risky:
			continue
		var pen: float = W_HIDDEN_EDGE * float(JunqiData.value_of(k))
		if _side[i] == s:
			sc -= pen
		else:
			sc += pen
	return sc


## i 是否会被 by 方的明棋吃掉：返回 by 方攻击 i 能拿到的最大净收益（≤ 0 表示不构成威胁）
func _best_attacker_gain(i: int, by: int) -> float:
	if _camp[i] == 1:
		return 0.0
	var victim: int = _kind[i]
	var best: float = 0.0
	for j: int in _road_nb[i]:
		if _kind[j] >= 0 and _rev[j] == 1 and _side[j] == by and _can(j, i, by):
			var g: float = _attack_gain(_kind[j], victim)
			if g > best:
				best = g
	if (_rail_nb[i] as PackedInt32Array).size() > 0:
		for d: Vector2i in _dirs:
			var cur: int = i
			while true:
				var np: Vector2i = _pos(cur) + d
				if not JunqiMap.is_valid_pos(np):
					break
				var nxt: int = _idx(np)
				if not (_rail_nb[cur] as PackedInt32Array).has(nxt):
					break
				if _kind[nxt] >= 0:
					if _rev[nxt] == 1 and _side[nxt] == by and _can(nxt, i, by) \
							and (not JunqiGame.RAIL_FLY_ENGINEER_ONLY \
								or _kind[nxt] == JunqiData.PieceType.ENGINEER):
						var g2: float = _attack_gain(_kind[nxt], victim)
						if g2 > best:
							best = g2
					break
				cur = nxt
	return best


## 进攻方吃防守方能拿到的净收益（子力价值差）
func _attack_gain(attacker_kind: int, defender_kind: int) -> float:
	var combat: int = JunqiGame.resolve_kinds(attacker_kind, defender_kind)
	match combat:
		JunqiGame.Combat.FLAG_DOWN:
			return 900.0
		JunqiGame.Combat.ATTACKER_WIN:
			return float(JunqiData.value_of(defender_kind))
		JunqiGame.Combat.BOTH_DIE:
			return float(JunqiData.value_of(defender_kind)) - float(JunqiData.value_of(attacker_kind))
		_:
			return 0.0


## i 是否被己方棋子保护（简化：相邻有己方明棋）
func _has_defender(i: int, owner: int) -> bool:
	for j: int in _road_nb[i]:
		var k: int = _kind[j]
		if k >= 0 and _rev[j] == 1 and _side[j] == owner \
				and k != JunqiData.PieceType.MINE and k != JunqiData.PieceType.FLAG:
			return true
	return false


func _mine_count(sd: int) -> int:
	var n: int = 0
	for i in N:
		if _kind[i] == JunqiData.PieceType.MINE and _side[i] == sd:
			n += 1
	return n


# ==================== 工具 ====================

func _idx(pos: Vector2i) -> int:
	return pos.x * JunqiMap.COLS + pos.y


func _pos(i: int) -> Vector2i:
	return Vector2i(i / JunqiMap.COLS, i % JunqiMap.COLS)

# JunqiGame.gd
# 军旗翻翻棋 · 规则与状态（翻棋 / 走子 / 战斗结算 / 胜负判定）
# 规则与二维版 jungle_chess 完全一致：
#   * 50 枚棋子（红蓝各 25）随机铺满 50 个兵站，全部背面朝上
#   * 每回合二选一：翻开一枚暗棋，或移动一枚己方已翻开的棋子
#   * 公路走一步（可进空行营）；只有工兵能在铁道上“飞”（任意远行 + 转弯），
#     其它棋子即使在铁道上也只能走一步
#   * 行营中的棋子不可被攻击
#   * 炸弹与任何棋子同归于尽；地雷只有工兵能挖 / 炸弹能炸，其它棋子不能主动触碰；
#     同级同归于尽；对方 3 颗地雷全部挖光后才能擎军旗
# 遵循 Godot 4.7 GDScript 2.0 静态类型规范

class_name JunqiGame
extends RefCounted

## 战斗结果
enum Combat {
	ATTACKER_WIN,   ## 进攻方胜，占据目标格
	DEFENDER_WIN,   ## 进攻方阵亡，防守方留在原地
	BOTH_DIE,       ## 同归于尽
	FLAG_DOWN,      ## 军旗被夺
}


## 棋盘上的一枚棋子（纯数据）
class Piece:
	var side: int = JunqiData.Side.RED
	var kind: int = JunqiData.PieceType.ENGINEER
	var revealed: bool = false
	var pos: Vector2i = Vector2i.ZERO

	func is_flag() -> bool:
		return kind == JunqiData.PieceType.FLAG

	func is_bomb() -> bool:
		return kind == JunqiData.PieceType.BOMB

	func is_mine() -> bool:
		return kind == JunqiData.PieceType.MINE

	func is_engineer() -> bool:
		return kind == JunqiData.PieceType.ENGINEER

	## 已翻开且不是军旗 / 地雷才能行动
	func can_move() -> bool:
		return revealed and JunqiData.can_kind_move(kind)

	func display_name() -> String:
		return JunqiData.piece_name(kind)


## 长时间无吃子则判和（防止双方无尽推拉）
const MAX_QUIET_PLIES: int = 140

## 铁路上的“飞”（沿铁路远距离移动）是否仅限工兵。
## true：只有工兵能沿铁路任意远行（且可转弯）；其它棋子即使在铁道上也只能走一步。
const RAIL_FLY_ENGINEER_ONLY: bool = true

# ==================== 状态 ====================

## Vector2i(row, col) -> Piece
var cells: Dictionary = {}

## 获胜方（-1 表示未分胜负）
var winner: int = -1

## 结束原因
var end_reason: String = ""

## 距离上一次吃子已经过了多少手（不含翻棋）
var quiet_plies: int = 0

## 是否判和
var is_draw: bool = false


# ==================== 初始化 ====================

## 随机布阵：50 枚棋子铺满 50 个兵站
func setup(rng: RandomNumberGenerator = null) -> void:
	cells.clear()
	winner = -1
	end_reason = ""
	quiet_plies = 0
	is_draw = false

	var r: RandomNumberGenerator = rng
	if r == null:
		r = RandomNumberGenerator.new()
		r.randomize()

	var all_pieces: Array = []
	for side: int in [JunqiData.Side.RED, JunqiData.Side.BLUE]:
		for ptype: int in JunqiData.SIDE_CONFIG.keys():
			var count: int = int(JunqiData.SIDE_CONFIG[ptype])
			for i in count:
				all_pieces.append({"side": side, "kind": int(ptype)})

	# Fisher-Yates 洗牌
	for i in range(all_pieces.size() - 1, 0, -1):
		var j: int = r.randi_range(0, i)
		var tmp: Variant = all_pieces[i]
		all_pieces[i] = all_pieces[j]
		all_pieces[j] = tmp

	var positions: Array[Vector2i] = JunqiMap.get_placeable_positions()
	for i in range(positions.size() - 1, 0, -1):
		var j: int = r.randi_range(0, i)
		var tmp: Vector2i = positions[i]
		positions[i] = positions[j]
		positions[j] = tmp

	var total: int = mini(all_pieces.size(), positions.size())
	for i in total:
		var data: Dictionary = all_pieces[i]
		var piece := Piece.new()
		piece.side = int(data["side"])
		piece.kind = int(data["kind"])
		piece.revealed = false
		piece.pos = positions[i]
		cells[piece.pos] = piece


# ==================== 基础查询 ====================

func piece_at(pos: Vector2i) -> Piece:
	return cells.get(pos, null)


func is_empty_pos(pos: Vector2i) -> bool:
	return not cells.has(pos)


## 所有暗棋位置
func hidden_positions() -> Array[Vector2i]:
	var out: Array[Vector2i] = []
	for pos: Vector2i in cells:
		var p: Piece = cells[pos]
		if not p.revealed:
			out.append(pos)
	return out


## 某阵营剩余棋子数
func side_count(side: int) -> int:
	var n: int = 0
	for pos: Vector2i in cells:
		if (cells[pos] as Piece).side == side:
			n += 1
	return n


## 已翻开棋子数（side = -1 表示双方合计）
func revealed_count(side: int = -1) -> int:
	var n: int = 0
	for pos: Vector2i in cells:
		var p: Piece = cells[pos]
		if p.revealed and (side == -1 or p.side == side):
			n += 1
	return n


# ==================== 走子规则 ====================

## 某阵营存活的地雷数（军旗在对方地雷挖完之前不可被擎）
func mine_count(side: int) -> int:
	var n: int = 0
	for pos: Vector2i in cells:
		var p: Piece = cells[pos]
		if p.side == side and p.is_mine():
			n += 1
	return n


## 对方的地雷是否已全部挖光（此时才能去擎军旗）
func mines_cleared(side: int) -> bool:
	return mine_count(1 - side) == 0


## 是否能移动到目标格
func can_move_to(piece: Piece, to_pos: Vector2i) -> bool:
	if piece == null or to_pos == piece.pos:
		return false
	if not JunqiMap.is_valid_pos(to_pos):
		return false
	var target: Piece = cells.get(to_pos, null)
	if target == null:
		return true                 # 空格（含空行营）
	if not target.revealed:
		return false                # 不能吃暗棋
	if target.side == piece.side:
		return false                # 不能吃己方
	if JunqiMap.is_camp(to_pos):
		return false                # 行营中的棋子不可被攻击
	# 地雷：只有工兵能挖，炸弹可以炸，其他棋子不能主动触碰
	if target.is_mine():
		return piece.is_engineer() or piece.is_bomb()
	# 军旗：必须先把对方 3 个地雷全部挖光才能擎旗
	if target.is_flag():
		return mines_cleared(piece.side)
	return true


## 计算某枚棋子的全部合法落点
func valid_moves(piece: Piece) -> Array[Vector2i]:
	var out: Array[Vector2i] = []
	if piece == null or not piece.can_move():
		return out

	# 公路：四周一步
	for n: Vector2i in JunqiMap.get_road_neighbors(piece.pos):
		if can_move_to(piece, n):
			out.append(n)

	# 铁路：“飞”（沿铁路远距离移动）只属于工兵；其它棋子即使在铁道上，
	# 也只能靠上面的公路一步。
	if JunqiMap.is_on_rail(piece.pos):
		if piece.is_engineer():
			out.append_array(_engineer_rail_moves(piece))
		elif not RAIL_FLY_ENGINEER_ONLY:
			out.append_array(_straight_rail_moves(piece))

	# 去重
	var unique: Array[Vector2i] = []
	for m: Vector2i in out:
		if m not in unique:
			unique.append(m)
	return unique


## 工兵：在铁路网上任意转弯（BFS）
func _engineer_rail_moves(piece: Piece) -> Array[Vector2i]:
	var result: Array[Vector2i] = []
	var visited: Dictionary = {}
	var queue: Array[Vector2i] = []
	queue.append(piece.pos)
	visited[piece.pos] = true

	while not queue.is_empty():
		var current: Vector2i = queue.pop_front()
		for neighbor: Vector2i in JunqiMap.get_rail_neighbors(current):
			if visited.has(neighbor):
				continue
			var target: Piece = cells.get(neighbor, null)
			if target != null and target.revealed and target.side == piece.side:
				continue
			visited[neighbor] = true
			if can_move_to(piece, neighbor):
				result.append(neighbor)
			if target == null:
				queue.append(neighbor)
	return result


## 普通棋子：沿铁路直线滑行，遇到棋子停下
func _straight_rail_moves(piece: Piece) -> Array[Vector2i]:
	var result: Array[Vector2i] = []
	var directions: Array[Vector2i] = [
		Vector2i(0, 1), Vector2i(0, -1), Vector2i(1, 0), Vector2i(-1, 0),
	]
	for dir: Vector2i in directions:
		var current: Vector2i = piece.pos
		while true:
			var next: Vector2i = current + dir
			if not JunqiMap.is_valid_pos(next):
				break
			var neighbors: Array[Vector2i] = JunqiMap.get_rail_neighbors(current)
			if not neighbors.has(next):
				break
			var target: Piece = cells.get(next, null)
			if target != null:
				if can_move_to(piece, next):
					result.append(next)
				break
			result.append(next)
			current = next
	return result


## 某阵营全部可走法：位置 -> 落点数组
func all_moves(side: int) -> Dictionary:
	var result: Dictionary = {}
	for pos: Vector2i in cells:
		var p: Piece = cells[pos]
		if p.side != side or not p.can_move():
			continue
		var moves: Array[Vector2i] = valid_moves(p)
		if not moves.is_empty():
			result[pos] = moves
	return result


## 该阵营是否还有棋可下（含翻暗棋）
func has_action(side: int) -> bool:
	if not hidden_positions().is_empty():
		return true
	for pos: Vector2i in cells:
		var p: Piece = cells[pos]
		if p.side == side and p.can_move() and not valid_moves(p).is_empty():
			return true
	return false


# ==================== 战斗结算 ====================

## 纯函数：给定攻守双方棋子类型，返回战斗结果
## 注意：这里只描述“真打起来”的结果；是否能发动攻击（例如非工兵不能主动碰地雷、
## 地雷未挖光不能擎旗）由 can_move_to 负责过滤。
static func resolve_kinds(attacker_kind: int, defender_kind: int) -> Combat:
	# 炸弹与任何棋子同归于尽
	if attacker_kind == JunqiData.PieceType.BOMB or defender_kind == JunqiData.PieceType.BOMB:
		return Combat.BOTH_DIE
	# 军旗被夺
	if defender_kind == JunqiData.PieceType.FLAG:
		return Combat.FLAG_DOWN
	if attacker_kind == JunqiData.PieceType.FLAG:
		return Combat.DEFENDER_WIN
	# 地雷：只有工兵能挖
	if attacker_kind == JunqiData.PieceType.MINE:
		return Combat.DEFENDER_WIN
	if defender_kind == JunqiData.PieceType.MINE:
		if attacker_kind == JunqiData.PieceType.ENGINEER:
			return Combat.ATTACKER_WIN
		return Combat.DEFENDER_WIN
	# 普通军衔比大小
	var ra: int = JunqiData.rank_of(attacker_kind)
	var rd: int = JunqiData.rank_of(defender_kind)
	if ra > rd:
		return Combat.ATTACKER_WIN
	if ra == rd:
		return Combat.BOTH_DIE
	return Combat.DEFENDER_WIN


## 翻开一枚暗棋，返回该棋子（非法则返回 null）
func flip_piece(pos: Vector2i) -> Piece:
	var p: Piece = cells.get(pos, null)
	if p == null or p.revealed:
		return null
	p.revealed = true
	return p


## 执行一步走子。返回：
## { ok:bool, attacker:Piece, removed:Array[Piece], from:Vector2i, to:Vector2i, combat:int }
func move_piece(from_pos: Vector2i, to_pos: Vector2i) -> Dictionary:
	var result: Dictionary = {
		"ok": false,
		"attacker": null,
		"removed": [],
		"from": from_pos,
		"to": to_pos,
		"combat": -1,
	}
	var p: Piece = cells.get(from_pos, null)
	if p == null or not p.can_move():
		return result
	if to_pos not in valid_moves(p):
		return result

	result["ok"] = true
	result["attacker"] = p

	var target: Piece = cells.get(to_pos, null)
	if target == null:
		cells.erase(from_pos)
		cells[to_pos] = p
		p.pos = to_pos
		_bump_quiet(false)
		return result

	var combat: Combat = resolve_kinds(p.kind, target.kind)
	result["combat"] = combat
	var removed: Array = result["removed"]
	_bump_quiet(true)

	match combat:
		Combat.ATTACKER_WIN, Combat.FLAG_DOWN:
			removed.append(target)
			cells.erase(to_pos)
			cells.erase(from_pos)
			cells[to_pos] = p
			p.pos = to_pos
		Combat.BOTH_DIE:
			removed.append(target)
			removed.append(p)
			cells.erase(to_pos)
			cells.erase(from_pos)
		Combat.DEFENDER_WIN:
			removed.append(p)
			cells.erase(from_pos)

	# 军旗被毁 → 直接分胜负
	for q: Piece in removed:
		if q.is_flag():
			winner = 1 - q.side
			end_reason = "军旗被夺"
			break

	return result


## 判负（某方无子可动）
func declare_no_action(loser_side: int) -> void:
	winner = 1 - loser_side
	end_reason = "%s 无子可动" % JunqiData.SIDE_NAMES[loser_side]


## 长时间无吃子 → 判和
func _bump_quiet(captured: bool) -> void:
	if captured:
		quiet_plies = 0
		return
	quiet_plies += 1
	if quiet_plies >= MAX_QUIET_PLIES:
		is_draw = true
		end_reason = "长久无吃子，判和"

# JunqiMap.gd
# 军旗翻翻棋 3D · 棋盘拓扑（5 列 × 13 行，含行营 / 大本营 / 前线 / 山界 / 铁路 / 公路）
# 坐标约定：Vector2i(row, col)
#   * 第 0、12 行为大本营行；
#   * 第 6 行为「前线」（开局不摆子，但可以落子）；
#   * 第 5、6 行之间是「山界」横带（不是格子，不可落子）。
#
# 三维世界坐标：X = 列方向，Z = 行方向，Y = 高度；棋盘顶面在 y = 0，
# 棋盘中心位于世界原点，因此 to_world() 直接给出可用于摆放节点的坐标。
# 遵循 Godot 4.7 GDScript 2.0 静态类型规范

class_name JunqiMap
extends RefCounted

const ROWS: int = 13
const COLS: int = 5

## 大本营行（最外两行，每行第 1、3 列）
const HQ_ROWS: Array[int] = [0, 12]
## 前线行：开局不摆放棋子，但棋子可以走到上面
const FRONTLINE_ROWS: Array[int] = [6]
## 行营（共 10 个，上下对称的“菱形”）：棋子躲入行营后不可被吃。
## 行营除了与上下左右相邻的兵站相通外，还与 4 个斜角相邻的格点相通（公路上只能走一步）。
const CAMPS: Array[Vector2i] = [
	Vector2i(2, 1), Vector2i(2, 3), Vector2i(3, 2), Vector2i(4, 1), Vector2i(4, 3),
	Vector2i(8, 1), Vector2i(8, 3), Vector2i(9, 2), Vector2i(10, 1), Vector2i(10, 3),
]

# ==================== 三维尺寸（单位：世界单位，约等于“一格”的宽度） ====================

## 相邻两列兵站中心的距离
const CELL_X: float = 1.0
## 同一半场内相邻两行兵站中心的距离
const CELL_Z: float = 0.5
## 跨越中线（第 5 ↔ 6 ↔ 7 行）时加宽后的行距，用来容纳「山界」横带
const MID_PITCH: float = 0.72
## 棋盘四边的留白
const BOARD_MARGIN: float = 0.46
## 棋盘厚度（顶面 y = 0，底面 y = -BOARD_THICKNESS）
const BOARD_THICKNESS: float = 0.24
## 棋子尺寸：X = 横（沿列方向），Y = 厚，Z = 纵（沿行方向）
const PIECE_SIZE: Vector3 = Vector3(0.82, 0.20, 0.40)
## 棋子中心离棋盘顶面的高度
const PIECE_Y: float = PIECE_SIZE.y * 0.5

## 棋盘左上角（-X / -Z 角）在棋盘局部坐标系中的位置
const BOARD_MIN_X: float = -CELL_X * 0.5 - BOARD_MARGIN
const BOARD_MAX_X: float = CELL_X * float(COLS - 1) + CELL_X * 0.5 + BOARD_MARGIN
const BOARD_MIN_Z: float = -CELL_Z * 0.5 - BOARD_MARGIN
## 第 12 行的 Z（见 row_z）
const BOARD_MAX_Z: float = 5.0 * CELL_Z + MID_PITCH * 2.0 + 5.0 * CELL_Z + CELL_Z * 0.5 + BOARD_MARGIN

enum NodeType { ROAD, CAMP, HQ }

static var NODE_TYPES: Dictionary = {}
static var RAIL_CONNECTIONS: Dictionary = {}
static var ROAD_CONNECTIONS: Dictionary = {}


static func _static_init() -> void:
	_init_node_types()
	_init_rail_connections()
	_init_road_connections()


# ==================== 拓扑构建 ====================

static func _init_node_types() -> void:
	for row in ROWS:
		for col in COLS:
			NODE_TYPES[Vector2i(row, col)] = NodeType.ROAD

	# 行营（见 CAMPS 常量）
	for pos: Vector2i in CAMPS:
		NODE_TYPES[pos] = NodeType.CAMP

	# 大本营（共 4 个，军旗的常规摆放位置）
	for row: int in HQ_ROWS:
		NODE_TYPES[Vector2i(row, 1)] = NodeType.HQ
		NODE_TYPES[Vector2i(row, 3)] = NodeType.HQ


static func _init_rail_connections() -> void:
	# 横向铁路：第 1、5、7、11 行（上下对称）
	var horizontal_rows: Array[int] = [1, 5, 7, 11]
	for row: int in horizontal_rows:
		for col in range(COLS - 1):
			_add_rail(Vector2i(row, col), Vector2i(row, col + 1))

	# 纵向铁路：第 0、2、4 列
	var vertical_cols: Array[int] = [0, 2, 4]
	for col: int in vertical_cols:
		for row in range(ROWS - 1):
			_add_rail(Vector2i(row, col), Vector2i(row + 1, col))

	# 注意：行营四周的斜线是「公路」而不是「铁路」（实物棋盘上画得较细），
	# 因此它们被登记到 ROAD_CONNECTIONS（任何棋子都可走一步），而不是铁路网。


static func _add_rail(a: Vector2i, b: Vector2i) -> void:
	if not RAIL_CONNECTIONS.has(a):
		RAIL_CONNECTIONS[a] = [] as Array[Vector2i]
	if not RAIL_CONNECTIONS.has(b):
		RAIL_CONNECTIONS[b] = [] as Array[Vector2i]
	var list_a: Array = RAIL_CONNECTIONS[a]
	var list_b: Array = RAIL_CONNECTIONS[b]
	if b not in list_a:
		list_a.append(b)
	if a not in list_b:
		list_b.append(a)


static func _init_road_connections() -> void:
	# 上下左右相邻的格点都由公路相连
	for row in ROWS:
		for col in COLS:
			var pos: Vector2i = Vector2i(row, col)
			var neighbors: Array[Vector2i] = [
				Vector2i(row - 1, col), Vector2i(row + 1, col),
				Vector2i(row, col - 1), Vector2i(row, col + 1),
			]
			for n: Vector2i in neighbors:
				if _is_valid_pos(n):
					_add_road(pos, n)

	# 行营与 4 个斜角格点之间的公路（菱形行营的边）。
	# 这一步非常关键：没有它，被围住的棋子（例如缩在行营里的棋子）会出现
	# “明明旁边的斜线是空的却一步也走不了”的情况。
	for camp: Vector2i in CAMPS:
		for dr: int in [-1, 1]:
			for dc: int in [-1, 1]:
				var n: Vector2i = camp + Vector2i(dr, dc)
				if _is_valid_pos(n):
					_add_road(camp, n)


static func _add_road(a: Vector2i, b: Vector2i) -> void:
	if not ROAD_CONNECTIONS.has(a):
		ROAD_CONNECTIONS[a] = [] as Array[Vector2i]
	if not ROAD_CONNECTIONS.has(b):
		ROAD_CONNECTIONS[b] = [] as Array[Vector2i]
	var list_a: Array = ROAD_CONNECTIONS[a]
	var list_b: Array = ROAD_CONNECTIONS[b]
	if b not in list_a:
		list_a.append(b)
	if a not in list_b:
		list_b.append(a)


static func _is_valid_pos(pos: Vector2i) -> bool:
	return pos.x >= 0 and pos.x < ROWS and pos.y >= 0 and pos.y < COLS


# ==================== 查询接口 ====================

static func is_valid_pos(pos: Vector2i) -> bool:
	return _is_valid_pos(pos)


static func all_positions() -> Array[Vector2i]:
	var result: Array[Vector2i] = []
	for row in ROWS:
		for col in COLS:
			result.append(Vector2i(row, col))
	return result


static func get_node_type(pos: Vector2i) -> NodeType:
	return NODE_TYPES.get(pos, NodeType.ROAD)


static func is_camp(pos: Vector2i) -> bool:
	return get_node_type(pos) == NodeType.CAMP


static func is_hq(pos: Vector2i) -> bool:
	return get_node_type(pos) == NodeType.HQ


## 是否在前线行（可落子，但开局不摆子）
static func is_frontline_row(row: int) -> bool:
	return row in FRONTLINE_ROWS


static func is_on_rail(pos: Vector2i) -> bool:
	var list: Array = RAIL_CONNECTIONS.get(pos, [])
	return not list.is_empty()


static func get_rail_neighbors(pos: Vector2i) -> Array[Vector2i]:
	var result: Array[Vector2i] = []
	var list: Array = RAIL_CONNECTIONS.get(pos, [])
	for v: Variant in list:
		if v is Vector2i:
			result.append(v)
	return result


static func get_road_neighbors(pos: Vector2i) -> Array[Vector2i]:
	var result: Array[Vector2i] = []
	var list: Array = ROAD_CONNECTIONS.get(pos, [])
	for v: Variant in list:
		if v is Vector2i:
			result.append(v)
	return result


## 所有可放置棋子的位置（兵站 + 大本营，排除行营与前线）→ 共 50 个
static func get_placeable_positions() -> Array[Vector2i]:
	var result: Array[Vector2i] = []
	for row in ROWS:
		if is_frontline_row(row):
			continue
		for col in COLS:
			var pos: Vector2i = Vector2i(row, col)
			if not is_camp(pos):
				result.append(pos)
	return result


# ==================== 三维坐标换算 ====================

## 列 → X
static func col_x(col: int) -> float:
	return float(col) * CELL_X


## 行 → Z（第 5 ↔ 6 ↔ 7 行两侧都按 MID_PITCH 加宽，用来容纳「山界」横带）
static func row_z(row: int) -> float:
	if row <= 5:
		return float(row) * CELL_Z
	if row == 6:
		return 5.0 * CELL_Z + MID_PITCH
	return 5.0 * CELL_Z + MID_PITCH * 2.0 + float(row - 7) * CELL_Z


## 棋盘尺寸（宽 × 深）
static func board_size() -> Vector2:
	return Vector2(BOARD_MAX_X - BOARD_MIN_X, BOARD_MAX_Z - BOARD_MIN_Z)


## 棋盘中心（世界原点即棋盘中心，所以此值为零向量）
static func board_center() -> Vector3:
	return Vector3((BOARD_MIN_X + BOARD_MAX_X) * 0.5, 0.0, (BOARD_MIN_Z + BOARD_MAX_Z) * 0.5)


## 棋盘贴图坐标原点：棋盘左上角在 col_x / row_z（未居中）坐标系中的位置。
## BoardArt 里的所有绘制都直接用 col_x / row_z，所以这里不能减掉棋盘中心。
static func art_origin() -> Vector2:
	return Vector2(BOARD_MIN_X, BOARD_MIN_Z)


## 棋盘坐标 → 世界坐标（棋盘顶面 y = 0，棋盘中心为原点）
static func to_world(pos: Vector2i) -> Vector3:
	var c: Vector3 = board_center()
	return Vector3(col_x(pos.y) - c.x, 0.0, row_z(pos.x) - c.z)


## 棋盘坐标 → 棋子中心的世界坐标
static func piece_world(pos: Vector2i) -> Vector3:
	return to_world(pos) + Vector3.UP * PIECE_Y


## 棋子（含暗棋）的包围盒，用于鼠标射线拾取
static func piece_aabb(pos: Vector2i) -> AABB:
	var size: Vector3 = PIECE_SIZE + Vector3(0.08, 0.0, 0.08)
	return AABB(piece_world(pos) - size * 0.5, size)


## 世界坐标（XZ）→ 最近的棋盘坐标；离所有格点都太远时返回 (-1, -1)
static func world_to_pos(world: Vector3, max_dist: float = 0.62) -> Vector2i:
	var best: Vector2i = Vector2i(-1, -1)
	var best_d: float = 1e9
	var c: Vector3 = board_center()
	for row in ROWS:
		for col in COLS:
			var dx: float = world.x - (col_x(col) - c.x)
			var dz: float = world.z - (row_z(row) - c.z)
			var d: float = sqrt(dx * dx + dz * dz)
			if d < best_d:
				best_d = d
				best = Vector2i(row, col)
	if best_d > max_dist:
		return Vector2i(-1, -1)
	return best


## 所有铁路边（两两成对：a0, b0, a1, b1 ...）
static func rail_edges() -> Array[Vector2i]:
	var edges: Array[Vector2i] = []
	var seen: Dictionary = {}
	for a: Vector2i in RAIL_CONNECTIONS.keys():
		for b: Vector2i in get_rail_neighbors(a):
			var key: Vector4i = Vector4i(mini(a.x, b.x), mini(a.y, b.y), maxi(a.x, b.x), maxi(a.y, b.y))
			if seen.has(key):
				continue
			seen[key] = true
			edges.append(a)
			edges.append(b)
	return edges

# main.gd
# 军旗翻翻棋 3D · 主控制器
# 负责：三维场景搭建（灯光 / 相机 / 棋盘 / 棋子）、鼠标拾取与视角操作、回合流程、UI
# 规则部分（JunqiGame / JunqiAI / JunqiMap）与二维版完全一致，只把渲染层从 2D 换成 3D。
# 遵循 Godot 4.7 GDScript 2.0 静态类型规范

extends Node3D

const COL_GOLD := Color(0.93, 0.79, 0.42)
const COL_TEXT_DIM := Color(0.72, 0.76, 0.84)

## 视角参数
const CAM_PITCH_DEFAULT: float = 0.78
const CAM_PITCH_MIN: float = 0.38
const CAM_PITCH_MAX: float = 1.45
const CAM_ZOOM_MIN: float = 0.55
const CAM_ZOOM_MAX: float = 1.90

# ==================== 场景对象 ====================
var board_view: Board3D = null
var pieces_root: Node3D = null
var camera: Camera3D = null
var cjk_font: Font = null
var piece_font: Font = null

# ==================== 视角状态 ====================
var cam_yaw: float = 0.0
var cam_pitch: float = CAM_PITCH_DEFAULT
var cam_zoom: float = 1.0
var cam_fit_dist: float = 14.0
## 取景目标点沿相机“上方向”的偏移：用来把透视下偏下的棋盘挪到画面中央
var cam_target_offset: float = 0.0
var _orbiting: bool = false
## 前几帧反复重算“棋盘装满画面”的距离，避开窗口尺寸尚未稳定的阶段
var _fit_frames: int = 0

# ==================== 游戏状态 ====================
var game: JunqiGame = null
var ai: JunqiAI = JunqiAI.new()
## JunqiGame.Piece -> Piece3D
var views: Dictionary = {}
var player_side: int = -1
var ai_side: int = -1
var player_turn: bool = true
var selected_pos: Vector2i = Vector2i(-1, -1)
var hover_pos: Vector2i = Vector2i(-1, -1)
var busy: bool = false
var game_over: bool = false
var ai_running: bool = false
var restart_queued: bool = false
var session: int = 0

# ==================== UI ====================
var turn_label: Label = null
var info_label: Label = null
var status_label: Label = null
var hint_label: Label = null
var over_panel: Control = null
var over_title: Label = null
var over_sub: Label = null


# ==================================================================== 生命周期
func _ready() -> void:
	randomize()
	DisplayServer.window_set_title("军旗翻翻棋 3D")
	cjk_font = _make_cjk_font()
	piece_font = _make_cjk_font(600)
	ThemeDB.fallback_font = cjk_font
	_build_world()
	_build_ui()
	_new_game()
	_fit_camera()
	_update_camera()
	get_viewport().size_changed.connect(_on_viewport_resized)


func _process(_delta: float) -> void:
	if _fit_frames < 10:
		_fit_frames += 1
		_fit_camera()
		_update_camera()
	_update_hover()


func _unhandled_input(event: InputEvent) -> void:
	if event is InputEventMouseButton:
		var mb := event as InputEventMouseButton
		match mb.button_index:
			MOUSE_BUTTON_LEFT:
				if mb.pressed:
					_on_click_screen(mb.position)
			MOUSE_BUTTON_RIGHT, MOUSE_BUTTON_MIDDLE:
				_orbiting = mb.pressed
			MOUSE_BUTTON_WHEEL_UP:
				if mb.pressed:
					_zoom_by(-0.09)
			MOUSE_BUTTON_WHEEL_DOWN:
				if mb.pressed:
					_zoom_by(0.09)
	elif event is InputEventMouseMotion:
		if _orbiting:
			var mm := event as InputEventMouseMotion
			cam_yaw -= mm.relative.x * 0.006
			cam_pitch = clampf(cam_pitch - mm.relative.y * 0.005, CAM_PITCH_MIN, CAM_PITCH_MAX)
			_fit_camera()
			_update_camera()


# ==================================================================== 场景搭建
func _make_cjk_font(weight: int = 400) -> Font:
	var f := SystemFont.new()
	f.font_names = PackedStringArray([
		"Microsoft YaHei UI", "Microsoft YaHei", "微软雅黑", "SimHei", "黑体",
		"Noto Sans CJK SC", "Source Han Sans SC", "PingFang SC",
		"WenQuanYi Micro Hei", "sans-serif",
	])
	f.font_weight = weight
	f.allow_system_fallback = true
	return f


func _build_world() -> void:
	# ---------- 环境光照 ----------
	var we := WorldEnvironment.new()
	var env := Environment.new()
	env.background_mode = Environment.BG_COLOR
	env.background_color = Color(0.055, 0.062, 0.082)
	env.ambient_light_source = Environment.AMBIENT_SOURCE_COLOR
	env.ambient_light_color = Color(0.62, 0.66, 0.76)
	env.ambient_light_energy = 0.55
	we.environment = env
	add_child(we)

	var key := DirectionalLight3D.new()
	key.rotation_degrees = Vector3(-54.0, -32.0, 0.0)
	key.light_energy = 1.25
	key.shadow_enabled = true
	key.directional_shadow_max_distance = 26.0
	add_child(key)

	# ---------- 桌布 ----------
	var table := MeshInstance3D.new()
	var plane := PlaneMesh.new()
	plane.size = Vector2(46.0, 46.0)
	var table_mat := StandardMaterial3D.new()
	table_mat.albedo_color = Color(0.086, 0.094, 0.114)
	table_mat.roughness = 0.95
	plane.material = table_mat
	table.mesh = plane
	table.position = Vector3(0.0, -JunqiMap.BOARD_THICKNESS - 0.004, 0.0)
	add_child(table)

	# ---------- 相机 ----------
	camera = Camera3D.new()
	camera.fov = 42.0
	camera.near = 0.15
	camera.far = 120.0
	camera.current = true
	add_child(camera)

	# ---------- 棋盘 ----------
	board_view = Board3D.new()
	add_child(board_view)
	board_view.build(cjk_font)

	# ---------- 棋子容器 ----------
	pieces_root = Node3D.new()
	add_child(pieces_root)


# ==================================================================== 相机
## 相机自身的上方向（与放置相机时用的 look_at 保持一致）
func _camera_up_vector() -> Vector3:
	var right := Vector3(cos(cam_yaw), 0.0, -sin(cam_yaw))
	var forward := Vector3(-sin(cam_yaw) * cos(cam_pitch), -sin(cam_pitch),
		-cos(cam_yaw) * cos(cam_pitch))
	return right.cross(forward).normalized()


func _place_camera(dist: float, offset_scale: float = 1.0) -> void:
	if camera == null:
		return
	var horizontal: float = cos(cam_pitch) * dist
	camera.position = Vector3(sin(cam_yaw) * horizontal, sin(cam_pitch) * dist, cos(cam_yaw) * horizontal)
	var target: Vector3 = _camera_up_vector() * (cam_target_offset * offset_scale)
	camera.look_at(target, Vector3.UP)


func _update_camera() -> void:
	_place_camera(cam_fit_dist * cam_zoom, cam_zoom)


func _zoom_by(step: float) -> void:
	cam_zoom = clampf(cam_zoom + step, CAM_ZOOM_MIN, CAM_ZOOM_MAX)
	_update_camera()


## 复位视角：把俯仰角与缩放恢复到默认值
func _reset_view() -> void:
	cam_yaw = 0.0
	cam_pitch = CAM_PITCH_DEFAULT
	cam_zoom = 1.0
	_fit_frames = 0
	_fit_camera()
	_update_camera()


func _on_viewport_resized() -> void:
	_fit_frames = 0
	_fit_camera()
	_update_camera()


## 二分求出“恰好把整张棋盘放进画面”的距离，并把棋盘在画面里垂直居中；
## 这样棋盘在任意窗口尺寸下都尽量大（用户在描述里也希望棋盘大一些）
func _fit_camera() -> void:
	var vp: Viewport = get_viewport()
	if vp == null or camera == null:
		return
	var view: Vector2 = vp.get_visible_rect().size
	if view.x < 16.0 or view.y < 16.0:
		return
	var pad_x: float = maxf(10.0, view.x * 0.02)
	var pad_top: float = 52.0
	var pad_bottom: float = 96.0

	cam_target_offset = 0.0
	_fit_distance(view, pad_x, pad_top, pad_bottom)

	# 透视会让靠近相机的一半更“长”，棋盘在画面里会偏下，这里逐步把投影包围盒搬到中央
	var want_center: float = (pad_top + view.y - pad_bottom) * 0.5
	var tan_half: float = tan(deg_to_rad(camera.fov * 0.5))
	for i in 6:
		var box: Rect2 = _projected_bounds(cam_fit_dist)
		var have_center: float = (box.position.y + box.end.y) * 0.5
		var d_px: float = have_center - want_center
		if absf(d_px) < 1.0:
			break
		cam_target_offset -= d_px * tan_half * cam_fit_dist / (view.y * 0.5)
		_fit_distance(view, pad_x, pad_top, pad_bottom)


func _fit_distance(view: Vector2, pad_x: float, pad_top: float, pad_bottom: float) -> void:
	var lo: float = 3.0
	var hi: float = 90.0
	for i in 26:
		var mid: float = (lo + hi) * 0.5
		if _board_fits(mid, view, pad_x, pad_top, pad_bottom):
			hi = mid
		else:
			lo = mid
	cam_fit_dist = clampf(hi, 4.0, 90.0)


## 棋盘八个角在屏幕上的投影包围盒
func _projected_bounds(dist: float) -> Rect2:
	_place_camera(dist)
	var bsize: Vector2 = JunqiMap.board_size()
	var hx: float = bsize.x * 0.5
	var hz: float = bsize.y * 0.5
	var box := Rect2()
	var first: bool = true
	for y: float in [-JunqiMap.BOARD_THICKNESS - 0.01, JunqiMap.PIECE_SIZE.y + 0.05]:
		for sx: float in [-1.0, 1.0]:
			for sz: float in [-1.0, 1.0]:
				var p: Vector2 = camera.unproject_position(Vector3(hx * sx, y, hz * sz))
				if first:
					box = Rect2(p, Vector2.ZERO)
					first = false
				else:
					box = box.expand(p)
	return box


func _board_fits(dist: float, view: Vector2, pad_x: float, pad_top: float, pad_bottom: float) -> bool:
	_place_camera(dist)
	var bsize: Vector2 = JunqiMap.board_size()
	var hx: float = bsize.x * 0.5
	var hz: float = bsize.y * 0.5
	for y: float in [-JunqiMap.BOARD_THICKNESS - 0.01, JunqiMap.PIECE_SIZE.y + 0.05]:
		for sx: float in [-1.0, 1.0]:
			for sz: float in [-1.0, 1.0]:
				var p: Vector2 = camera.unproject_position(Vector3(hx * sx, y, hz * sz))
				if p.x < pad_x or p.x > view.x - pad_x:
					return false
				if p.y < pad_top or p.y > view.y - pad_bottom:
					return false
	return true


