# ==================================================================== 新对局
func _new_game() -> void:
	session += 1
	for child in pieces_root.get_children():
		child.queue_free()
	views.clear()

	game = JunqiGame.new()
	game.setup()

	player_side = -1
	ai_side = -1
	player_turn = true
	selected_pos = Vector2i(-1, -1)
	hover_pos = Vector2i(-1, -1)
	busy = false
	game_over = false
	ai_running = false
	restart_queued = false

	board_view.hide_selection()
	board_view.clear_targets()
	board_view.hide_hover()
	over_panel.visible = false

	for pos: Vector2i in game.cells:
		var p: JunqiGame.Piece = game.cells[pos]
		var v := Piece3D.new()
		pieces_root.add_child(v)
		v.build(p, piece_font)
		v.position = JunqiMap.piece_world(pos)
		v.base_pos = v.position
		views[p] = v

	_update_ui()


func _on_restart_pressed() -> void:
	if busy or ai_running:
		restart_queued = true
		status_label.text = "本回合结束后重新开始…"
		return
	_new_game()


# ==================================================================== 拾取与交互
## 鼠标位置 → 棋盘格点：先做棋子包围盒求交，再退回棋盘平面上的最近格点
func _pick_cell(screen_pos: Vector2) -> Vector2i:
	if game == null or camera == null:
		return Vector2i(-1, -1)
	var origin: Vector3 = camera.project_ray_origin(screen_pos)
	var dir: Vector3 = camera.project_ray_normal(screen_pos)

	var best: Vector2i = Vector2i(-1, -1)
	var best_t: float = INF
	for pos: Vector2i in game.cells:
		var hit: Variant = JunqiMap.piece_aabb(pos).intersects_ray(origin, dir)
		if hit == null:
			continue
		var t: float = origin.distance_to(hit as Vector3)
		if t < best_t:
			best_t = t
			best = pos
	if best.x >= 0:
		return best

	var plane_hit: Variant = Plane(Vector3.UP, 0.0).intersects_ray(origin, dir)
	if plane_hit == null:
		return Vector2i(-1, -1)
	return JunqiMap.world_to_pos(plane_hit as Vector3)


func _update_hover() -> void:
	if board_view == null or game == null:
		return
	if game_over or busy or ai_running or not player_turn:
		if hover_pos.x >= 0:
			hover_pos = Vector2i(-1, -1)
			board_view.hide_hover()
		return
	var pos: Vector2i = _pick_cell(get_viewport().get_mouse_position())
	if pos == hover_pos:
		return
	hover_pos = pos
	if pos.x < 0:
		board_view.hide_hover()
		return
	var p: JunqiGame.Piece = game.piece_at(pos)
	var interesting: bool = false
	if p == null:
		interesting = selected_pos != Vector2i(-1, -1)
	elif not p.revealed:
		interesting = true
	elif p.side == player_side:
		interesting = true
	if interesting:
		board_view.show_hover(pos)
	else:
		board_view.hide_hover()


func _on_click_screen(screen_pos: Vector2) -> void:
	if busy or game_over or ai_running or not player_turn:
		return
	var pos: Vector2i = _pick_cell(screen_pos)
	if pos.x < 0:
		return
	await click_cell(pos)


## 处理“点在某一个格点上”（测试脚本也直接调用这个接口）
func click_cell(pos: Vector2i) -> void:
	if game == null or game_over or busy or ai_running or not player_turn:
		return
	var p: JunqiGame.Piece = game.piece_at(pos)

	# 1) 点暗棋 → 翻开
	if p != null and not p.revealed:
		busy = true
		await _do_flip(pos)
		_after_human()
		return

	# 2) 点己方明棋 → 选中
	if p != null and p.revealed and p.side == player_side:
		if not p.can_move():
			status_label.text = "%s 不能移动" % p.display_name()
			return
		if selected_pos == pos:
			_clear_selection()
		else:
			_select(pos, p)
		return

	# 3) 点空格 / 敌子 → 尝试走子
	if selected_pos != Vector2i(-1, -1):
		var from_pos: Vector2i = selected_pos
		var mover: JunqiGame.Piece = game.piece_at(from_pos)
		if mover != null and pos in game.valid_moves(mover):
			busy = true
			await _do_move(from_pos, pos)
			_after_human()
			return
	_clear_selection()


func _select(pos: Vector2i, p: JunqiGame.Piece) -> void:
	_clear_selection()
	selected_pos = pos
	board_view.show_selection(pos)
	board_view.show_targets(game.valid_moves(p), _occupied_map())
	var v: Piece3D = views.get(p, null)
	if v != null:
		v.set_selected(true)
	_update_ui()


func _clear_selection() -> void:
	if selected_pos != Vector2i(-1, -1):
		var p: JunqiGame.Piece = game.piece_at(selected_pos)
		if p != null:
			var v: Piece3D = views.get(p, null)
			if v != null:
				v.set_selected(false)
	selected_pos = Vector2i(-1, -1)
	if board_view != null:
		board_view.hide_selection()
		board_view.clear_targets()


func _occupied_map() -> Dictionary:
	var d: Dictionary = {}
	if game == null:
		return d
	for pos: Vector2i in game.cells:
		d[pos] = true
	return d


# ==================================================================== 行动
## 翻开一枚暗棋（含动画与回合切换）
func _do_flip(pos: Vector2i) -> void:
	var p: JunqiGame.Piece = game.flip_piece(pos)
	if p == null:
		return
	_clear_selection()

	# 第一枚翻开的棋子决定玩家阵营
	if player_side == -1:
		player_side = p.side
		ai_side = 1 - player_side

	var v: Piece3D = views.get(p, null)
	if v != null:
		await v.reveal(true)

	_update_ui()
	if game.is_draw:
		_end_draw()
		return
	_toggle_turn()


## 走一步棋（含动画、战斗结算、回合切换）
func _do_move(from_pos: Vector2i, to_pos: Vector2i) -> void:
	var p: JunqiGame.Piece = game.piece_at(from_pos)
	if p == null:
		return
	if to_pos not in game.valid_moves(p):
		return
	_clear_selection()

	var target: JunqiGame.Piece = game.piece_at(to_pos)
	var v: Piece3D = views.get(p, null)
	var dest: Vector3 = JunqiMap.piece_world(to_pos)

	# 先让被吃的棋子消失，避免两个棋子在同格重叠
	var pre_destroyed: Array = []
	if target != null:
		var combat: int = JunqiGame.resolve_kinds(p.kind, target.kind)
		if combat != JunqiGame.Combat.DEFENDER_WIN:
			var qv: Piece3D = views.get(target, null)
			if qv != null:
				pre_destroyed.append(target)
				await qv.animate_destroy()
				views.erase(target)

	# 移动动画
	if v != null:
		await v.animate_move(dest)

	# 结算
	var result: Dictionary = game.move_piece(from_pos, to_pos)
	if not result["ok"]:
		_update_ui()
		return

	var removed: Array = result["removed"]
	for q: JunqiGame.Piece in removed:
		if q == p or pre_destroyed.has(q):
			continue
		var qv: Piece3D = views.get(q, null)
		if qv != null:
			await qv.animate_destroy()
			views.erase(q)

	if removed.has(p):
		if v != null:
			await v.animate_destroy()
			views.erase(p)

	_update_ui()
	if game.is_draw:
		_end_draw()
		return
	if game.winner != -1:
		_end_game(game.winner, game.end_reason)
		return
	_toggle_turn()


## 回合切换 + 无棋可走判负
func _toggle_turn() -> void:
	if game_over:
		return
	player_turn = not player_turn
	var acting: int = player_side if player_turn else ai_side
	if acting != -1 and not game.has_action(acting):
		game.declare_no_action(acting)
		_end_game(game.winner, game.end_reason)
		return
	_update_ui()


## 玩家行动之后的收尾：交给电脑或交还控制权
func _after_human() -> void:
	if restart_queued:
		_new_game()
		return
	if game_over:
		busy = false
		return
	if not player_turn and not ai_running:
		_run_ai()
	else:
		busy = false
	_update_ui()


# ==================================================================== 电脑
func _run_ai() -> void:
	if ai_running or game_over:
		return
	ai_running = true
	busy = true
	_update_ui()

	var s: int = session
	await get_tree().create_timer(0.45).timeout

	while not game_over and session == s and not player_turn:
		var action: Dictionary = ai.decide(game, ai_side)
		if action.is_empty():
			game.declare_no_action(ai_side)
			_end_game(game.winner, game.end_reason)
			break

		if String(action.get("action", "")) == "flip":
			await _do_flip(action["pos"])
		else:
			await _do_move(action["from"], action["to"])

		if session != s:
			return
		if game_over or player_turn:
			break
		await get_tree().create_timer(0.28).timeout

	if session != s:
		return
	busy = false
	ai_running = false
	_update_ui()

	if restart_queued:
		_new_game()


# ==================================================================== 结算
func _end_game(winner: int, reason: String) -> void:
	if game_over:
		return
	game_over = true
	busy = false
	board_view.hide_selection()
	board_view.clear_targets()
	board_view.hide_hover()
	_update_ui()

	var i_win: bool = winner == player_side
	var side_name: String = JunqiData.SIDE_NAMES.get(winner, "?")
	over_title.text = "%s获胜！" % ("你" if i_win else "电脑")
	over_title.add_theme_color_override("font_color",
		JunqiData.SIDE_COLORS.get(winner, Color.WHITE))
	if reason != "":
		over_sub.text = "%s · %s" % [side_name, reason]
	else:
		over_sub.text = side_name
	over_panel.visible = true


## 和棋
func _end_draw() -> void:
	if game_over:
		return
	game_over = true
	busy = false
	board_view.hide_selection()
	board_view.clear_targets()
	board_view.hide_hover()
	_update_ui()
	over_title.text = "和棋"
	over_title.add_theme_color_override("font_color", COL_GOLD)
	over_sub.text = game.end_reason if game.end_reason != "" else "双方相持不下"
	over_panel.visible = true


# ==================================================================== UI 刷新
func _update_ui() -> void:
	if turn_label == null or game == null:
		return

	var red_n: int = game.side_count(JunqiData.Side.RED)
	var blue_n: int = game.side_count(JunqiData.Side.BLUE)
	var hidden_n: int = game.hidden_positions().size()
	info_label.text = "红 %d · 蓝 %d · 暗 %d" % [red_n, blue_n, hidden_n]

	if player_side == -1:
		turn_label.text = "阵营待定"
		turn_label.add_theme_color_override("font_color", Color(0.95, 0.85, 0.45))
	else:
		turn_label.text = "你执%s" % JunqiData.SIDE_NAMES[player_side]
		turn_label.add_theme_color_override("font_color", JunqiData.SIDE_COLORS[player_side])

	if game_over:
		status_label.text = "对局结束"
		hint_label.text = "点击「重新开始」或下方「再来一局」再战一局"
	elif player_side == -1:
		status_label.text = "翻开任意一枚暗棋 —— 第一枚翻开的棋子决定你的阵营"
		hint_label.text = "左键点暗棋翻面；右键拖动旋转视角，滚轮缩放"
	elif busy or ai_running:
		status_label.text = "电脑思考中…"
		hint_label.text = ""
	elif player_turn:
		status_label.text = "你的回合（%s）" % JunqiData.SIDE_NAMES[player_side]
		hint_label.text = "点暗棋翻面，或点己方棋子选中后走到绿色圆环处吃子"
	else:
		status_label.text = "电脑回合"
		hint_label.text = ""

# tests/ai_test.gd
# 电脑对手（大师级）测试：
#   1. 走法生成必须与规则引擎 JunqiGame.all_moves 完全一致（防止 AI 提出非法着法）
#   2. 大师 AI 自我对弈：每一步都必须合法，对局必须能结束
#   3. 强度对比：大师 AI 对阵旧版“贪心 AI”，用子力差与胜负率共同衡量
#   4. 默认（大师级）预算下单步思考不应卡住界面
# 运行： godot --headless --script res://tests/ai_test.gd

extends SceneTree

const EQUIV_TRIALS: int = 300
const SELF_GAMES: int = 3
const STRENGTH_GAMES: int = 24
const MAX_PLIES: int = 1500

## 自测用的“快速预算”（对局默认预算更大）
const TEST_DEPTH: int = 3
const TEST_NODES: int = 1500
const TEST_TIME_USEC: int = 40000
const TEST_FLIP_SCAN: int = 12

var failures: int = 0
var rng: RandomNumberGenerator = RandomNumberGenerator.new()


func _init() -> void:
	rng.seed = 424242
	print("=== 军旗翻翻棋 大师 AI 测试 ===")

	_test_move_gen_equivalence()
	_test_self_play_legality()
	_test_strength_vs_greedy()
	_test_default_budget_speed()

	print("")
	if failures == 0:
		print("全部通过 ✔")
	else:
		print("发现 %d 处问题 ✘" % failures)
	quit(1 if failures > 0 else 0)


func _fail(msg: String) -> void:
	failures += 1
	print("  [FAIL] ", msg)


func _make_ai(depth: int, nodes: int, usec: int) -> JunqiAI:
	var ai := JunqiAI.new()
	ai.max_depth = depth
	ai.node_limit = nodes
	ai.time_limit_usec = usec
	ai.flip_scan_limit = TEST_FLIP_SCAN
	# 固定随机种子，让批量测试可复现
	ai.rng.seed = 20240927 + depth
	return ai


# ---------------------------------------------------------------- 走法生成一致性
func _test_move_gen_equivalence() -> void:
	print("- 走法生成 vs 规则引擎（%d 个随机局面）" % EQUIV_TRIALS)
	var ai := JunqiAI.new()
	var bad: int = 0
	for trial in EQUIV_TRIALS:
		var g := JunqiGame.new()
		var r := RandomNumberGenerator.new()
		r.seed = trial
		g.setup(r)
		var hidden: Array[Vector2i] = g.hidden_positions()
		var n: int = (trial * 7) % 40
		for i in mini(n, hidden.size()):
			g.flip_piece(hidden[i])
		for side: int in [JunqiData.Side.RED, JunqiData.Side.BLUE]:
			ai._load(g)
			var got: Dictionary = {}
			for m: int in ai._gen(side):
				var from: Vector2i = ai._pos(m / JunqiAI.N)
				var to: Vector2i = ai._pos(m % JunqiAI.N)
				if not got.has(from):
					got[from] = []
				got[from].append(to)
			var want: Dictionary = g.all_moves(side)
			if not _same_moves(want, got):
				bad += 1
				if bad <= 3:
					print("    不一致：trial=%d side=%d" % [trial, side])
					print("      want=", want)
					print("      got =", got)
	print("    完成，不一致 %d / %d" % [bad, EQUIV_TRIALS * 2])
	if bad > 0:
		_fail("AI 走法生成与规则引擎不一致")


func _same_moves(want: Dictionary, got: Dictionary) -> bool:
	if want.size() != got.size():
		return false
	for from: Vector2i in want:
		var a: Array = want[from]
		var b: Array = got.get(from, [])
		if a.size() != b.size():
			return false
		for to: Vector2i in a:
			if to not in b:
				return false
	return true


# ---------------------------------------------------------------- 自我对弈合法性
func _test_self_play_legality() -> void:
	print("- 大师 AI 自我对弈 %d 盘" % SELF_GAMES)
	var ai := _make_ai(TEST_DEPTH, TEST_NODES, TEST_TIME_USEC)
	var t0: int = Time.get_ticks_msec()
	var total_plies: int = 0
	var wins := {JunqiData.Side.RED: 0, JunqiData.Side.BLUE: 0}
	var draws: int = 0
	for i in SELF_GAMES:
		var g := JunqiGame.new()
		g.setup()
		var side: int = JunqiData.Side.RED
		var plies: int = 0
		while g.winner == -1 and not g.is_draw and plies < MAX_PLIES:
			if not g.has_action(side):
				g.declare_no_action(side)
				break
			var action: Dictionary = ai.decide(g, side)
			if action.is_empty():
				g.declare_no_action(side)
				break
			if not _apply_checked(g, side, action):
				break
			plies += 1
			side = 1 - side
		total_plies += plies
		if g.winner == -1:
			draws += 1
		else:
			wins[g.winner] += 1
		if plies >= MAX_PLIES:
			_fail("自我对弈无法结束")
	var dt: int = Time.get_ticks_msec() - t0
	print("    红胜 %d / 蓝胜 %d / 和 %d，平均 %.0f 手，用时 %d ms"
		% [wins[0], wins[1], draws, float(total_plies) / float(SELF_GAMES), dt])


## 执行并校验一个动作；非法则记失败
func _apply_checked(g: JunqiGame, side: int, action: Dictionary) -> bool:
	if String(action.get("action", "")) == "flip":
		var pos: Vector2i = action["pos"]
		var p: JunqiGame.Piece = g.piece_at(pos)
		if p == null or p.revealed:
			_fail("AI 翻了非暗棋 %s" % str(pos))
			return false
		g.flip_piece(pos)
		return true
	var from: Vector2i = action["from"]
	var to: Vector2i = action["to"]
	var mover: JunqiGame.Piece = g.piece_at(from)
	if mover == null or mover.side != side or not mover.can_move():
		_fail("AI 移动了非法棋子 %s" % str(from))
		return false
	if to not in g.valid_moves(mover):
		_fail("AI 走出非法着法 %s -> %s" % [str(from), str(to)])
		return false
	g.move_piece(from, to)
	return true


# ---------------------------------------------------------------- 强度对比
func _test_strength_vs_greedy() -> void:
	print("- 大师 AI vs 贪心 AI（%d 盘）" % STRENGTH_GAMES)
	var master := _make_ai(TEST_DEPTH, TEST_NODES, TEST_TIME_USEC)
	var master_wins: int = 0
	var greedy_wins: int = 0
	var draws: int = 0
	var diff_sum: float = 0.0
	var t0: int = Time.get_ticks_msec()
	for i in STRENGTH_GAMES:
		var g := JunqiGame.new()
		g.setup()
		var master_side: int = JunqiData.Side.RED if i % 2 == 0 else JunqiData.Side.BLUE
		var side: int = JunqiData.Side.RED
		var plies: int = 0
		while g.winner == -1 and not g.is_draw and plies < MAX_PLIES:
			if not g.has_action(side):
				g.declare_no_action(side)
				break
			var action: Dictionary
			if side == master_side:
				action = master.decide(g, side)
			else:
				action = _greedy_decide(g, side)
			if action.is_empty():
				g.declare_no_action(side)
				break
			if not _apply_checked(g, side, action):
				break
			plies += 1
			side = 1 - side
		if g.winner == -1:
			draws += 1
		elif g.winner == master_side:
			master_wins += 1
		else:
			greedy_wins += 1
		diff_sum += _material_diff(g, master_side)
	var dt: int = Time.get_ticks_msec() - t0
	var avg_diff: float = diff_sum / float(STRENGTH_GAMES)
	print("    大师胜 %d / 贪心胜 %d / 和 %d，平均子力差 %+.1f，用时 %d ms"
		% [master_wins, greedy_wins, draws, avg_diff, dt])
	# 翻翻棋在“挖光地雷才能夺旗”的规则下和棋很多，用子力差衡量更可靠
	if avg_diff <= 0.0:
		_fail("大师 AI 的平均子力差不为正（%+.1f）" % avg_diff)
	if master_wins + draws < greedy_wins:
		_fail("大师 AI 的战绩明显劣于贪心 AI")


## 大师一方剩余子力 − 对方剩余子力
func _material_diff(game: JunqiGame, side: int) -> float:
	var mine: float = 0.0
	var theirs: float = 0.0
	for pos: Vector2i in game.cells:
		var p: JunqiGame.Piece = game.cells[pos]
		var v: float = float(JunqiData.value_of(p.kind))
		if p.side == side:
			mine += v
		else:
			theirs += v
	return mine - theirs


## 旧版贪心策略（仅做一步启发式评估，作为对照基线）
func _greedy_decide(game: JunqiGame, side: int) -> Dictionary:
	var moves: Dictionary = game.all_moves(side)
	var best: Dictionary = {}
	var best_score: float = -INF
	for from: Vector2i in moves:
		var p: JunqiGame.Piece = game.piece_at(from)
		if p == null:
			continue
		for to: Vector2i in moves[from]:
			var score: float = 0.0
			var target: JunqiGame.Piece = game.piece_at(to)
			var mv: float = float(JunqiData.value_of(p.kind))
			if target != null:
				var combat: int = JunqiGame.resolve_kinds(p.kind, target.kind)
				var tv: float = float(JunqiData.value_of(target.kind))
				match combat:
					JunqiGame.Combat.FLAG_DOWN:
						return {"action": "move", "from": from, "to": to}
					JunqiGame.Combat.ATTACKER_WIN:
						score = 30.0 + tv
					JunqiGame.Combat.BOTH_DIE:
						score = 30.0 + tv - mv * 1.35
					_:
						score = -400.0 - mv
			else:
				score = 1.0
				if JunqiMap.is_camp(to):
					score += 10.0
			if JunqiMap.is_camp(from) and not JunqiMap.is_camp(to):
				score -= 8.0
			score += rng.randf() * 1.5
			if score > best_score:
				best_score = score
				best = {"action": "move", "from": from, "to": to}
	var hidden: Array[Vector2i] = game.hidden_positions()
	if not hidden.is_empty():
		var progress: float = float(game.revealed_count(-1)) / 50.0
		var flip_score: float = lerpf(70.0, -35.0, progress) + rng.randf() * 4.0
		if flip_score > best_score:
			return {"action": "flip", "pos": hidden[rng.randi_range(0, hidden.size() - 1)]}
	if not best.is_empty():
		return best
	return {}


# ---------------------------------------------------------------- 默认预算速度
## 默认（大师级）设置下，单步决策不应慢到卡住界面
func _test_default_budget_speed() -> void:
	print("- 默认大师级预算的单步耗时")
	var g := JunqiGame.new()
	g.setup()
	var hidden: Array[Vector2i] = g.hidden_positions()
	for i in 30:
		g.flip_piece(hidden[i])
	var ai := JunqiAI.new()
	var worst: int = 0
	for k in 6:
		var t0: int = Time.get_ticks_usec()
		var action: Dictionary = ai.decide(g, k % 2)
		var dt: int = Time.get_ticks_usec() - t0
		worst = maxi(worst, dt)
		if action.is_empty():
			break
		if String(action.get("action", "")) == "flip":
			g.flip_piece(action["pos"])
		else:
			g.move_piece(action["from"], action["to"])
	print("    最慢一步 %.0f ms（预算 %.0f ms）" % [worst / 1000.0, JunqiAI.TIME_LIMIT_USEC / 1000.0])
	if worst > 2500000:
		_fail("默认预算下一步思考超过 2.5 秒")

# tests/logic_test.gd
# 纯逻辑自测：规则表、棋盘拓扑、走法合法性、以及随机自动对局压力测试（headless）
# 运行： godot --headless --script res://tests/logic_test.gd

extends SceneTree

const GAMES: int = 200
const MAX_PLIES: int = 2000

var failures: int = 0
var rng: RandomNumberGenerator = RandomNumberGenerator.new()


func _init() -> void:
	rng.seed = 20240927
	print("=== 军旗翻翻棋 逻辑自测 ===")

	_test_combat_table()
