	print("  [FAIL] ", msg)


func _expect(label: String, ok: bool) -> void:
	if not ok:
		_fail(label)


# ---------------------------------------------------------------- 战斗判定
func _test_combat_table() -> void:
	print("- 战斗判定表")
	var A := JunqiGame.Combat.ATTACKER_WIN
	var D := JunqiGame.Combat.DEFENDER_WIN
	var B := JunqiGame.Combat.BOTH_DIE
	var F := JunqiGame.Combat.FLAG_DOWN

	var cases: Array = [
		[JunqiData.PieceType.COMMANDER, JunqiData.PieceType.ARMY_COMMANDER, A, "司令吃军长"],
		[JunqiData.PieceType.ARMY_COMMANDER, JunqiData.PieceType.COMMANDER, D, "军长撞司令"],
		[JunqiData.PieceType.PLATOON, JunqiData.PieceType.PLATOON, B, "排长对排长"],
		[JunqiData.PieceType.ENGINEER, JunqiData.PieceType.MINE, A, "工兵挖地雷"],
		[JunqiData.PieceType.BOMB, JunqiData.PieceType.MINE, B, "炸弹炸地雷"],
		[JunqiData.PieceType.COMMANDER, JunqiData.PieceType.MINE, D, "司令撞地雷（非法动作，纯函数保留 D）"],
		[JunqiData.PieceType.BOMB, JunqiData.PieceType.COMMANDER, B, "炸弹换司令"],
		[JunqiData.PieceType.COMMANDER, JunqiData.PieceType.BOMB, B, "司令碰炸弹"],
		[JunqiData.PieceType.PLATOON, JunqiData.PieceType.FLAG, F, "排长夺旗"],
		[JunqiData.PieceType.ENGINEER, JunqiData.PieceType.FLAG, F, "工兵夺旗"],
		[JunqiData.PieceType.BOMB, JunqiData.PieceType.FLAG, B, "炸弹炸旗（同归）"],
	]
	for c: Array in cases:
		var got: int = JunqiGame.resolve_kinds(int(c[0]), int(c[1]))
		if got != int(c[2]):
			_fail("%s：期望 %d，实际 %d" % [c[3], c[2], got])
	print("  完成")


## 军衔大小：司令 > 军长 > 师长 > 旅长 > 团长 > 营长 > 连长 > 排长 > 工兵
## 以「团长」为例逐项验证（同归于尽 / 不能吃大的 / 能吃小的）
func _test_rank_table() -> void:
	print("- 军衔大小（团长为例）")
	var order: Array[int] = [
		JunqiData.PieceType.COMMANDER,
		JunqiData.PieceType.ARMY_COMMANDER,
		JunqiData.PieceType.DIVISION,
		JunqiData.PieceType.BRIGADE,
		JunqiData.PieceType.REGIMENT,
		JunqiData.PieceType.BATTALION,
		JunqiData.PieceType.COMPANY,
		JunqiData.PieceType.PLATOON,
		JunqiData.PieceType.ENGINEER,
	]
	# 等级必须严格递减
	for i in range(1, order.size()):
		if JunqiData.rank_of(order[i]) >= JunqiData.rank_of(order[i - 1]):
			_fail("军衔没有严格递减：%s vs %s"
				% [JunqiData.piece_name(order[i - 1]), JunqiData.piece_name(order[i])])

	var me: int = JunqiData.PieceType.REGIMENT
	for k: int in order:
		var got: int = JunqiGame.resolve_kinds(me, k)
		var rk: int = JunqiData.rank_of(k)
		var rm: int = JunqiData.rank_of(me)
		if rk > rm:
			_expect("团长不应吃 %s" % JunqiData.piece_name(k), got == JunqiGame.Combat.DEFENDER_WIN)
		elif rk == rm:
			_expect("团长遇团长应同归于尽", got == JunqiGame.Combat.BOTH_DIE)
		else:
			_expect("团长应吃 %s" % JunqiData.piece_name(k), got == JunqiGame.Combat.ATTACKER_WIN)
	# 反方向也不能乱
	_expect("旅长应吃团长",
		JunqiGame.resolve_kinds(JunqiData.PieceType.BRIGADE, me) == JunqiGame.Combat.ATTACKER_WIN)
	_expect("营长不应吃团长",
		JunqiGame.resolve_kinds(JunqiData.PieceType.BATTALION, me) == JunqiGame.Combat.DEFENDER_WIN)
	print("  完成")


# ---------------------------------------------------------------- 三维几何
func _test_map_geometry() -> void:
	print("- 三维几何")
	for row in range(1, JunqiMap.ROWS):
		if JunqiMap.row_z(row) <= JunqiMap.row_z(row - 1):
			_fail("第 %d 行的 Z 没有递增" % row)
	var inner: float = JunqiMap.row_z(6) - JunqiMap.row_z(5)
	var outer: float = JunqiMap.row_z(7) - JunqiMap.row_z(6)
	if absf(inner - outer) > 0.0001:
		_fail("中线两侧间距不对称")
	if inner <= JunqiMap.CELL_Z:
		_fail("山界没有加宽")
	var bsize: Vector2 = JunqiMap.board_size()
	if bsize.x <= 0.0 or bsize.y <= 0.0:
		_fail("棋盘尺寸非法")
	if JunqiMap.get_placeable_positions().size() != 50:
		_fail("可落子点位数不是 50")
	for pos: Vector2i in JunqiMap.all_positions():
		var w: Vector3 = JunqiMap.to_world(pos)
		if absf(w.y) > 0.0001:
			_fail("棋盘顶面不在 y = 0：%s" % str(w))
		if JunqiMap.world_to_pos(w) != pos:
			_fail("世界坐标回转失败：%s" % str(pos))
		if not JunqiMap.piece_aabb(pos).has_point(JunqiMap.piece_world(pos)):
			_fail("棋子包围盒没有包住棋子中心：%s" % str(pos))
	if JunqiMap.rail_edges().size() % 2 != 0 or JunqiMap.rail_edges().is_empty():
		_fail("铁路边列表异常")
	# 行营后方不再有“斜向铁路”
	for camp: Vector2i in JunqiMap.CAMPS:
		for n: Vector2i in JunqiMap.get_rail_neighbors(camp):
			var d: Vector2i = n - camp
			if abs(d.x) == 1 and abs(d.y) == 1:
				_fail("行营 %s 仍连着斜向铁路 %s" % [str(camp), str(n)])
	print("  棋盘 %.2f × %.2f，铁路边 %d 条" % [bsize.x, bsize.y, JunqiMap.rail_edges().size() / 2])


## 行营四周的斜线是「公路」：被四面包围时，仍能沿斜线走一步。
## 这是“个别棋子不能移动”的关键回归测试。
func _test_diagonal_roads() -> void:
	print("- 行营斜向公路")
	for camp: Vector2i in JunqiMap.CAMPS:
		for dr: int in [-1, 1]:
			for dc: int in [-1, 1]:
				var diag: Vector2i = camp + Vector2i(dr, dc)
				if not JunqiMap.is_valid_pos(diag):
					continue
				if diag not in JunqiMap.get_road_neighbors(camp):
					_fail("行营 %s 与斜角 %s 之间缺少公路" % [str(camp), str(diag)])

	# 构造：中央行营放一枚排长，四个正方向全被己方棋子堵死，斜角留空。
	var camp: Vector2i = Vector2i(3, 2)
	var game := JunqiGame.new()
	game.cells.clear()
	game.winner = -1
	var me := _make_piece(JunqiData.Side.RED, JunqiData.PieceType.PLATOON, camp, true)
	game.cells[camp] = me
	for n: Vector2i in [Vector2i(2, 2), Vector2i(4, 2), Vector2i(3, 1), Vector2i(3, 3)]:
		game.cells[n] = _make_piece(JunqiData.Side.RED, JunqiData.PieceType.ENGINEER, n, true)
	var moves: Array[Vector2i] = game.valid_moves(me)
	var diag_moves: Array[Vector2i] = [
		Vector2i(2, 1), Vector2i(2, 3), Vector2i(4, 1), Vector2i(4, 3),
	]
	var found: bool = false
	for d: Vector2i in diag_moves:
		if d in moves:
			found = true
	_expect("四面包围的行营棋子仍能沿斜线移动", found)
	print("  行营 %s 可走 %d 步（含斜向 %s）" % [str(camp), moves.size(), str(found)])


## 铁道“飞行”：只有工兵能沿铁路远距离移动，其它棋子即使在铁道上也只能走一步。
func _test_rail_fly() -> void:
	print("- 铁道飞行（仅工兵）")
	if not JunqiGame.RAIL_FLY_ENGINEER_ONLY:
		print("  （当前配置允许所有棋子滑动，跳过）")
		return
	var g := JunqiGame.new()
	g.cells.clear()
	g.winner = -1
	var start: Vector2i = Vector2i(1, 0)   # 第 1 行横向铁路与第 0 列纵向铁路的交点

	var co := _make_piece(JunqiData.Side.RED, JunqiData.PieceType.COMPANY, start, true)
	g.cells[start] = co
	var moves: Array[Vector2i] = g.valid_moves(co)
	_expect("非工兵不能沿铁路飞到 (1,4)", Vector2i(1, 4) not in moves)
	_expect("非工兵不能沿铁路飞到 (6,0)", Vector2i(6, 0) not in moves)
	_expect("非工兵仍能走到相邻 (1,1)", Vector2i(1, 1) in moves)

	g.cells.clear()
	var eng := _make_piece(JunqiData.Side.RED, JunqiData.PieceType.ENGINEER, start, true)
	g.cells[start] = eng
	var emoves: Array[Vector2i] = g.valid_moves(eng)
	_expect("工兵能沿铁路飞到 (1,4)", Vector2i(1, 4) in emoves)
	_expect("工兵能沿铁路飞到 (6,0)", Vector2i(6, 0) in emoves)
	_expect("工兵能在铁路上转弯到 (5,2)", Vector2i(5, 2) in emoves)
	print("  非工兵可走 %d 步，工兵可走 %d 步" % [moves.size(), emoves.size()])


## 地雷 / 军旗 的官方规则
func _test_mine_flag_rules() -> void:
	print("- 地雷 / 军旗规则")
	var game := JunqiGame.new()
	game.cells.clear()
	game.winner = -1

	# 工兵 / 炸弹 / 其它棋子 对地雷
	var mine_pos: Vector2i = Vector2i(5, 1)
	var eng_pos: Vector2i = Vector2i(5, 0)
	var bomb_pos: Vector2i = Vector2i(5, 2)
	var reg_pos: Vector2i = Vector2i(4, 1)
	game.cells[mine_pos] = _make_piece(JunqiData.Side.BLUE, JunqiData.PieceType.MINE, mine_pos, true)
	var eng := _make_piece(JunqiData.Side.RED, JunqiData.PieceType.ENGINEER, eng_pos, true)
	var bomb := _make_piece(JunqiData.Side.RED, JunqiData.PieceType.BOMB, bomb_pos, true)
	var reg := _make_piece(JunqiData.Side.RED, JunqiData.PieceType.REGIMENT, reg_pos, true)
	game.cells[eng_pos] = eng
	game.cells[bomb_pos] = bomb
	game.cells[reg_pos] = reg
	_expect("工兵可以移动到地雷", game.can_move_to(eng, mine_pos))
	_expect("炸弹可以移动到地雷", game.can_move_to(bomb, mine_pos))
	_expect("普通棋子不能主动触碰地雷", not game.can_move_to(reg, mine_pos))

	# 军旗：对方还有雷时不可被擎
	var flag_pos: Vector2i = Vector2i(0, 1)
	var flag := _make_piece(JunqiData.Side.BLUE, JunqiData.PieceType.FLAG, flag_pos, true)
	game.cells[flag_pos] = flag
	# 路径：把地雷挪走，换成 3 枚藏起来的蓝雷（计数仍然生效）
	game.cells.erase(mine_pos)
	for i in 3:
		var p: Vector2i = Vector2i(12, i)
		game.cells[p] = _make_piece(JunqiData.Side.BLUE, JunqiData.PieceType.MINE, p, false)
	_expect("对方还有 3 雷时不能夺旗", not game.can_move_to(eng, flag_pos))
	_expect("mine_count(BLUE) == 3", game.mine_count(JunqiData.Side.BLUE) == 3)
	# 挖掉 3 颗雷后即可夺旗
	for i in 3:
		game.cells.erase(Vector2i(12, i))
	_expect("地雷挖光后可以夺旗", game.can_move_to(eng, flag_pos))
	print("  完成")


# ---------------------------------------------------------------- 初始布阵
func _test_initial_setup() -> void:
	print("- 初始布阵")
	for i in 20:
		var g := JunqiGame.new()
		g.setup()
		if g.cells.size() != 50:
			_fail("棋子总数 %d != 50" % g.cells.size())
