			_fail("红方棋子数 != 25")
		if g.side_count(JunqiData.Side.BLUE) != 25:
			_fail("蓝方棋子数 != 25")
		if g.hidden_positions().size() != 50:
			_fail("开局应当全部为暗棋")
		var flags := 0
		for pos: Vector2i in g.cells:
			var p: JunqiGame.Piece = g.cells[pos]
			if JunqiMap.is_camp(pos):
				_fail("棋子被放到了行营：%s" % str(pos))
			if p.is_flag():
				flags += 1
		if flags != 2:
			_fail("军旗数量 %d != 2" % flags)
