import { BoardSquarePieceMap, FRONT_ROW_SQUARES, HEADQUARTER_SQUARES, PLAYER1_BACK_ROW_RAIL, PLAYER2_BACK_ROW_RAIL } from './BoardConstants';
import { BoardValidator } from './BoardValidator';
import { Piece, PieceRank } from './Piece';

export class BoardShuffler {
  boardValidator: BoardValidator;

  constructor(boardValidator: BoardValidator) {
    this.boardValidator = boardValidator;
  }

  /**
   * Randomly rearrange one player's pieces among their own squares for setup,
   * keeping the board valid and avoiding placements no rational player would make.
   */
  shuffle(boardState: BoardSquarePieceMap, squares: string[]): void {
    const remainingPieces = squares.map((square) => boardState[square]!);

    const remainingSquares = new Set(squares);
    const assignment: BoardSquarePieceMap = {};

    // Assign the most constrained pieces/squares first, so unrestricted pieces
    // are left to fill whatever pieces and squares remain.
    const placeGroup = (matchesPiece: (piece: Piece) => boolean, candidateSquares: string[], maxCount: number = Infinity): void => {
      const eligibleSquares = this.shuffleCopy(candidateSquares.filter((square) => remainingSquares.has(square)));
      // Cap to available squares - a matcher can match more pieces than there are squares left.
      const groupPieces = this.shuffleCopy(remainingPieces.filter(matchesPiece)).slice(0, Math.min(eligibleSquares.length, maxCount));

      groupPieces.forEach((piece, i) => {
        const square = eligibleSquares[i];
        assignment[square] = piece;
        remainingSquares.delete(square);
        remainingPieces.splice(remainingPieces.indexOf(piece), 1);
      });
    };

    const hqSquares = squares.filter((square) => HEADQUARTER_SQUARES.includes(square));
    // Row in front of HQ - reserving one landmine here guarantees not all 3 end up on the HQ row.
    const frontGuardRow = squares.filter((square) => PLAYER1_BACK_ROW_RAIL.includes(square) || PLAYER2_BACK_ROW_RAIL.includes(square));

    placeGroup((piece) => piece.getRank() === PieceRank.FLAG, hqSquares);
    placeGroup((piece) => piece.getRank() === PieceRank.LANDMINE, frontGuardRow, 1);
    // HQ squares have zero legal moves for the rest of the game, so the non-flag one
    // should only ever hold a landmine or a lieutenant - nothing worth losing that way.
    placeGroup((piece) => piece.getRank() === PieceRank.LANDMINE || piece.getRank() === PieceRank.LIEUTENANT, hqSquares);

    // HQ row's other 3 squares: near-flag corner is a fair reserve position; center and
    // far corner aren't (a piece there either gets stuck, or freeing it telegraphs which
    // HQ is real). Center is worse still (exposes both HQ squares at once), hence the
    // tighter limit. HQ squares are always 'b'/'d' columns, so center/corners are built
    // directly rather than derived by elimination over the row.
    const flagSquare = hqSquares.find((square) => assignment[square]?.getRank() === PieceRank.FLAG)!;
    const hqRow = this.boardValidator.getBoardSquareRow(flagSquare);
    const centerSquare = `c${hqRow}`;
    const nearFlagColumn = flagSquare[0] === 'b' ? 'a' : 'e';
    const farFlagColumn = nearFlagColumn === 'a' ? 'e' : 'a';
    const nearFlagCorner = `${nearFlagColumn}${hqRow}`;
    const farFlagCorner = `${farFlagColumn}${hqRow}`;

    placeGroup((piece) => piece.getRank() === PieceRank.LANDMINE || piece.getRank() === PieceRank.LIEUTENANT, [centerSquare]);
    placeGroup((piece) => [PieceRank.CAPTAIN, PieceRank.LIEUTENANT, PieceRank.LANDMINE].includes(piece.getRank()), [farFlagCorner]);
    // Engineer excluded too: deploying it later means first moving it onto a railroad,
    // which costs a turn and exposes the flag the same way extracting any other piece does
    placeGroup((piece) => ![PieceRank.FLAG, PieceRank.COMMANDER, PieceRank.GENERAL, PieceRank.BOMB, PieceRank.ENGINEER].includes(piece.getRank()), [nearFlagCorner]);

    // a/c/e front-row squares have a direct edge to the enemy's front row (only those
    // 3 column pairs, per Graph.ts) - earliest contact point, bad for Engineer (needed
    // alive for mines later). Ordinary combat piece specifically, not just "not
    // Engineer" - Landmine/Bomb are still unplaced and have their own row rules.
    const exposedFrontRow = squares.filter((square) => FRONT_ROW_SQUARES.includes(square) && ['a', 'c', 'e'].includes(square[0]));
    placeGroup((piece) => piece.getRank() >= PieceRank.COMMANDER && piece.getRank() <= PieceRank.LIEUTENANT, exposedFrontRow);

    placeGroup((piece) => piece.getRank() === PieceRank.LANDMINE, squares.filter((square) => this.boardValidator.isValidLandminePosition(this.boardValidator.getBoardSquareRow(square))));
    // Bomb is kept off the whole HQ row, not just the front row - once it's gone the row behind it is exposed
    placeGroup((piece) => piece.getRank() === PieceRank.BOMB, squares.filter((square) => this.boardValidator.isValidBombPosition(this.boardValidator.getBoardSquareRow(square)) && this.boardValidator.getBoardSquareRow(square) !== hqRow));

    // Remaining pieces have no placement restrictions
    placeGroup(() => true, squares);

    squares.forEach((square) => {
      boardState[square] = assignment[square];
    });
  }

  // Returns a new array containing the same elements in random order
  private shuffleCopy<T>(items: T[]): T[] {
    const copy = items.slice();
    for (let i = copy.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [copy[i], copy[j]] = [copy[j], copy[i]];
    }
    return copy;
  }
}

import { BoardSquarePieceMap, BUNKER_SQUARES, HEADQUARTER_SQUARE_GROUP, HEADQUARTER_SQUARES } from './BoardConstants';
import {
    Piece,
    PieceRank,
} from './Piece';

export class BoardValidator {
    validateBoard(board: BoardSquarePieceMap): boolean {
        return Object.keys(board).every(square => {
            // Bunker squares should always be empty in beginning
            if (BUNKER_SQUARES.includes(square)) {
                return board[square] === null;
            }

            // All other squares must have a piece
            const piece: Piece | null = board[square];
            if (!piece) {
                return false;
            }

            const squareRowNum: number = this.getBoardSquareRow(square);
            if (piece.getRank() === PieceRank.BOMB) {
                return this.isValidBombPosition(squareRowNum);
            } else if (piece.getRank() === PieceRank.LANDMINE) {
                return this.isValidLandminePosition(squareRowNum);
            } else if (piece.getRank() === PieceRank.FLAG) {
                // flag must be in headquarters
                return HEADQUARTER_SQUARES.includes(square);
            }

            return true;
        });
    }

    // Assumes current position is valid
    isDestinationPositionValid(pieceRank: PieceRank, current: string, destination: string): boolean {
        const destRowNum: number = this.getBoardSquareRow(destination);
        // Check if piece has restrictions
        if (pieceRank === PieceRank.BOMB) {
            return this.isValidBombPosition(destRowNum);
        } else if (pieceRank === PieceRank.LANDMINE) {
            return this.isValidLandminePosition(destRowNum);
        } else if (pieceRank === PieceRank.FLAG) {
            return this.isValidFlagPosition(current, destination);
        }

        // piece has no restrictions
        // can be placed anywhere on the player's side
        return true;
    }

    getBoardSquareRow(square: string): number {
        return parseInt(square.substring(1, square.length));
    }

    isValidBombPosition(rowNum: number): boolean {
        // don't allow front row placement
        const isPlayer1FrontRow = (rowNum === 6);
        const isPlayer2FrontRow = (rowNum === 7);
        return !isPlayer1FrontRow && !isPlayer2FrontRow;
    }

    isValidLandminePosition(rowNum: number): boolean {
        // landmines only in back two rows
        const isPlayer1BackTwoRows = (rowNum === 1 || rowNum === 2);
        const isPlayer2BackTwoRows = (rowNum === 11 || rowNum === 12);
        return isPlayer1BackTwoRows || isPlayer2BackTwoRows;
    }

    isValidFlagPosition(current: string, destination: string): boolean {
        // flag can only go in headquarters
        const isPlayer1Headquarters = HEADQUARTER_SQUARE_GROUP[0].includes(current) && HEADQUARTER_SQUARE_GROUP[0].includes(destination) && current != destination;
        const isPlayer2Headquarters = HEADQUARTER_SQUARE_GROUP[1].includes(current) && HEADQUARTER_SQUARE_GROUP[1].includes(destination) && current != destination;
        return isPlayer1Headquarters || isPlayer2Headquarters;
    }
}

import { Board, PlayerMove, SwapMove } from './Board';
import { Piece, PieceRank } from './Piece';
import { ClientPieceView, FilteredBoardState, GameStateDTO, GameStatus, PlayerSession, PlayerStatus } from '../types';

/*
 * The Game object
 */

export class Game {
    status: GameStatus;
    activePlayer: PlayerStatus | null;
    players: PlayerStatus[];
    board: Board;
    capturedPieces: Piece[];
    validMoves: PlayerMove[];
    validSwap: SwapMove[];
    lastMove: PlayerMove | null;
    modifiedOn: number;
    colorMap: { [key: string]: number };

    /**
     * Create new game and initialize
     */
    constructor(params: PlayerSession) {
        // pending/ongoing/defeat/forfeit
        this.status = GameStatus.PENDING;

        this.activePlayer = null;

        this.players = [
            { color: null, name: null, joined: false, isSetup: false, flagCaptured: false, hasCommander: true, hasMoveablePieces: true, forfeited: false },
            { color: null, name: null, joined: false, isSetup: false, flagCaptured: false, hasCommander: true, hasMoveablePieces: true, forfeited: false }
        ];

        this.board = new Board();

        this.capturedPieces = [];

        this.validMoves = this.board.getMovesForPlayer('blue');

        this.validSwap = this.board.getSwapForAll();

        this.lastMove = null;

        this.modifiedOn = Date.now();

        this.colorMap = {};

        // Set player colors
        // params.playerColor is the color of the player who created the game
        if (params.playerColor === 'red') {
            this.players[0].color = 'red';
            this.players[1].color = 'blue';

            this.colorMap = { 'r': 0, 'b': 1 };
        } else if (params.playerColor === 'blue') {
            this.players[0].color = 'blue';
            this.players[1].color = 'red';

            this.colorMap = { 'b': 0, 'r': 1 };
        }
    }

    /**
     * Get the current game state as a plain object for data transfer
     * @param playerColor - The color of the player requesting the state (for filtering)
     */
    getState(playerColor?: string): GameStateDTO {
        const baseState: GameStateDTO = {
            status: this.status,
            activePlayer: this.activePlayer,
            players: this.players,
            capturedPieces: playerColor ?
                this.capturedPieces.filter(p => p.colorChar === playerColor) :
                this.capturedPieces,
            validMoves: this.validMoves,
            validSwap: this.validSwap,
            lastMove: this.lastMove,
            modifiedOn: this.modifiedOn,
            colorMap: this.colorMap,
            // No playerColor means an unfiltered admin/spectator view
            board: playerColor ? this.getFilteredBoardState(playerColor) : this.board.boardState
        };

        return baseState;
    }

    /**
     * Get filtered board state for a specific player
     * Hides opponent piece ranks to maintain game security
     */
    private getFilteredBoardState(playerColor: string): FilteredBoardState {
        const filteredState: FilteredBoardState = {};

        Object.keys(this.board.boardState).forEach(square => {
            const piece = this.board.boardState[square];
            if (!piece) {
                filteredState[square] = null; // Empty square
            } else if (piece.colorChar === playerColor[0]) {
                // Own piece - show full information
                filteredState[square] = {
                    colorChar: piece.colorChar,
                    rank: piece.rank
                };
            } else {
                // Opponent piece - hide the rank for security!

                // Find opponent player
                const opponentIndex = this.colorMap[piece.colorChar];
                const opponent = this.players[opponentIndex];

                // Exception: reveal enemy flag if commander is dead
                const shouldRevealFlag = piece.getRank() === PieceRank.FLAG && opponent && !opponent.hasCommander;

                const view: ClientPieceView = shouldRevealFlag
                    ? { colorChar: piece.colorChar, rank: piece.rank }
                    : { colorChar: piece.colorChar, rank: 'hidden' }; // Don't expose actual rank!

                filteredState[square] = view;
            }
        });
        return filteredState;
    }

    /**
     * Add player to game, and after both players have joined activate the game.
     * Returns true on success and false on failure.
     */
    addPlayer(playerData: PlayerSession): boolean {
        // Check for an open spot
        const p = this.players.find(player => player.color === playerData.playerColor && !player.joined);
        if (!p) { return false; }

        // Set player info
        p.name = playerData.playerName;
        p.joined = true;

        this.modifiedOn = Date.now();

        return true;
    }

    /**
     * Remove player from game
     */
    removePlayer(playerData: PlayerSession): boolean {
        // Find player in question
        const p = this.players.find(player => player.color === playerData.playerColor);
        if (!p) { return false; }

        // Check if player is actually joined
        if (!p.joined) { return false; }

        // Set player info
        p.joined = false;
        p.name = null;

        this.modifiedOn = Date.now();

        return true;
    }

    /*
    Finalize the setup
    */
    finishSetup(playerData: PlayerSession): boolean {
        const DEFAULT_PLAYER_COLOR = 'blue';
        // Find player in question
        const p = this.players.find(player => player.color === playerData.playerColor);
        if (!p) { return false; }

        // Check if player is actually joined
        if (!p.joined) { return false; }

        // Set player info
        p.isSetup = true;

        // If both players have joined and finish setting up, start the game
        if (
            this.players[0].joined &&
            this.players[0].isSetup &&
            this.players[1].joined &&
            this.players[1].isSetup &&
            this.status === GameStatus.PENDING
        ) {
            this.activePlayer = this.players.find(player => player.color === DEFAULT_PLAYER_COLOR) || null;
            // Generate valid moves based on latest board configuration
            this.validMoves = this.board.getMovesForPlayer(DEFAULT_PLAYER_COLOR);
            this.validSwap = [];
            this.status = GameStatus.ONGOING;
        }

        this.modifiedOn = Date.now();

        return true;
    }

    /**
     * Randomly shuffle a player's own pieces during the setup phase
     */
    shuffleSetup(playerData: PlayerSession): boolean {
        // Find player in question
        const p = this.players.find(player => player.color === playerData.playerColor);
        if (!p) { return false; }

        // Check if player is actually joined
        if (!p.joined) { return false; }

        // Can't reshuffle after setup is finalized
        if (p.isSetup || this.status !== GameStatus.PENDING) { return false; }

        this.board.shufflePlayerPieces(p.color!);

        // Regenerate valid swaps based on the new board configuration
        this.validSwap = this.board.getSwapForAll();

        this.modifiedOn = Date.now();

        return true;
    }

    /**
     * Swap pieces during setup phase
     */
    swapPieces(moveString: string): boolean {
        // Test if swap is valid
        const validSwap = this.validSwap.find(swap =>
            JSON.stringify(swap) === JSON.stringify(this.parseMoveString(moveString))
        );
        if (!validSwap) {
            return false;
        }

        // Apply swap
        const piece1: Piece = this.board.getPieceAtSquare(validSwap.startSquare)!;
        const piece2: Piece = this.board.getPieceAtSquare(validSwap.endSquare)!;

        this.board.placePieceAtSquare(validSwap.startSquare, piece2);
        this.board.placePieceAtSquare(validSwap.endSquare, piece1);

        // Regenerate valid swaps
        this.validSwap = this.board.getSwapForAll();

        this.modifiedOn = Date.now();

        return true;
    }

    evaluateMoveAndModifyBoard(validMove: PlayerMove): boolean {
        // Evaluation is only required for attacks
        // since each unit's rank is hidden from the other player
        let evaluatedMove = validMove;
        if (validMove.type === "attack") {
            const updatedEvaluatedMove = this.board.evaluateMove(validMove.startSquare, validMove.endSquare);
            if (!updatedEvaluatedMove) {
                return false;
            }
            evaluatedMove = updatedEvaluatedMove;
        }

        // Apply move
        const selectedPiece: Piece = this.board.getPieceAtSquare(evaluatedMove.startSquare)!;
        switch (evaluatedMove.type) {
            case 'move':
                this.board.placePieceAtSquare(evaluatedMove.endSquare, selectedPiece);
                this.board.setSquareEmpty(evaluatedMove.startSquare);
                break;

            case 'capture':
                this.capturedPieces.push(this.board.getPieceAtSquare(evaluatedMove.endSquare)!);
                this.board.setSquareEmpty(evaluatedMove.endSquare);

                this.board.placePieceAtSquare(evaluatedMove.endSquare, selectedPiece);
                this.board.setSquareEmpty(evaluatedMove.startSquare);
                break;

            case 'dies':
                this.board.setSquareEmpty(evaluatedMove.startSquare);
                break;

            case 'equal':
                this.capturedPieces.push(this.board.getPieceAtSquare(evaluatedMove.endSquare)!);
                this.board.setSquareEmpty(evaluatedMove.startSquare);
                this.board.setSquareEmpty(evaluatedMove.endSquare);
                break;

            default: break;
        };

        return true;
    }

    /**
     * Apply move and regenerate game state.
     * Returns true on success and false on failure.
     */
    move(moveString: string): boolean {
        if (this.status === GameStatus.PENDING) {
            return this.swapPieces(moveString);
        }

        // player can't swap units during the game
        this.validSwap = [];

        // Test if move is valid
        const validMove = this.validMoves.find(move =>
            JSON.stringify(move) === JSON.stringify(this.parseMoveString(moveString))
        );
        if (!validMove) {
            return false;
        }

        const moveMade = this.evaluateMoveAndModifyBoard(validMove!);
        if (!moveMade) {
            return false;
        }

        // Set this move as last move
        this.lastMove = validMove;

        // Get inactive player
        const inactivePlayer = this.players.find(p => p !== this.activePlayer);

        // Regenerate valid moves
        if (inactivePlayer && inactivePlayer.color) {
            this.validMoves = this.board.getMovesForPlayer(inactivePlayer.color);
        }

        // Set flag-captured status for both players
        this.players.forEach((p: PlayerStatus) => {
            if (p.color) {
                p.flagCaptured = this.board.isPlayerFlagCaptured(p.color);
                p.hasCommander = this.board.isCommanderAlive(p.color);
            }
        });

        // Test for flag capture or no moveable pieces remaining
        if (inactivePlayer && this.validMoves.length === 0) {
            inactivePlayer.hasMoveablePieces = false;
        }

        if (inactivePlayer && inactivePlayer.flagCaptured) {
            this.status = GameStatus.FLAG_CAPTURED;
        }

        if (inactivePlayer && inactivePlayer.hasMoveablePieces === false) {
            this.status = GameStatus.NO_PIECES;
        }

        // Toggle active player
        if (this.status === GameStatus.ONGOING && inactivePlayer) {
            this.activePlayer = inactivePlayer;
        }

        this.modifiedOn = Date.now();

        return true;
    }

    /**
     * Forfeit the game
     */
    forfeit(playerData: PlayerSession): boolean {
        // Find player in question
        const p = this.players.find(player => player.color === playerData.playerColor);
        if (!p) { return false; }

        // Check if player is actually joined
        if (!p.joined) { return false; }

        // Set player info
        p.forfeited = true;

        // Set game status
        this.status = GameStatus.FORFEIT;

        this.modifiedOn = Date.now();

        return true;
    }

    /**
     * Parse a move string and convert it to an object.
     * Returns the move object on success or null on failure.
     */
    parseMoveString(moveString: string): PlayerMove | null {
        // format: "<startSquare> <command> <endSquare>"
        const moveStrArr = moveString.split(" ");

        const startSquare = moveStrArr[0];
        const command = moveStrArr[1];
        const endSquare = moveStrArr[2];

        // Move to empty square
        if (command === '-') {
            return {
                type: 'move',
                startSquare: startSquare,
                endSquare: endSquare
            }
        }
        // Attack the piece
        // The result is unknown until the unit ranks are compared
        else if (command === 'x') {
            return {
                type: 'attack',
                startSquare: startSquare,
                endSquare: endSquare
            }
        }
        //swapping pieces (only allowed during setup)
        else if (command === 's') {
            return {
                type: 'swap',
                startSquare: startSquare,
                endSquare: endSquare
            }
        } else {
            return null;
        }
    };
}

/*
* Defines the adjacency graph for nodes on the board.
*/
import { BUNKER_SQUARES, FRONT_ROW_SQUARES, HEADQUARTER_SQUARES } from './BoardConstants';

interface TransformOffset {
  x: number;
  y: number;
}

// Bunker squares connect in 8 directions
const bunkerTransforms: TransformOffset[] = [
  {x:+0, y:+1}, {x:+1, y:+1},
  {x:+1, y:+0}, {x:+1, y:-1},
  {x:+0, y:-1}, {x:-1, y:-1},
  {x:-1, y:+0}, {x:-1, y:+1}
];
// Most squares connect in 4 directions
const crossTransforms: TransformOffset[] = [
  {x:+0, y:+1}, {x:+1, y:+0},
  {x:+0, y:-1}, {x:-1, y:+0}
]

export class Graph {
  nodes: string[];
  neighborMap: { [key: string]: Set<string> };

  constructor() {
    const graphNodesEdges = this.initializeGraph();

    this.nodes = graphNodesEdges.nodes;
    this.neighborMap = graphNodesEdges.neighborMap;
  }

  getAdjacentNeighbors(currentSquare: string): Set<string> {
    return this.neighborMap[currentSquare];
  }

  initializeGraph() {
    const nodes = this.initializeNodes();
    const neighborMap = this.initializeEdges(nodes);

    return {
      nodes: nodes,
      neighborMap: neighborMap
    }
  }

  initializeNodes(): string[] {
    const allNodes: string[] = [];
    const columnList: string[] = ['a', 'b', 'c', 'd', 'e'];
    columnList.forEach(function(columnChar) {
      for (let row = 1; row <= 12; row++) {
        const nodeKey = columnChar + row;
        allNodes.push(nodeKey);
      }
    });

    return allNodes;
  }

  initializeEdges(nodes: string[]): { [key: string]: Set<string> } {
    const neighborMap: { [key: string]: Set<string> } = {};

    nodes.forEach(currentSquare => {
      // Exclude front row because the neighbor could end up in the opponent's side
      if (FRONT_ROW_SQUARES.includes(currentSquare)) {
        return;
      }
      const adjacentSquares: string[] = this.getMoves(currentSquare, crossTransforms);
      adjacentSquares.forEach(newSquare => {
        this.addEdge(neighborMap, currentSquare, newSquare);
      });
    });

    BUNKER_SQUARES.forEach(currentSquare => {
      const adjacentSquares: string[] = this.getMoves(currentSquare, bunkerTransforms);
      adjacentSquares.forEach(newSquare => {
        this.addEdge(neighborMap, currentSquare, newSquare);
      });
    });

    this.addEdgesInFrontRowSamePlayer(neighborMap)
    this.addEdgesBetweenDifferentPlayers(neighborMap);

    // Set headquarter squares to immobile
    HEADQUARTER_SQUARES.forEach(function(square: string) {
      neighborMap[square].clear();
    });

    return neighborMap;
  }

  getMoves(square: string, transforms: TransformOffset[]): string[] {
      return transforms
        .map((move) => this.transformSquare(square, move))
        .filter((newSquare): newSquare is string => !!newSquare);
  }

  addEdgesInFrontRowSamePlayer(neighborMap: { [key: string]: Set<string> }): void {
    // Player 1: a6 <-> b6 <-> c6 <-> d6 <-> e6
    this.addEdge(neighborMap, "b6", "a6");
    this.addEdge(neighborMap, "b6", "c6");
    this.addEdge(neighborMap, "d6", "c6");
    this.addEdge(neighborMap, "d6", "e6");
    // Player 2: a7 <-> b7 <-> c7 <-> d7 <-> e7
    this.addEdge(neighborMap, "b7", "a7");
    this.addEdge(neighborMap, "b7", "c7");
    this.addEdge(neighborMap, "d7", "c7");
    this.addEdge(neighborMap, "d7", "e7");
  }

  addEdgesBetweenDifferentPlayers(neighborMap: { [key: string]: Set<string> }): void {
    // Add edges between front row nodes on the opposite side
    this.addEdge(neighborMap, "a6", "a7");
    this.addEdge(neighborMap, "c6", "c7");
    this.addEdge(neighborMap, "e6", "e7");
  }

  /**
   * Apply an x and y offset to a starting square to get a destination square.
   * Returns the destination square on success, otherwise returns null
   */
  transformSquare(square: string, transform: TransformOffset): string | null {
    // Parse square
    const column = square[0];
    const row = parseInt(square.substring(1, square.length), 10);

    // Apply transform
    const destColumn = Graph.alpha2num(column) + transform.x;
    const destRow = row + transform.y;

    // Check boundaries
    if (destColumn < 1 || destColumn > 5) { return null; }
    if (destRow < 1 || destRow > 12) { return null; }

    // Return new square
    return Graph.num2alpha(destColumn) + destRow;
  };

  // Add an unconnected edge between node1 and node2
  addEdge(neighborMap: { [key: string]: Set<string> }, node1Key: string, node2Key: string): void {
    // Initialize an empty list for the new nodes
    if (!(node1Key in neighborMap)) {
      neighborMap[node1Key] = new Set<string>();
    }
    if (!(node2Key in neighborMap)) {
      neighborMap[node2Key] = new Set<string>();
    }

    // Add the nodes
    neighborMap[node1Key].add(node2Key);
    neighborMap[node2Key].add(node1Key);
  }

  private static alpha2num(a: string): number {
    switch (a) {
      case 'a': return 1;
      case 'b': return 2;
      case 'c': return 3;
      case 'd': return 4;
      case 'e': return 5;
      default: return 6; // out of bounds
    }
  }

  private static num2alpha(n: number): string {
    switch (n) {
      case 1: return 'a';
      case 2: return 'b';
      case 3: return 'c';
      case 4: return 'd';
      case 5: return 'e';
      default: return 'f'; // out of bounds
    }
  }
}

export enum PieceRank {
  BOMB = 0,
  COMMANDER = 1,
  GENERAL = 2,
  MAJOR_GENERAL = 3,
  BRIGADIER_GENERAL = 4,
  COLONEL = 5,
  MAJOR = 6,
  CAPTAIN = 7,
  LIEUTENANT = 8,
  ENGINEER = 9,
  LANDMINE = 10,
  FLAG = 11
}

export enum GameResult {
  WIN = 1,
  DRAW = 0,
  LOSE = -1
}

export class Piece {
  colorChar: string;
  rank: PieceRank;

  constructor(colorChar: string, rank: PieceRank) {
    this.colorChar = colorChar;
    this.rank = rank;
  }

  getPieceColor(): string {
    return this.colorChar;
  }

  getRank(): PieceRank {
    return this.rank;
  }

  isMovable(): boolean {
    return this.rank !== PieceRank.LANDMINE && this.rank !== PieceRank.FLAG;
  }

  // compares this piece's rank with another piece's rank
  // returns  1 if this piece wins
  //          0 if they draw
  //          -1 if this piece loses
  compareRank(otherPiece: Piece): GameResult {
    const rank1 = this.rank;
    const rank2 = otherPiece.rank;

    // the opponent is a bomb, which destroys any piece that hits it
    if (rank1 === PieceRank.BOMB || rank2 === PieceRank.BOMB) {
      return GameResult.DRAW;
    }

    // the opponent is a flag, which any of your pieces can capture
    if (rank2 === PieceRank.FLAG) {
      return GameResult.WIN;
    }

    // the opponent is a landmine, which only the engineer can disable
    if (rank2 === PieceRank.LANDMINE) {
      // engineer disables landmine
      if (rank1 === PieceRank.ENGINEER) {
        return GameResult.WIN;
      } else {
        // no other piece can disable it
        return GameResult.LOSE;
      }
    }

    // 2 regular pieces
    // the lower the number, the higher the rank (1 beats 2, 2 beats 3, etc.)
    if (rank1 >= PieceRank.COMMANDER && rank1 <= PieceRank.ENGINEER && 
        rank2 >= PieceRank.COMMANDER && rank2 <= PieceRank.ENGINEER) {
      if (rank1 < rank2) {
        return GameResult.WIN;
      } else if (rank1 === rank2) {
        return GameResult.DRAW;
      } else {
        return GameResult.LOSE;
      }
    }

    // should not reach this point
    return GameResult.DRAW;
  }
}

import { Graph } from './Graph';
import { Piece } from './Piece';

export class RailroadNetwork {
  graph: Graph;
  railLines: string[][];

  constructor(railLines: string[][]) {
    this.graph = new Graph();
    this.railLines = railLines;
  }

  // Get all the reachable squares from the current square
  // A square is not reachable if it is not accessible or it passes through another unit
  // Returns a set of strings
  getReachableSquares(currentSquare: string, isPieceEngineer: boolean, boardState: { [key: string]: Piece | null }): Set<string> {
    // If the piece is not on the railroad, it can only move one space
    if (!this.isOnRail(currentSquare)) {
      return this.graph.getAdjacentNeighbors(currentSquare);
    }

    const singleRail: Set<string> = this.getAllRailroadsFromSquare(currentSquare);

    // BFS search on the railroads
    const reachableSquares: string[] = [];
    const visited = new Set<string>();

    visited.add(currentSquare);
    reachableSquares.push(currentSquare);

    while (reachableSquares.length != 0) {
      const iterSquare: string = reachableSquares.shift()!;
      const allNeighbors: Set<string> = this.graph.getAdjacentNeighbors(iterSquare);
      const neighborsOnRailroad: string[] = Array.from(allNeighbors).filter((nextSquare) => this.isOnRail(nextSquare));

      neighborsOnRailroad.forEach(function(nextSquare) {
        if (visited.has(nextSquare)) {
          return;
        }

        // if the piece is not an engineer, check if it is on the same railroad
        if (isPieceEngineer === false && singleRail.has(nextSquare) === false) {
          // skip if not accessible without turning
          return;
        }

        // visited
        visited.add(nextSquare);

        // empty
        if (boardState[nextSquare] === null) {
          // explore this square and its neighbors
          reachableSquares.push(nextSquare);
        }
      });
    }

    // include squares that aren't on the railroad
    const neighbors: Set<string> = this.graph.getAdjacentNeighbors(currentSquare);
    neighbors.forEach(function(square: string) {
      visited.add(square);
    });

    return visited;
  }

  isOnRail(currentSquare: string): boolean {
    return this.railLines.some((railLine) => railLine.includes(currentSquare));
  }

  getAllRailroadsFromSquare(currentSquare: string): Set<string> {
    // get all positions that are accessible on the same railroad
    const singleRail: string[] = this.railLines
      .filter((railroad) => railroad.includes(currentSquare))
      .flat();
    return new Set(singleRail);
  }
}

import { describe, it } from 'node:test';
import { strict as assert } from 'assert';
import { Piece, PieceRank } from '../src/lib/Piece';
import { RailroadNetwork } from '../src/lib/RailroadNetwork';

describe('RailroadNetwork', function () {
  const RAIL1 = ['a2', 'a3', 'a4', 'a5', 'a6'];
  const RAIL2 = ['a2', 'b2', 'c2', 'd2', 'e2'];
  var railroadNetwork = new RailroadNetwork([RAIL1, RAIL2]);

  describe('#getReachableSquaresEngineer()', function () {
    it('Get reachable squares', function () {
      var currentSquare = "e2"
      var boardState = {"e2": new Piece("r", PieceRank.ENGINEER), "d2": null, "c2": null, "b2": null,
       "a2": null, "a3": null, "a4": null, "a5": new Piece("_", PieceRank.FLAG), "a6": null};
      var isPieceEngineer = true;

      var reachableSquares = railroadNetwork.getReachableSquares(currentSquare, isPieceEngineer, boardState);
      assert.equal(reachableSquares.size, 11);

      // modeled in graph class
      const adjacentNeighborsNotOnRailroad =  ['e1', 'e3', 'd3'];
      const neighborsOnRailroad = ['e2', 'd2', 'c2', 'b2', 'a2', 'a3', 'a4', 'a5'];
      const expectedNeighbors = neighborsOnRailroad.concat(adjacentNeighborsNotOnRailroad);
      expectedNeighbors.forEach(function(square) {
        assert.equal(reachableSquares.has(square), true);
      })
    });
  });

  describe('#getReachableSquaresNotEngineer()', function () {
    it('Get reachable squares', function () {
      var currentSquare = "e2"
      var boardState = {"e2": new Piece("r", PieceRank.ENGINEER), "d2": null, "c2": null, "b2": null,
       "a2": null, "a3": null, "a4": null, "a5": new Piece("_", PieceRank.FLAG), "a6": null};
      var isPieceEngineer = false;

      var reachableSquares = railroadNetwork.getReachableSquares(currentSquare, isPieceEngineer, boardState);
      assert.equal(reachableSquares.size, 8);

      // modeled in graph class
      const adjacentNeighborsNotOnRailroad =  ['e1', 'e3', 'd3'];
      const neighborsOnRailroad = ['e2', 'd2', 'c2', 'b2', 'a2'];
      const expectedNeighbors = neighborsOnRailroad.concat(adjacentNeighborsNotOnRailroad);
      expectedNeighbors.forEach(function(square) {
        assert.equal(reachableSquares.has(square), true);
      })
    });
  });


  describe('#getAllRailroadsFromSquareIntersection()', function () {
    it('Return all railroads from square as a flat list', function () {
      var singleRail = railroadNetwork.getAllRailroadsFromSquare("a2");
      assert.equal(singleRail.size, 9);
    });
  });

  describe('#getAllRailroadsFromSquareNotIntersection()', function () {
    it('Return all railroads from square as a flat list', function () {
      var singleRail = railroadNetwork.getAllRailroadsFromSquare("a4");
      assert.equal(singleRail.size, 5);
    });
  });

  describe('#isOnRail()', function () {
    it('Check if the square is on any railroad', function () {
      var result = railroadNetwork.isOnRail("a4");
      assert.equal(result, true);
    });
  });

  describe('#isNotOnRail()', function () {
    it('Check if the square is not on any railroad', function () {
      var result = railroadNetwork.isOnRail("e6");
      assert.equal(result, false);
    });
  });
});
